package com.flippingcopilot.model;

import org.junit.Test;

import java.util.Collections;

public class AccountStatusTest {
    private static final int ITEM_ID = 4151;

    @Test
    public void testMoreGpNeeded() {
        AccountStatus accountStatus = new AccountStatus();
        assert accountStatus.moreGpNeeded();
    }

    @Test
    public void testNoMoreGpNeeded() {
        AccountStatus accountStatus = new AccountStatus();
        accountStatus.getInventory().add(new RSItem(995, 2000));
        assert !accountStatus.moreGpNeeded();
    }

    @Test
    public void testBuyAndHoldModeDefaultsToTrue() {
        AccountStatus accountStatus = new AccountStatus();
        assert accountStatus.isBuyAndHold();
    }

    @Test
    public void testHasSufficientInventoryForSellSuggestionRequiresInventoryQuantity() {
        AccountStatus accountStatus = new AccountStatus();
        accountStatus.getInventory().add(new RSItem(ITEM_ID, 3));
        accountStatus.setBankAvailable(true);
        accountStatus.setBankInventory(Collections.singletonMap(ITEM_ID, 10));
        Suggestion suggestion = sellSuggestion(5);

        assert !accountStatus.hasSufficientInventoryForSellSuggestion(suggestion);
        assert !accountStatus.isCollectNeeded(suggestion, false);
    }

    @Test
    public void testHasSufficientInventoryForSellSuggestionWhenInventoryQuantityMatches() {
        AccountStatus accountStatus = new AccountStatus();
        accountStatus.getInventory().add(new RSItem(ITEM_ID, 5));
        Suggestion suggestion = sellSuggestion(5);

        assert accountStatus.hasSufficientInventoryForSellSuggestion(suggestion);
    }

    @Test
    public void testEncodeProtoIncludesBuyAndHoldAtField30() {
        AccountStatus accountStatus = new AccountStatus();
        accountStatus.setUncollected(Collections.emptyMap());

        byte[] payload = accountStatus.encodeProto(true, false);

        assert contains(payload, new byte[]{(byte) 0xF0, 0x01, 0x01});
        assert !contains(payload, new byte[]{(byte) 0xE8, 0x01, 0x01});
    }

    private static boolean contains(byte[] haystack, byte[] needle) {
        outer:
        for (int i = 0; i <= haystack.length - needle.length; i++) {
            for (int j = 0; j < needle.length; j++) {
                if (haystack[i + j] != needle[j]) {
                    continue outer;
                }
            }
            return true;
        }
        return false;
    }

    private static Suggestion sellSuggestion(int quantity) {
        Suggestion suggestion = new Suggestion();
        suggestion.setType(SuggestionType.SELL);
        suggestion.setItemId(ITEM_ID);
        suggestion.setQuantity(quantity);
        return suggestion;
    }
}

package com.flippingcopilot.model;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SuggestionTest {

    @Test
    public void onlyBuyDumpSuggestionsFlashHighlights() {
        assertTrue(suggestion(SuggestionType.BUY, true).isBuyDumpSuggestion());

        assertFalse(suggestion(SuggestionType.BUY, false).isBuyDumpSuggestion());
        assertFalse(suggestion(SuggestionType.MODIFY_BUY, true).isBuyDumpSuggestion());
        assertFalse(suggestion(SuggestionType.SELL, true).isBuyDumpSuggestion());
        assertFalse(suggestion(SuggestionType.MODIFY_SELL, true).isBuyDumpSuggestion());
        assertFalse(suggestion(SuggestionType.ABORT, true).isBuyDumpSuggestion());
    }

    private static Suggestion suggestion(SuggestionType type, boolean isDumpAlert) {
        Suggestion suggestion = new Suggestion();
        suggestion.setType(type);
        suggestion.setDumpAlert(isDumpAlert);
        return suggestion;
    }
}

package com.flippingcopilot.ui;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class UIUtilitiesTest {
    @Test
    public void truncateString_returnsOriginalString_whenLengthIsGreaterThanStringLength() {
        String result = UIUtilities.truncateString("Hello", 10);
        assertEquals("Hello", result);
    }

    @Test
    public void truncateString_returnsTruncatedString_whenLengthIsLessThanStringLength() {
        String result = UIUtilities.truncateString("Hello, World!", 5);
        assertEquals("Hello...", result);
    }

    @Test
    public void truncateString_returnsOriginalString_whenLengthIsEqualToStringLength() {
        String result = UIUtilities.truncateString("Hello", 5);
        assertEquals("Hello", result);
    }

    @Test
    public void truncateString_returnsEmptyString_whenInputStringIsEmpty() {
        String result = UIUtilities.truncateString("", 5);
        assertEquals("", result);
    }

    @Test
    public void truncateString_returnsTruncatedString_whenLengthIsZero() {
        String result = UIUtilities.truncateString("Hello, World!", 0);
        assertEquals("...", result);
    }

    @Test
    public void quantityToRSDecimalStack_largeNegativeValue_includesMinusSign() {
        String result = UIUtilities.quantityToRSDecimalStack(-15000, false);
        assertEquals("-15K", result);
    }

    @Test
    public void quantityToRSDecimalStack_smallNegativeValue_includesMinusSign() {
        String result = UIUtilities.quantityToRSDecimalStack(-406, false);
        assertEquals("-406", result);
    }

    @Test
    public void formatSuggestionDuration_roundsToNearestFiveMinutes_underAnHour() {
        String result = UIUtilities.formatSuggestionDuration(33 * 60);
        assertEquals("35min", result);
    }

    @Test
    public void formatSuggestionDuration_showsHoursAndMinutes_underOneDay() {
        String result = UIUtilities.formatSuggestionDuration((2 * 60 + 7) * 60);
        assertEquals("2h 5m", result);
    }

    @Test
    public void formatSuggestionDuration_showsDaysAndHours_whenAtLeastOneDay() {
        String result = UIUtilities.formatSuggestionDuration((26 * 60 + 29) * 60);
        assertEquals("1d 2h", result);
    }

    @Test
    public void formatSuggestionDuration_omitsHours_whenRoundedToWholeDay() {
        String result = UIUtilities.formatSuggestionDuration((23 * 60 + 58) * 60);
        assertEquals("1d", result);
    }
}

