package com.flippingcopilot.model;

import com.google.protobuf.CodedInputStream;
import com.google.protobuf.WireFormat;
import lombok.AllArgsConstructor;
import lombok.Getter;

import java.io.IOException;

/** The protobuf error body every v2 endpoint replies with on failure; its code mirrors the HTTP status. */
@Getter
@AllArgsConstructor
public class ApiError {

    private final int code;
    private final String displayErr;

    public static ApiError decodeProto(byte[] bytes) throws IOException {
        int code = 0;
        String displayErr = "";
        if (bytes == null || bytes.length == 0) {
            return new ApiError(code, displayErr);
        }
        CodedInputStream input = CodedInputStream.newInstance(bytes);
        while (!input.isAtEnd()) {
            int tag = input.readTag();
            if (tag == 0) {
                break;
            }
            switch (WireFormat.getTagFieldNumber(tag)) {
                case 1:
                    code = input.readInt32();
                    break;
                case 2:
                    displayErr = input.readString();
                    break;
                default:
                    input.skipField(tag);
            }
        }
        return new ApiError(code, displayErr);
    }
}

package com.flippingcopilot.model;

import com.flippingcopilot.controller.Persistance;
import com.google.gson.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.*;
import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;

@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SessionManager {

    public static final String SESSION_DATA_FILE_TEMPLATE = "%s_session_data.jsonl";

    private final OsrsLoginManager osrsLoginManager;
    private final ScheduledExecutorService executorService;
    private final Gson gson;

    private final Map<String, SessionData> cachedSessionData =  new HashMap<>();
    private final Map<String, File> displayNameToFile = new HashMap<>();

    private Instant lastSessionUpdateTime;

    public synchronized SessionData getCachedSessionData() {
        SessionData sd = getSessionData(osrsLoginManager.getPlayerDisplayName());
        return new SessionData(sd.startTime,  sd.durationMillis, sd.averageCash);
    }

    public synchronized void resetSession() {
        String displayName = osrsLoginManager.getPlayerDisplayName();
        SessionData sd = getSessionData(displayName);
        sd.startTime = (int) Instant.now().getEpochSecond();
        sd.averageCash = 0;
        sd.durationMillis = 0;
        saveAsync(displayName);
    }

    public synchronized boolean updateSessionStats(boolean currentlyFlipping, long cashStack) {
        String displayName = osrsLoginManager.getPlayerDisplayName();
        if (!currentlyFlipping || displayName == null) {
            lastSessionUpdateTime = null;
            return false;
        } else if (lastSessionUpdateTime == null) {
            lastSessionUpdateTime = Instant.now();
            return false;
        } else {
            SessionData sd = getSessionData(displayName);
            Instant now = Instant.now();
            long duration = Duration.between(lastSessionUpdateTime, now).toMillis();
            long newAverageCashStack = (cashStack * duration + sd.durationMillis * sd.averageCash) / (sd.durationMillis + duration);
            sd.durationMillis = sd.durationMillis + duration;
            lastSessionUpdateTime = now;
            sd.averageCash = newAverageCashStack;
            saveAsync(displayName);
            return true;
        }
    }

    private void saveAsync(String displayName) {
        executorService.submit(() -> {
            File file = getFile(displayName);
            synchronized (file) {
                SessionData data = cachedSessionData.computeIfAbsent(displayName, this::load);
                try (BufferedWriter writer = new BufferedWriter(new FileWriter(file, false))) {
                    String json = gson.toJson(data);
                    writer.write(json);
                    writer.newLine();
                } catch (IOException e) {
                    log.warn("error storing session data to file {}", file, e);
                }
            }
        });
    }

     private SessionData load(String displayName) {
        File file = getFile(displayName);
        if (!file.exists()) {
            return new SessionData((int) Instant.now().getEpochSecond(), 0 ,0);
        }
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            SessionData sd =  gson.fromJson(reader, SessionData.class);
            if (sd != null) {
                return sd;
            }
        } catch (JsonSyntaxException | JsonIOException | IOException e) {
            log.warn("error loading session data json file {}", file, e);
        }
        return new SessionData((int) Instant.now().getEpochSecond(), 0 ,0);
    }

    private File getFile(String displayName) {
        return displayNameToFile.computeIfAbsent(displayName,
                (k) -> new File(Persistance.COPILOT_DIR, String.format(SESSION_DATA_FILE_TEMPLATE, Persistance.hashDisplayName(displayName))));
    }

    private SessionData getSessionData(String displayName) {
         return cachedSessionData.computeIfAbsent(displayName, this::load);
    }

    public synchronized void reset() {
        lastSessionUpdateTime = null;
    }
}

package com.flippingcopilot.model;

import lombok.Value;

@Value
public class PortfolioItemCardData {
    int itemId;
    String itemName;
    int runeliteGeQuantity;
    int runeliteInventoryQuantity;
    int suggestionBankQuantity;
    int openFlipsCount;
    long postTaxSellUnitPrice;
    long unitBuyPrice;
    Long unrealizedUnitProfit;
    int heldMinutes;
    int portfolioQuantity; // quantity with portfolio_id 0 (COFLIP_PORTFOLIO) or 1 (PERSONAL_PORTFOLIO)

    public boolean isInPortfolio() {
        return portfolioQuantity > 0;
    }

    public int getPortfolioBankQuantity() {
        long quantityOutsideBank = Math.max(0L, runeliteGeQuantity)
                + Math.max(0L, runeliteInventoryQuantity);
        long bankPortfolioQuantity = Math.max(0L, (long) portfolioQuantity - quantityOutsideBank);
        return (int) Math.min(Math.max(0L, suggestionBankQuantity), bankPortfolioQuantity);
    }

    public boolean hasPortfolioQuantityInBank() {
        return getPortfolioBankQuantity() > 0;
    }

    public long inventoryTooltipUnrealizedProfit() {
        return ((long) runeliteInventoryQuantity + suggestionBankQuantity) * safeUnrealizedUnitProfit();
    }

    public long portfolioUnrealizedProfit() {
        return (long) portfolioQuantity * safeUnrealizedUnitProfit();
    }

    private long safeUnrealizedUnitProfit() {
        return unrealizedUnitProfit == null ? 0L : unrealizedUnitProfit;
    }

    public boolean isPartiallyInPortfolio() {
        return isInPortfolio() && portfolioQuantity < runeliteGeQuantity + runeliteInventoryQuantity + suggestionBankQuantity;
    }

    public int getNotInPortfolioQuantity() {
        int clientHeld = runeliteGeQuantity + runeliteInventoryQuantity + suggestionBankQuantity;
        return Math.max(0, clientHeld - portfolioQuantity);
    }
}

package com.flippingcopilot.model;
import com.google.protobuf.CodedInputStream;
import com.google.protobuf.WireFormat;
import lombok.*;
import lombok.extern.slf4j.Slf4j;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.UUID;

@Getter
@Setter
@AllArgsConstructor
@NoArgsConstructor
@EqualsAndHashCode
@ToString
@Slf4j
public class AckedTransaction {

    public static final int RAW_SIZE = 64;

    private UUID id;
    private UUID clientFlipId;
    private int accountId;
    private int time;
    private int itemId;
    private int quantity;
    private long price;
    private long amountSpent;

    public static AckedTransaction fromRaw(byte[] raw) {
        if (raw.length != RAW_SIZE) {
            throw new IllegalArgumentException("Raw data must be exactly " + RAW_SIZE + " bytes");
        }

        ByteBuffer b = ByteBuffer.wrap(raw);
        b.order(ByteOrder.BIG_ENDIAN);
        AckedTransaction transaction = new AckedTransaction();

        // Read UUID (16 bytes)
        long idMostSig = b.getLong();
        long idLeastSig = b.getLong();
        transaction.id = new UUID(idMostSig, idLeastSig);
        long clientFlipIdMostSig = b.getLong();
        long clientFlipIdLeastSig = b.getLong();
        transaction.clientFlipId = new UUID(clientFlipIdMostSig, clientFlipIdLeastSig);

        // Read primitive fields
        transaction.accountId = b.getInt();
        transaction.time = b.getInt();
        transaction.itemId = b.getInt();
        transaction.quantity = b.getInt();
        transaction.price = b.getLong();
        transaction.amountSpent = b.getLong();
        return transaction;
    }

    public byte[] toRaw() {
        ByteBuffer b = ByteBuffer.allocate(RAW_SIZE);
        b.order(ByteOrder.BIG_ENDIAN);
        b.putLong(id.getMostSignificantBits());
        b.putLong(id.getLeastSignificantBits());
        b.putLong(clientFlipId.getMostSignificantBits());
        b.putLong(clientFlipId.getLeastSignificantBits());
        b.putInt(accountId);
        b.putInt(time);
        b.putInt(itemId);
        b.putInt(quantity);
        b.putLong(price);
        b.putLong(amountSpent);
        return b.array();
    }

    public static byte[] listDecodeProto(byte[] bytes) {
        ByteArrayOutputStream rawTransactions = new ByteArrayOutputStream();
        if (bytes == null || bytes.length == 0) {
            return rawTransactions.toByteArray();
        }
        try {
            CodedInputStream input = CodedInputStream.newInstance(bytes);
            while (!input.isAtEnd()) {
                int tag = input.readTag();
                if (tag == 0) {
                    break;
                }
                if (WireFormat.getTagFieldNumber(tag) == 1) {
                    AckedTransaction transaction = decodeProto(input.readByteArray());
                    if (transaction != null) {
                        byte[] raw = transaction.toRaw();
                        rawTransactions.write(raw, 0, raw.length);
                    }
                } else {
                    input.skipField(tag);
                }
            }
        } catch (IOException | IllegalArgumentException e) {
            log.warn("failed decoding client transactions proto", e);
        }
        return rawTransactions.toByteArray();
    }

    private static AckedTransaction decodeProto(byte[] bytes) throws IOException {
        AckedTransaction transaction = new AckedTransaction();
        transaction.clientFlipId = new UUID(0L, 0L);
        CodedInputStream input = CodedInputStream.newInstance(bytes);
        while (!input.isAtEnd()) {
            int tag = input.readTag();
            if (tag == 0) {
                break;
            }
            switch (WireFormat.getTagFieldNumber(tag)) {
                case 1:
                    transaction.id = decodeUuid(input.readByteArray());
                    break;
                case 2:
                    transaction.clientFlipId = decodeUuid(input.readByteArray());
                    break;
                case 3:
                    transaction.accountId = input.readInt32();
                    break;
                case 4:
                    transaction.time = input.readInt32();
                    break;
                case 5:
                    transaction.itemId = input.readInt32();
                    break;
                case 6:
                    transaction.quantity = input.readInt32();
                    break;
                case 11:
                    transaction.price = input.readInt64();
                    break;
                case 12:
                    transaction.amountSpent = input.readInt64();
                    break;
                default:
                    input.skipField(tag);
            }
        }
        return transaction;
    }

    private static UUID decodeUuid(byte[] bytes) throws IOException {
        if (bytes.length != 16) {
            throw new IOException("UUID data must be exactly 16 bytes");
        }
        ByteBuffer b = ByteBuffer.wrap(bytes).order(ByteOrder.BIG_ENDIAN);
        return new UUID(b.getLong(), b.getLong());
    }
}

