package com.flippingcopilot.model;

import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumSet;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class OsrsLoginManager {

    public static final int GE_LOGIN_BURST_WINDOW = 2; // ticks

    public static String LOGIN_TO_GET_SUGGESTION_MESSAGE = "Log in to the game<br>to get a flip suggestion";
    private static final WorldType[] COPILOT_UNSUPPORTED_WORLDS = {WorldType.BETA_WORLD,
            WorldType.DEADMAN,
            WorldType.FRESH_START_WORLD,
            WorldType.NOSAVE_MODE,
            WorldType.PVP_ARENA,
            WorldType.SEASONAL,
            WorldType.QUEST_SPEEDRUNNING,
            WorldType.TOURNAMENT_WORLD};

    private final Client client;

    private String cachedDisplayName;
    private long lastAccountHash;

    @Getter
    @Setter
    private int lastLoginTick;

    private boolean lastIsIronman = false;

    public boolean isMembersWorld() {
        return client.getWorldType().contains(WorldType.MEMBERS);
    }

    public boolean isAccountMember()
    {
        int daysLeft = client.getVarpValue(VarPlayer.MEMBERSHIP_DAYS);
        return daysLeft > 0;
    }

    public boolean isValidLoginState() {
        return getInvalidStateDisplayMessage() == null;
    }

    public String getInvalidStateDisplayMessage() {
        if (client.getGameState() != GameState.LOGGED_IN || getPlayerDisplayName() == null) {
            return LOGIN_TO_GET_SUGGESTION_MESSAGE;
        }

        WorldType unsupportedWorldType = getUnsupportedWorldType();
        if (unsupportedWorldType != null) {
            return unsupportedWorldType + " worlds<br>are not supported";
        }
        if(client.isClientThread()) {
            lastIsIronman = client.getVarbitValue(Varbits.ACCOUNT_TYPE) != 0;
        }
        if (lastIsIronman) {
            return "Ironman accounts<br>are not supported";
        }
        return null;
    }

    // todo: inline this method
    public Long getAccountHash() {
        return client.getAccountHash();
    }

    public String getPlayerDisplayName() {
        long accountHash = client.getAccountHash();
        if(lastAccountHash == accountHash && cachedDisplayName != null) {
            return cachedDisplayName;
        }
        final Player player = client.getLocalPlayer();
        if (player != null) {
            final String name = player.getName();
            if (name != null && !name.isEmpty()) {
                lastAccountHash = accountHash;
                cachedDisplayName = name;
                return name;
            }
        }
        return null;
    }

    public String getLastDisplayName() {
        return cachedDisplayName != null ? cachedDisplayName : getPlayerDisplayName();
    }

    public boolean isUnsupportedWorldType() {
        return getUnsupportedWorldType() != null;
    }

    public WorldType getUnsupportedWorldType() {
        EnumSet<WorldType> worldTypes = client.getWorldType();
        for (WorldType worldType : COPILOT_UNSUPPORTED_WORLDS) {
            if (worldTypes.contains(worldType)) {
                return worldType;
            }
        }
        return null;
    }

    public void reset() {

    }

    public boolean hasJustLoggedIn() {
        return client.getTickCount() <= lastLoginTick + GE_LOGIN_BURST_WINDOW;
    }
}

package com.flippingcopilot.model;

import net.runelite.api.*;
import net.runelite.api.ItemID;
import static com.flippingcopilot.util.Constants.PLATINUM_TOKEN_VALUE;

import java.util.ArrayList;
import java.util.Map;
import java.util.stream.Collectors;


public class Inventory extends ArrayList<RSItem> {

    boolean hasSufficientGp(Suggestion suggestion) {
        return suggestion.getType() != SuggestionType.BUY
                || getTotalGp() >= (long) suggestion.getPrice() * suggestion.getQuantity();
    }

    public long getTotalGp() {
        return getTotalAmount(ItemID.COINS_995) + PLATINUM_TOKEN_VALUE * getTotalAmount(ItemID.PLATINUM_TOKEN);
    }

    public long getTotalAmount(long itemId) {
        long amount = 0;
        for (RSItem item : this) {
            if (item.getId() == itemId) {
                amount += item.getAmount();
            }
        }
        return amount;
    }


    public static Inventory fromRunelite(ItemContainer inventory, Client client) {
        Inventory unnotedItems = new Inventory();
        if (inventory == null) {
            return unnotedItems;
        }
        Item[] items = inventory.getItems();
        for (Item item : items) {
            if (item.getId() == -1) {
                continue;
            }
            unnotedItems.add(RSItem.getUnnoted(item, client));
        }
        return unnotedItems;
    }

    public Map<Integer, Long> getItemAmounts() {
        return stream().collect(Collectors.groupingBy(RSItem::getId,
                        Collectors.summingLong(RSItem::getAmount)));
    }

    public void mergeItem(RSItem i) {
        for(RSItem item : this) {
            if(item.id == i.id) {
                item.amount += i.amount;
                return;
            }
        }
        add(i);
    }

     public boolean missingJustCollected( Map<Integer, Long> inLimboItems) {
         for (Map.Entry<Integer, Long> entry : inLimboItems.entrySet()) {
             Integer itemId = entry.getKey();
             Long qty = entry.getValue();
             if (qty > 0) {
                 long inventoryQty = getTotalAmount(itemId);
                 if (inventoryQty < qty) {
                     return true;
                 }
             }
         }
         return false;
    }
}

package com.flippingcopilot.model;

import com.flippingcopilot.util.ProtoUtils;
import com.google.gson.annotations.SerializedName;
import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;


@Slf4j
@Getter
@AllArgsConstructor
@EqualsAndHashCode
public class Offer {

    @Setter
    private OfferStatus status;

    @SerializedName("item_id")
    private int itemId;

    private long price;

    @SerializedName("amount_total")
    private int amountTotal;

    @SerializedName("amount_spent")
    private long amountSpent;

    @SerializedName("amount_traded")
    private int amountTraded;

    @SerializedName("box_id")
    private int boxId;

    private boolean active;

    @Setter
    @SerializedName("copilot_price_used")
    private boolean copilotPriceUsed;

    public static Offer getEmptyOffer(int slotId) {
        return new Offer(OfferStatus.EMPTY, 0, 0, 0, 0, 0, slotId, false, false);
    }


    public long cashStackGpValue() {
        if (status == OfferStatus.SELL) {
            return (long) (amountTotal - amountTraded) * price;
        } else if (status == OfferStatus.BUY){
            // for a buy just take the full amount even if they have collected
            // we assume they won't start selling any collected items until their buy offer is finished
            return (long) amountTotal * price;
        } else {
            return 0;
        }
    }


    public static Offer fromRunelite(GrandExchangeOffer runeliteOffer, int slotId) {
        OfferStatus status = OfferStatus.fromRunelite(runeliteOffer.getState());
        boolean active = runeliteOffer.getState().equals(GrandExchangeOfferState.BUYING)
                || runeliteOffer.getState().equals(GrandExchangeOfferState.SELLING);
        return new Offer(status,
                runeliteOffer.getItemId(),
                runeliteOffer.getPrice(),
                runeliteOffer.getTotalQuantity(),
                runeliteOffer.getSpent(),
                runeliteOffer.getQuantitySold(),
                slotId,
                active,
                false);
    }


    byte[] encodeProto() {
        try {
            return ProtoUtils.encodeMessage(out -> {
                out.writeInt32(1, boxId);
                out.writeInt32(2, itemId);
                out.writeInt64(3, price);
                out.writeInt64(4, amountTotal);
                out.writeInt64(5, amountTraded);
                out.writeInt32(6, status == null ? 0 : status.protoInt());
                out.writeBool(7, active);
                out.writeInt64(8, amountSpent);
                out.writeBool(9, copilotPriceUsed);
            });
        } catch (RuntimeException e) {
            log.warn("failed to encode offer proto, boxId={}, itemId={}", boxId, itemId, e);
            return new byte[0];
        }
    }

}

package com.flippingcopilot.model;

import com.google.protobuf.CodedInputStream;
import com.google.protobuf.WireFormat;
import com.google.gson.annotations.SerializedName;
import lombok.AllArgsConstructor;
import lombok.Data;

import java.io.IOException;

@Data
@AllArgsConstructor
public class LoginResponse {
    public String jwt;

    @SerializedName("user_id")
    public int userId;

    public String error;

    public static LoginResponse decodeProto(byte[] bytes) throws IOException {
        LoginResponse response = new LoginResponse("", 0, null);
        CodedInputStream input = CodedInputStream.newInstance(bytes);
        while (!input.isAtEnd()) {
            int tag = input.readTag();
            if (tag == 0) {
                break;
            }
            switch (WireFormat.getTagFieldNumber(tag)) {
                case 2:
                    response.jwt = input.readString();
                    break;
                case 3:
                    response.userId = input.readInt32();
                    break;
                default:
                    input.skipField(tag);
            }
        }
        return response;
    }

    public static LoginResponse decodeDiscordLoginResult(byte[] bytes) throws IOException {
        LoginResponse response = new LoginResponse("", 0, null);
        if (bytes.length == 0) {
            response.error = "Login failed (no response from server)";
            return response;
        }
        CodedInputStream input = CodedInputStream.newInstance(bytes);
        while (!input.isAtEnd()) {
            int tag = input.readTag();
            if (tag == 0) {
                break;
            }
            switch (WireFormat.getTagFieldNumber(tag)) {
                case 1:
                    response.jwt = input.readString();
                    break;
                case 2:
                    response.userId = input.readInt32();
                    break;
                case 3:
                    response.error = input.readString();
                    break;
                default:
                    input.skipField(tag);
            }
        }
        return response;
    }
}

package com.flippingcopilot.model;

import com.flippingcopilot.controller.ApiRequestHandler;
import com.flippingcopilot.controller.Persistance;
import com.flippingcopilot.rs.CopilotLoginRS;
import com.flippingcopilot.util.MutableReference;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

import static com.flippingcopilot.util.FormatUtil.formatDurationSince;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class TransactionManager {

    // dependencies
    private final FlipManager flipManager;
    private final ScheduledExecutorService executorService;
    private final ApiRequestHandler api;
    private final CopilotLoginRS copilotLoginRS;
    private final OsrsLoginManager osrsLoginManager;

    // state
    private final ConcurrentMap<String, List<Transaction>> cachedUnAckedTransactions = new ConcurrentHashMap<>();
    private final ConcurrentMap<String, AtomicBoolean> transactionSyncScheduled = new ConcurrentHashMap<>();

    public void syncUnAckedTransactions(String displayName) {

        long s = System.nanoTime();
        List<Transaction> toSend;
        synchronized (this) {
            toSend = new ArrayList<>(getUnAckedTransactions(displayName));
            if(toSend.isEmpty()) {
                transactionSyncScheduled.get(displayName).set(false);
                return;
            }
        }

        BiConsumer<Integer, List<FlipV2>> onSuccess = (userId, flips) -> {
            if(!flips.isEmpty()) {
                copilotLoginRS.addAccountIfMissing(flips.get(0).getAccountId(), displayName, userId);
            }
            flipManager.mergeFlips(flips, userId);
            log.info("sending {} transactions took {}", toSend.size(), formatDurationSince(s));
            synchronized (this) {
                List<Transaction> unAckedTransactions  = getUnAckedTransactions(displayName);
                transactionSyncScheduled.get(displayName).set(false);
                toSend.forEach(unAckedTransactions::remove);
                if(!unAckedTransactions.isEmpty()) {
                    scheduleSyncIn(0, displayName);
                }
            }
        };

        Consumer<HttpResponseException> onFailure = (e) -> {
            synchronized (this) {
                transactionSyncScheduled.get(displayName).set(false);
            }
            String currentDisplayName = osrsLoginManager.getPlayerDisplayName();
            if (copilotLoginRS.get().isLoggedIn() && (currentDisplayName == null || currentDisplayName.equals(displayName))) {
                log.warn("failed to send transactions to copilot server {}", e.getMessage(), e);
                scheduleSyncIn(10, displayName);
            }
        };
        api.sendTransactionsAsync(toSend, displayName, onSuccess, onFailure);
    }

    public long addTransaction(Transaction transaction, String displayName) {
        if (osrsLoginManager.isUnsupportedWorldType()) {
            log.debug("ignoring transaction for {} on unsupported world type(s)", displayName);
            return 0;
        }
        synchronized (this) {
            List<Transaction> unAckedTransactions = getUnAckedTransactions(displayName);
            unAckedTransactions.add(transaction);
            Persistance.storeUnAckedTransactions(unAckedTransactions, displayName);
        }
        MutableReference<Long> profit = new MutableReference<>(0L);
        if (OfferStatus.SELL.equals(transaction.getType())) {
            Integer accountId = copilotLoginRS.get().getAccountId(displayName);
            if (accountId != null && accountId != -1) {
                Long p = flipManager.estimateTransactionProfit(accountId, transaction);
                if (p != null) {
                    profit.setValue(p);
                }
            }
        }
        if (copilotLoginRS.get().isLoggedIn()) {
            scheduleSyncIn(0, displayName);
        }
        return profit.getValue();
    }

    public List<Transaction> getUnAckedTransactions(String displayName) {
        return cachedUnAckedTransactions.computeIfAbsent(displayName, (k) -> Persistance.loadUnAckedTransactions(displayName));
    }

    public synchronized void scheduleSyncIn(int seconds, String displayName) {
        AtomicBoolean scheduled = transactionSyncScheduled.computeIfAbsent(displayName, k -> new AtomicBoolean(false));
        if(scheduled.compareAndSet(false, true)) {
            log.info("scheduling {} attempt to sync {} transactions in {}s", displayName, getUnAckedTransactions(displayName).size(), seconds);
            executorService.schedule(() ->  {
                this.syncUnAckedTransactions(displayName);
            }, seconds, TimeUnit.SECONDS);
        } else {
            log.debug("skipping scheduling sync as already scheduled");
        }
    }
}

package com.flippingcopilot.model;

import lombok.Getter;
import lombok.Setter;

import javax.inject.Singleton;
import java.time.Instant;

@Singleton
@Getter
@Setter
public class SuggestionManager {

    private volatile boolean suggestionNeeded;
    private volatile boolean suggestionRequestInProgress;
    private volatile boolean graphDataReadingInProgress;
    private volatile boolean suggestionRefreshPending;
    private Instant lastFailureAt;
    private HttpResponseException suggestionError;
    private Suggestion suggestion;
    private Instant suggestionReceivedAt;
    private int lastOfferSubmittedTick = -1;

    // these two variables get set based on the current suggestion when the confirm offer button is clicked.
    // this allows us to track on the subsequent offer events whether the offer originates from a copilot suggestion
    // this flag can then eventually be propagated onto each transaction and can be used by the server to
    // determine which items in the inventory were bought based upon copilot suggestions and which are not
    private int suggestionItemIdOnOfferSubmitted = -1;
    private OfferStatus suggestionOfferStatusOnOfferSubmitted = null;


    public volatile int suggestionsDelayedUntil = 0;

    public void setSuggestion(Suggestion suggestion) {
        this.suggestion = suggestion;
        suggestionReceivedAt = Instant.now();

    }

    public void setSuggestionError(HttpResponseException error) {
        this.suggestionError = error;
        lastFailureAt= Instant.now();
    }

    public void reset() {
        suggestionNeeded = false;
        suggestionRefreshPending = false;
        suggestion = null;
        suggestionReceivedAt = null;
        lastFailureAt = null;
        lastOfferSubmittedTick = -1;
        suggestionError = null;
        suggestionItemIdOnOfferSubmitted = -1;
        suggestionOfferStatusOnOfferSubmitted = null;
    }

    public boolean suggestionOutOfDate() {
        Instant tenSecondsAgo = Instant.now().minusSeconds(10L);
        if (suggestionReceivedAt == null || tenSecondsAgo.isAfter(suggestionReceivedAt)) {
            return lastFailureAt == null || tenSecondsAgo.isAfter(lastFailureAt);
        }
        return false;
    }

    public boolean suggestionVeryOutOfDate() {
        return suggestionReceivedAt != null && Instant.now().minusSeconds(60L).isAfter(suggestionReceivedAt);
    }
}

package com.flippingcopilot.model;
import com.flippingcopilot.util.Constants;
import com.flippingcopilot.util.ProtoUtils;
import com.google.protobuf.CodedOutputStream;
import lombok.Data;
import lombok.extern.slf4j.Slf4j;

import java.util.*;


// note: we synchronize all public methods of this class as they read/modify its state and may
// be called by multiple threads at the same time

@Slf4j
@Data
public class AccountStatus {

    private final int version = 100;

    private StatusOfferList offers;
    private Inventory inventory;
    private Map<Integer, Long> uncollected;
    private boolean isWorldMember = false;
    private boolean isAccountMember = false;
    private int skipSuggestion = -1;
    private String displayName;
    private Boolean suggestionsPaused;
    private boolean sellOnlyMode = false;
    private boolean buyAndHold = true;
    private boolean f2pOnlyMode = false;
    private List<Integer> blockedItems;
    private int timeframe = 5; // Default to 5 minutes
    private RiskLevel riskLevel = RiskLevel.MEDIUM;
    private Integer reservedSlots;
    private Long minPredictedProfit;
    private Long dumpMinPredictedProfit;

    private Map<Integer, Integer> bankInventory;
    private boolean bankAvailable;
    private List<Integer> syncExcluded;
    private boolean allowedSync;
    private Map<Integer, Integer> bagInventory;

    public AccountStatus() {
        offers = new StatusOfferList();
        inventory = new Inventory();
    }

    public synchronized boolean isCollectNeeded(Suggestion suggestion, boolean setUpOfferOpen) {
        if (!suggestion.isDumpAlert() && !setUpOfferOpen
                && SuggestionType.WAIT.equals(suggestion.getType()) && offers.reservedSlotNeeded(isWorldMember || isAccountMember, resolveReservedSlots(), suggestion))  {
            log.debug("collected needed reservedSlotNeeded");
            return true;
        }
        if (offers.isEmptySlotNeeded(suggestion, isWorldMember || isAccountMember)) {
            log.debug("collected needed isEmptySlotNeeded");
            return true;
        }
        if (suggestion.isModifySuggestion() || suggestion.isAbortSuggestion()) {
            return false;
        }
        if (!inventory.hasSufficientGp(suggestion)) {
            log.debug("collected needed hasSufficientGp");
            return true;
        }
        if (!hasSufficientItemsForSuggestion(suggestion)) {
            if (hasSufficientCollectibleItemsForSuggestion(suggestion)) {
                log.debug("collected needed hasSufficientItems");
                return true;
            }
        }
        return false;
    }

    public synchronized boolean hasSufficientInventoryForSellSuggestion(Suggestion suggestion) {
        return suggestion != null
                && suggestion.isSellSuggestion()
                && inventory != null
                && inventory.getTotalAmount(suggestion.getItemId()) >= suggestion.getQuantity();
    }

    public synchronized boolean shouldSellFromBank(Suggestion suggestion) {
        if (suggestion == null || !suggestion.isSellSuggestion() || suggestion.isModifySuggestion()) {
            return false;
        }
        if (inventory == null || hasSufficientInventoryForSellSuggestion(suggestion)) {
            return false;
        }
        return getBankQuantity(suggestion) > 0;
    }

    private long getBankQuantity(Suggestion suggestion) {
        if (bankAvailable && bankInventory != null) {
            return Math.max(0, bankInventory.getOrDefault(suggestion.getItemId(), 0));
        }
        if (suggestion.getBankItems() == null) {
            return 0;
        }
        return Math.max(0, suggestion.getBankItems().getOrDefault(suggestion.getItemId(), 0));
    }

    private boolean hasSufficientItemsForSuggestion(Suggestion suggestion) {
        if (!suggestion.isSellSuggestion()) {
            return true;
        }

        if (hasSufficientInventoryForSellSuggestion(suggestion)) {
            return true;
        }

        if (!bankAvailable || bankInventory == null) {
            return false;
        }

        long inventoryQty = inventory.getTotalAmount(suggestion.getItemId());
        long bankQty = Math.max(0, bankInventory.getOrDefault(suggestion.getItemId(), 0));
        return inventoryQty + bankQty >= suggestion.getQuantity();
    }

    private boolean hasSufficientCollectibleItemsForSuggestion(Suggestion suggestion) {
        if (suggestion == null || !suggestion.isSellSuggestion() || uncollected == null) {
            return false;
        }

        long inventoryQty = inventory == null ? 0 : inventory.getTotalAmount(suggestion.getItemId());
        long bankQty = 0;
        if (bankAvailable && bankInventory != null) {
            bankQty = Math.max(0, bankInventory.getOrDefault(suggestion.getItemId(), 0));
        }

        long collectibleQty = Math.max(0, uncollected.getOrDefault(suggestion.getItemId(), 0L));
        long missingQty = suggestion.getQuantity() - inventoryQty - bankQty;
        return missingQty > 0 && collectibleQty >= missingQty;
    }

    public int findEmptySlot() {
        return getOffers().findEmptySlot(isWorldMember || isAccountMember);
    }

    private Map<Integer, Long> computeInventory() {
        Map<Integer, Long> itemAmounts = inventory.getItemAmounts();
        uncollected.forEach((key, value) -> itemAmounts.merge(key, value, Long::sum));
        itemAmounts.entrySet().removeIf(entry -> entry.getValue() == 0);
        return itemAmounts;
    }

    public synchronized boolean moreGpNeeded() {
        return emptySlotExists() && getTotalGp() < Constants.MIN_GP_NEEDED_TO_FLIP;
    }

    public synchronized boolean emptySlotExists() {
        return offers.emptySlotExists(isWorldMember || isAccountMember);
    }

    private long getTotalGp() {
        return inventory.getTotalGp();
    }

    public synchronized boolean currentlyFlipping() {
        return offers.stream().anyMatch(Offer::isActive);
    }

    public synchronized long currentCashStack() {
        // the cash stack is the gp in their inventory + the value on the market
        // todo: when a buy offer has fully finished its value will not count towards the cash stack
        //  size until they start selling it. We should probably track items that where recently bought
        //  and they should still count towards the cash stack size for some period of time
        return offers.getGpOnMarket() + inventory.getTotalGp();
    }

    private Set<SuggestionType> resolveRequestedSuggestionTypes(boolean geOpen) {
        Set<SuggestionType> requestedSuggestionTypes = SuggestionType.abortAndModifyTypes();
        requestedSuggestionTypes.add(SuggestionType.SELL);
        if (geOpen && !sellOnlyMode) {
            requestedSuggestionTypes.add(SuggestionType.BUY);
        }
        return requestedSuggestionTypes;
    }

    private int resolveReservedSlots() {
        return reservedSlots == null ? 0 : reservedSlots;
    }

    public synchronized byte[] encodeProto( boolean geOpen, boolean sendGraphData) {
        return ProtoUtils.encodeMessage(out -> {
            out.writeInt32(8, version);
            if (displayName != null && !displayName.isEmpty()) {
                out.writeString(1, displayName);
            }
            out.writeBool(2, sellOnlyMode);
            out.writeBool(3, isWorldMember);
            out.writeBool(4, isAccountMember);
            out.writeInt32(5, skipSuggestion);

            if (offers != null) {
                for (Offer offer : offers) {
                    if (offer == null) {
                        continue;
                    }
                    byte[] offerBytes = offer.encodeProto();
                    if (offerBytes.length == 0) {
                        continue;
                    }
                    ProtoUtils.writeDelimitedMessageField(out, 6, offerBytes);
                }
            }

            Map<Integer, Long> protoInventory = computeInventory();
            ProtoUtils.writeMap(out, 7, protoInventory, CodedOutputStream::writeInt32, CodedOutputStream::writeInt64);

            out.writeBool(11, f2pOnlyMode);
            ProtoUtils.writePacked(out, 12, blockedItems, CodedOutputStream::writeInt32NoTag);

            Set<SuggestionType> requestedSuggestionTypes = resolveRequestedSuggestionTypes(geOpen);
            List<Integer> requestedSuggestionTypeInts = new java.util.ArrayList<>(requestedSuggestionTypes.size());
            for (SuggestionType suggestionType : requestedSuggestionTypes) {
                requestedSuggestionTypeInts.add(suggestionType.protoInt());
            }
            ProtoUtils.writePacked(out, 13, requestedSuggestionTypeInts, CodedOutputStream::writeInt32NoTag);

            out.writeBool(14, sendGraphData);

            out.writeDouble(15, timeframe);
            RiskLevel effectiveRiskLevel = riskLevel == null ? RiskLevel.MEDIUM : riskLevel;
            out.writeInt32(16, effectiveRiskLevel.protoInt());
            if (reservedSlots != null) {
                out.writeInt32(17, reservedSlots);
            }
            if (minPredictedProfit != null) {
                out.writeInt64(34, minPredictedProfit);
            }
            if (dumpMinPredictedProfit != null) {
                out.writeInt64(35, dumpMinPredictedProfit);
            }

            ProtoUtils.writeMap(
                    out,
                    20,
                    bankInventory,
                    CodedOutputStream::writeInt32,
                    CodedOutputStream::writeInt32
            );
            out.writeBool(21, bankAvailable);

            if (suggestionsPaused != null) {
                out.writeBool(28, suggestionsPaused);
            }
            out.writeBool(30, buyAndHold);
            ProtoUtils.writePacked(out, 31, syncExcluded, CodedOutputStream::writeInt32NoTag);
            out.writeBool(32, allowedSync);
            ProtoUtils.writeMap(
                    out,
                    33,
                    bagInventory,
                    CodedOutputStream::writeInt32,
                    CodedOutputStream::writeInt32
            );
        });
    }
}

