package com.flippingcopilot.model;

import lombok.*;
import net.runelite.api.*;
import net.runelite.api.gameval.VarbitID;

import java.util.EnumSet;


@NoArgsConstructor
@AllArgsConstructor
@Builder(toBuilder = true)
@EqualsAndHashCode
@ToString
public class OsrsLoginState {

    public boolean loggedIn;

    // These are not cleared on log out so the last values can still be accessed.
    public boolean isIronMan;
    public EnumSet<WorldType> worldTypes;
    public String displayName;
    public Long accountHash;

    public OsrsLoginState nextState(Client client) {
        if(client.getGameState() == GameState.LOGGED_IN) {
            Player p = client.getLocalPlayer();
            return OsrsLoginState.builder()
                    .loggedIn(true)
                    .isIronMan(client.getVarbitValue(VarbitID.IRONMAN) > 0)
                    .worldTypes(client.getWorldType())
                    .displayName(p == null ? null : p.getName())
                    .accountHash(client.getAccountHash())
                    .build();
        } else {
            return this.toBuilder().loggedIn(false).build();
        }
    }
}

package com.flippingcopilot.model;

import com.flippingcopilot.ui.graph.model.Data;
import com.flippingcopilot.util.ProtoUtils;
import com.google.protobuf.CodedInputStream;
import com.google.protobuf.WireFormat;
import com.google.gson.annotations.SerializedName;
import lombok.*;
import lombok.extern.slf4j.Slf4j;

import java.text.NumberFormat;
import java.time.Instant;
import java.io.IOException;
import java.util.*;

@Setter
@Getter
@AllArgsConstructor
@ToString
@NoArgsConstructor
@Slf4j
public class Suggestion {
    private SuggestionType type;
    private int boxId;
    private int itemId;
    private long price;
    private int quantity;
    private String name;
    private int id;
    private String message = "";
    private Double expectedProfit;
    private Double expectedDuration;
    @SerializedName("is_hold")
    private boolean isHold;
    private Map<Integer, Integer> bankItems;
    private List<PortfolioItem> portfolioItems;
    private Data graphData;
    private Instant timeIssued;

    @Setter
    @Getter
    @AllArgsConstructor
    @NoArgsConstructor
    public static class PortfolioItem {
        public int itemId;

        // Per-portfolio breakdowns. Only portfolio_id 0 (COFLIP_PORTFOLIO) and 1 (PERSONAL_PORTFOLIO)
        // count as "in portfolio" (getAmount / getSellValue / getBuySpend / getHeldMinutes).
        // Ghost (portfolio_id -1) is tracked separately and excluded from those totals; it only
        // surfaces as a fallback when computing per-unit market prices for items the user holds
        // client-side but has no visible portfolio/personal entry for.
        public int portfolioAmount;
        public long portfolioSellValue;
        public long portfolioBuySpend;
        public int portfolioHeldMinutes;
        public int personalAmount;
        public long personalSellValue;
        public long personalBuySpend;
        public int personalHeldMinutes;
        public int ghostAmount;
        public long ghostSellValue;
        public long ghostBuySpend;
        public int ghostHeldMinutes;

        public int getAmount() {
            return portfolioAmount + personalAmount;
        }

        public long getSellValue() {
            return portfolioSellValue + personalSellValue;
        }

        public long getBuySpend() {
            return portfolioBuySpend + personalBuySpend;
        }

        public int getHeldMinutes() {
            return Math.max(portfolioHeldMinutes, personalHeldMinutes);
        }

        public long getPostTaxSellUnitPrice() {
            int amt = getAmount();
            if (amt > 0) {
                return getSellValue() / amt;
            }
            if (ghostAmount > 0) {
                return ghostSellValue / ghostAmount;
            }
            return 0L;
        }

        public long getUnitBuyPrice() {
            int amt = getAmount();
            if (amt > 0) {
                return getBuySpend() / amt;
            }
            if (ghostAmount > 0) {
                return ghostBuySpend / ghostAmount;
            }
            return 0L;
        }

        public static PortfolioItem decodeProto(CodedInputStream input) throws IOException {
            PortfolioItem item = new PortfolioItem();
            while (!input.isAtEnd()) {
                int tag = input.readTag();
                if (tag == 0) {
                    break;
                }
                int field = WireFormat.getTagFieldNumber(tag);
                switch (field) {
                    case 1:
                        item.itemId = input.readInt32();
                        break;
                    case 7:
                        item.portfolioAmount = input.readInt32();
                        break;
                    case 8:
                        item.portfolioSellValue = input.readInt64();
                        break;
                    case 9:
                        item.portfolioBuySpend = input.readInt64();
                        break;
                    case 10:
                        item.portfolioHeldMinutes = input.readInt32();
                        break;
                    case 11:
                        item.personalAmount = input.readInt32();
                        break;
                    case 12:
                        item.personalSellValue = input.readInt64();
                        break;
                    case 13:
                        item.personalBuySpend = input.readInt64();
                        break;
                    case 14:
                        item.personalHeldMinutes = input.readInt32();
                        break;
                    case 15:
                        item.ghostAmount = input.readInt32();
                        break;
                    case 16:
                        item.ghostSellValue = input.readInt64();
                        break;
                    case 17:
                        item.ghostBuySpend = input.readInt64();
                        break;
                    case 18:
                        item.ghostHeldMinutes = input.readInt32();
                        break;
                    default:
                        // Skips deprecated legacy aggregates (2-6).
                        input.skipField(tag);
                }
            }
            return item;
        }
    }

    public volatile Instant dumpAlertReceived = Instant.now();
    public volatile boolean isDumpAlert;
    public volatile int actionedTick = -1;


    public boolean equals(Suggestion other) {
        return this.type == other.type
                && this.itemId == other.itemId
                && this.name.equals(other.name);
    }

    public boolean isWaitSuggestion() {
        return type == SuggestionType.WAIT;
    }

    public boolean isAbortSuggestion() {
        return type == SuggestionType.ABORT;
    }

    public boolean isBuySuggestion() {
        return type == SuggestionType.BUY || type == SuggestionType.MODIFY_BUY;
    }

    public boolean isSellSuggestion() {
        return type == SuggestionType.SELL || type == SuggestionType.MODIFY_SELL;
    }

    public boolean isModifySuggestion() {
        return type == SuggestionType.MODIFY_BUY || type == SuggestionType.MODIFY_SELL;
    }

    public String offerType() {
        if (isBuySuggestion()) {
            return "buy";
        }
        if (isSellSuggestion()) {
            return "sell";
        }
        return null;
    }

    public boolean isRecentUnActionedDumpAlert() {
        return isDumpAlert && actionedTick == -1 && dumpAlertReceived.isAfter(Instant.now().minusSeconds(10));
    }

    public boolean isBuyDumpSuggestion() {
        return isDumpAlert && type == SuggestionType.BUY;
    }

    public String toMessage() {
        NumberFormat formatter = NumberFormat.getNumberInstance();
        String string = isDumpAlert ? "DUMP ALERT!! " : "Flipping Copilot: ";
        if (type == null) {
            return string + "Unknown suggestion type";
        }
        switch (type) {
            case BUY:
                string += String.format("%s %s %s for %s gp",
                        isHold ? "Buy and hold" : "Buy",
                        formatter.format(quantity), name, formatter.format(price));
                break;
            case MODIFY_BUY:
                string += String.format("Modify buy offer for %s %s to %s gp",
                        formatter.format(quantity), name, formatter.format(price));
                break;
            case SELL:
                string += String.format("Sell %s %s for %s gp",
                        formatter.format(quantity), name, formatter.format(price));
                break;
            case MODIFY_SELL:
                string += String.format("Modify sell offer for %s %s to %s gp",
                        formatter.format(quantity), name, formatter.format(price));
                break;
            case ABORT:
                string += "Abort " + name;
                break;
            case WAIT:
                string += "Wait";
                break;
            default:
                string += "Unknown suggestion type";
                break;
        }
        return string;
    }

    public static Suggestion decodeProto(byte[] bytes) {
        if (bytes == null || bytes.length == 0) {
            return null;
        }

        Suggestion suggestion = new Suggestion();
        try {
            CodedInputStream input = CodedInputStream.newInstance(bytes);
            while (!input.isAtEnd()) {
                int tag = input.readTag();
                if (tag == 0) {
                    break;
                }

                int fieldNumber = WireFormat.getTagFieldNumber(tag);
                switch (fieldNumber) {
                    case 1:
                        suggestion.timeIssued = ProtoUtils.decodeTimestamp(input);
                        break;
                    case 2:
                        suggestion.boxId = input.readInt32();
                        break;
                    case 3:
                        suggestion.type = SuggestionType.fromProtoInt(input.readInt32());
                        break;
                    case 4:
                        suggestion.itemId = input.readInt32();
                        break;
                    case 5:
                        suggestion.quantity = clampToInt(input.readInt64());
                        break;
                    case 6:
                        suggestion.price = input.readInt64();
                        break;
                    case 7:
                        suggestion.id = input.readInt32();
                        break;
                    case 11:
                        suggestion.message = input.readString();
                        break;
                    case 12:
                        suggestion.expectedProfit = input.readDouble();
                        break;
                    case 14:
                        suggestion.isDumpAlert = input.readBool();
                        break;
                    case 15:
                        suggestion.name = input.readString();
                        break;
                    case 16:
                        suggestion.expectedDuration = input.readDouble();
                        break;
                    case 17:
                        if (suggestion.bankItems == null) {
                            suggestion.bankItems = new HashMap<>();
                        }
                        int mapLength = input.readRawVarint32();
                        int mapLimit = input.pushLimit(mapLength);
                        int key = 0;
                        int value = 0;
                        while (!input.isAtEnd()) {
                            int mapTag = input.readTag();
                            if (mapTag == 0) {
                                break;
                            }
                            int mapFieldNumber = WireFormat.getTagFieldNumber(mapTag);
                            switch (mapFieldNumber) {
                                case 1:
                                    key = input.readInt32();
                                    break;
                                case 2:
                                    value = input.readInt32();
                                    break;
                                default:
                                    input.skipField(mapTag);
                            }
                        }
                        suggestion.bankItems.put(key, value);
                        input.popLimit(mapLimit);
                        break;
                    case 18:
                        if (suggestion.portfolioItems == null) {
                            suggestion.portfolioItems = new ArrayList<>();
                        }
                        int itemLength = input.readRawVarint32();
                        int itemLimit = input.pushLimit(itemLength);
                        suggestion.portfolioItems.add(PortfolioItem.decodeProto(input));
                        input.popLimit(itemLimit);
                        break;
                    case 19:
                        suggestion.isHold = input.readBool();
                        break;
                    default:
                        input.skipField(tag);
                }
            }
        } catch (IOException e) {
            log.warn("failed decoding suggestion proto", e);
            return null;
        }

        if (!suggestion.isDumpAlert && suggestion.message != null && suggestion.message.contains("Dump alert")) {
            suggestion.isDumpAlert = true;
        }
        if (suggestion.type == SuggestionType.ABORT) {
            suggestion.isDumpAlert = false;
        }
        return suggestion;
    }

    private static int clampToInt(long value) {
        if (value > Integer.MAX_VALUE) {
            return Integer.MAX_VALUE;
        }
        if (value < Integer.MIN_VALUE) {
            return Integer.MIN_VALUE;
        }
        return (int) value;
    }
}

