public enum OfferStatus {
    @SerializedName("buy")
    BUY,
    @SerializedName("sell")
    SELL,
    @SerializedName("empty")
    EMPTY;

    public int protoInt() {
        switch (this) {
            case BUY:
                return 1;
            case SELL:
                return 2;
            case EMPTY:
                return 3;
            default:
                return 0;
        }
    }

