import java.text.*;
import java.util.Locale;
import java.util.function.Supplier;

public class UIUtilities {
    public static final String redditIcon = "/reddit-icon.png";
    public static final String discordIcon = "/discord.png";
    public static final String logoutIcon = "/logout.png";
    public static final String internetIcon = "/internet.png";

    public static final float BUTTON_HOVER_LUMINANCE = 0.65f;
    public static final Color OUTDATED_COLOR = new Color(250, 74, 75);
    public static final Color TOMATO = new Color(255,99,71);

    private static final NumberFormat PRECISE_DECIMAL_FORMATTER = new DecimalFormat(
            "#,###.###",
            DecimalFormatSymbols.getInstance(Locale.ENGLISH)
    );
    private static final NumberFormat DECIMAL_FORMATTER = new DecimalFormat(
            "#,###.#",
            DecimalFormatSymbols.getInstance(Locale.ENGLISH)
    );

    public static synchronized String quantityToRSDecimalStack(long quantity, boolean precise)
    {
        String sign = quantity >= 0 ? "" : "-";
        quantity = Math.abs(quantity);
        if (Long.toString(quantity).length() <= 4)
        {
            return sign + QuantityFormatter.formatNumber(quantity);
        }

        long power = (long) Math.log10(quantity);

        // Output thousandths for values above a million
        NumberFormat format = precise && power >= 6
                ? PRECISE_DECIMAL_FORMATTER
                : DECIMAL_FORMATTER;

        return sign+format.format(quantity / Math.pow(10, (Long.divideUnsigned(power, 3)) * 3))
                + new String[] {"", "K", "M", "B", "T"}[(int) (power / 3)];
    }

    public static Color getProfitColor(long profit, FlippingCopilotConfig config) {
        if (profit > 0) {
            return config.profitAmountColor();
        } else if (profit < 0) {
            return config.lossAmountColor();
        } else {
            return Color.WHITE;
        }
    }

    public static Color getProfitColor(double profit, FlippingCopilotConfig config) {
        if (profit > 0) {
            return config.profitAmountColor();
        } else if (profit < 0) {
            return config.lossAmountColor();
        } else {
            return Color.WHITE;
        }
    }

    public static String formatProfit(long profit) {
        return quantityToRSDecimalStack(profit, true) + " gp";
    }

    public static String formatProfitWithoutGp(long profit) {
        return quantityToRSDecimalStack(profit, true);
    }

    public static String formatSuggestionDuration(double durationSeconds) {
        int totalMinutes = (int) Math.round(durationSeconds / 60.0);
        totalMinutes = Math.round(totalMinutes / 5.0f) * 5;
        totalMinutes = Math.max(totalMinutes, 5);

        String formatted = formatDurationMinutes(totalMinutes);
        if (!formatted.contains("h") && !formatted.contains("d")) {
            return formatted.replace("m", "min");
        }
        return formatted;
    }

    public static String formatDurationMinutes(int minutes) {
        int safeMinutes = Math.max(0, minutes);
        int days = safeMinutes / (24 * 60);
        int hours = (safeMinutes % (24 * 60)) / 60;
        int remainingMinutes = safeMinutes % 60;

        if (days > 0) {
            return hours == 0 ? days + "d" : days + "d " + hours + "h";
        }
        if (hours > 0) {
            return hours + "h " + remainingMinutes + "m";
        }
        return Math.max(1, remainingMinutes) + "m";
    }

    public static String truncateString(String string, int length) {
        if (string.length() > length) {
            return string.substring(0, length) + "...";
        }
        return string;
    }

    public static JLabel buildButton(BufferedImage icon, String tooltip, Runnable onClick) {
        JLabel label = new JLabel();
        label.setToolTipText(tooltip);
        label.setHorizontalAlignment(JLabel.CENTER);
        ImageIcon iconOff = new ImageIcon(icon);
        ImageIcon iconOn = new ImageIcon(ImageUtil.luminanceScale(icon, BUTTON_HOVER_LUMINANCE));
        label.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                try {
                    onClick.run();
                } catch (Exception error) {}
            }
            @Override
            public void mouseEntered(MouseEvent e) {
                label.setCursor(new Cursor(Cursor.HAND_CURSOR));
                label.setIcon(iconOn);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                label.setIcon(iconOff);
            }
        });
        label.setIcon(iconOff);
        return label;
    }

    public static JLabel gearButton(String tooltip, Runnable onClick) {
        BufferedImage icon = ImageUtil.resizeImage(ImageUtil.loadImageResource(UIUtilities.class, "/preferences-icon.png"), 20, 20);
        return buildButton(ImageUtil.recolorImage(icon, ColorScheme.LIGHT_GRAY_COLOR), tooltip, onClick);
    }

    public static void addHoverIcons(AbstractButton button, Supplier<Icon> normal, Supplier<Icon> hover) {
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                button.setIcon(hover.get());
            }

            @Override
            public void mouseExited(MouseEvent e) {
                button.setIcon(normal.get());
            }
        });
    }

    /**
     * Returns true when the caller may proceed on the current (EDT) thread. Otherwise the task has
     * been scheduled via invokeLater and the caller must return immediately.
     */
    public static boolean ensureEdt(Runnable task) {
        if (SwingUtilities.isEventDispatchThread()) {
            return true;
        }
        SwingUtilities.invokeLater(task);
        return false;
    }

    public static String colorHex(Color color) {
        return String.format("#%06X", (0xFFFFFF & color.getRGB()));
    }

    public static JPanel darkPanel(LayoutManager layout, Color background) {
        JPanel panel = new JPanel(layout);
        panel.setBackground(background);
        return panel;
    }

    public static JPanel transparentPanel(LayoutManager layout) {
        JPanel panel = new JPanel(layout);
        panel.setOpaque(false);
        return panel;
    }

    public static JPanel verticalPanel(Color background) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(background);
        return panel;
    }

    public static void setFixedSize(JComponent component, int width, int height) {
        Dimension size = new Dimension(width, height);
        component.setPreferredSize(size);
        component.setMaximumSize(size);
    }

    public static void addVerticalGap(JPanel panel, int height) {
        panel.add(Box.createRigidArea(new Dimension(0, height)));
    }

    public static void addHorizontalGap(JPanel panel, int width) {
        panel.add(Box.createRigidArea(new Dimension(width, 0)));
    }

    public static JPanel formRow(String label, Component control) {
        JPanel panel = transparentPanel(new BorderLayout());
        panel.add(new JLabel(label), BorderLayout.LINE_START);
        panel.add(control, BorderLayout.LINE_END);
        return panel;
    }
}

package com.flippingcopilot.ui;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.FlipV2;
import net.runelite.client.ui.ColorScheme;

import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

import static com.flippingcopilot.util.DateUtil.formatEpoch;

public class FlipPanel extends JPanel {
    private static final Color HOVER_BACKGROUND = ColorScheme.DARKER_GRAY_COLOR.brighter();

    public FlipPanel(FlipV2 flip, FlippingCopilotConfig config, Runnable onClick) {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JLabel itemQuantity = new JLabel(String.format("%d x ", flip.getClosedQuantity()));
        itemQuantity.setForeground(Color.WHITE);

        JLabel itemNameLabel = new JLabel(UIUtilities.truncateString(flip.getCachedItemName(), 19));

        // Create a sub-panel for the left side
        JPanel leftPanel = new JPanel();
        leftPanel.setLayout(new FlowLayout(FlowLayout.LEFT, 0, 0));
        leftPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        leftPanel.add(itemQuantity);
        leftPanel.add(itemNameLabel);

        JLabel profitLabel = new JLabel(UIUtilities.formatProfitWithoutGp(flip.getProfit()));
        profitLabel.setForeground(UIUtilities.getProfitColor(flip.getProfit(), config));

        // Add the sub-panel to the LINE_START position
        add(leftPanel, BorderLayout.LINE_START);
        add(profitLabel, BorderLayout.LINE_END);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));

        String closeLabel = flip.getClosedQuantity() == flip.getOpenedQuantity() ? "Close time" : "Partial close time";
        long closedCostBasis = flip.getOpenedQuantity() <= 0
                ? 0
                : (flip.getSpent() * flip.getClosedQuantity()) / flip.getOpenedQuantity();
        String roiText = closedCostBasis > 0
                ? String.format("%.2f%%", ((double) flip.getProfit() / (double) closedCostBasis) * 100.0d)
                : "Unknown";
        Color profitColor = UIUtilities.getProfitColor(flip.getProfit(), config);
        String profitColorHex = UIUtilities.colorHex(profitColor);

        String tooltipText = String.format("<html>Profit: <font color='%s'>%s</font><br>ROI: <font color='%s'>%s</font><br>Avg buy price: <font color='#32A0FA'>%s</font><br>Avg sell price: <font color='#F0CF7B'>%s</font><br>Tax paid: <font color='#FFFFFF'>%s</font><br>Opened time: %s<br>%s: %s</html>",
                profitColorHex,
                UIUtilities.formatProfit(flip.getProfit()),
                profitColorHex,
                roiText,
                UIUtilities.formatProfit(flip.getAvgBuyPrice()),
                UIUtilities.formatProfit(flip.getAvgSellPrice()),
                UIUtilities.formatProfit(flip.getTaxPaid()),
                formatEpoch(flip.getOpenedTime()),
                closeLabel,
                formatEpoch(flip.getClosedTime()));
        setToolTipText(tooltipText);
        leftPanel.setToolTipText(tooltipText);
        itemQuantity.setToolTipText(tooltipText);
        itemNameLabel.setToolTipText(tooltipText);
        profitLabel.setToolTipText(tooltipText);

        if (onClick != null) {
            Component[] clickableComponents = {this, leftPanel, itemQuantity, itemNameLabel, profitLabel};
            MouseAdapter clickListener = new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    onClick.run();
                }

                @Override
                public void mouseEntered(MouseEvent e) {
                    setBackground(HOVER_BACKGROUND);
                    leftPanel.setBackground(HOVER_BACKGROUND);
                    for (Component component : clickableComponents) {
                        component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
                    }
                }

                @Override
                public void mouseExited(MouseEvent e) {
                    setBackground(ColorScheme.DARKER_GRAY_COLOR);
                    leftPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
                    for (Component component : clickableComponents) {
                        component.setCursor(Cursor.getDefaultCursor());
                    }
                }
            };

            for (Component component : clickableComponents) {
                component.addMouseListener(clickListener);
            }
        }
    }
}

