import java.awt.event.MouseEvent;
import java.io.*;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

import static com.flippingcopilot.ui.flipsdialog.FlipFilterAndSort.escapeCSV;
import static com.flippingcopilot.ui.flipsdialog.FlipFilterAndSort.formatTimestampISO;
import static com.flippingcopilot.util.DateUtil.formatEpoch;
import java.util.List;

@Slf4j
public class TransactionsPanel extends JPanel {

    private static final UUID ZERO_UUID = new UUID(0L, 0L);
    private static final int DEFAULT_PAGE_SIZE = 200;
    private static final String[] COLUMN_NAMES = {
            "Timestamp", "Account", "Side", "Item", "Quantity", "Paid/Received", "Tax", "Price ea.", "Part of Flip"
    };

    // dependencies
    private final CopilotLoginRS copilotLoginRS;
    private final ItemController itemController;
    private final ExecutorService executorService;
    private final ApiRequestHandler apiRequestHandler;
    private final OsrsLoginManager osrsLoginManager;
    private final FlipManager flipManager;

    // ui components
    private final Paginator paginatorPanel;
    private final PaginatedTablePanel<AckedTransaction> tablePanel;
    private final AtomicBoolean loadTransactionsTriggered = new AtomicBoolean(false);
    private final JLabel loadingText;

    private AccountDropdown accountDropdown;
    private JLabel errorLabel;

    // state
    private TransactionDataWrapper transactionDataWrapper;
    private volatile Set<Integer> filteredItems = new HashSet<>();
    private volatile int pageSize = DEFAULT_PAGE_SIZE;
    private volatile int currentPage = 1;
    private volatile Integer selectedAccountId;

    public TransactionsPanel(CopilotLoginRS copilotLoginRS,
                             ItemController itemController,
                             @Named("copilotExecutor") ExecutorService executorService,
                             ApiRequestHandler apiRequestHandler,
                             OsrsLoginManager osrsLoginManager,
                             FlippingCopilotConfig config,
                             FlipManager flipManager) {
        this.copilotLoginRS = copilotLoginRS;
        this.itemController = itemController;
        this.executorService = executorService;
        this.apiRequestHandler = apiRequestHandler;
        this.osrsLoginManager = osrsLoginManager;
        this.flipManager = flipManager;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        paginatorPanel = new Paginator((n) -> {
            if (n != currentPage) {
                currentPage = n;
                applyFilters(false);
            }
        });
        tablePanel = new PaginatedTablePanel<>(COLUMN_NAMES, this::toRow);
        loadingText = tablePanel.setSpinnerText("Downloading transactions..");
        setupControls();
        setupTable(config);
        setupErrorOverlay();

        tablePanel.installPageFooter(paginatorPanel, pageSize, newPageSize -> {
            if (newPageSize != pageSize) {
                pageSize = newPageSize;
                currentPage = 1;
                paginatorPanel.setPageNumber(1);
                applyFilters(true);
            }
        });

        add(tablePanel, BorderLayout.CENTER);
    }

    public void loadTransactionsIfNeeded() {
        if (!canLoadForCurrentPlayer()) {
            showLoginPrompt();
            return;
        }
        if (loadTransactionsTriggered.compareAndSet(false, true)) {
            loadTransactions();
        }
    }

    private void setupControls() {
        // Create left panel with dropdowns
        ItemSearchMultiSelect searchField = ItemSearchMultiSelect.itemsFilter(this, itemController,
                () -> new HashSet<>(filteredItems),
                items -> {
                    if (!Objects.equals(items, filteredItems)) {
                        filteredItems = new HashSet<>(items);
                        currentPage = 1;
                        paginatorPanel.setPageNumber(1);
                        applyFilters(true);
                    }
                });

        // Account dropdown
        accountDropdown = DialogUi.accountDropdown(
                () -> copilotLoginRS.get().displayNameToAccountId,
                accountId -> {
                    if (!Objects.equals(accountId, selectedAccountId)) {
                        currentPage = 1;
                        paginatorPanel.setPageNumber(currentPage);
                        selectedAccountId = accountId;
                        applyFilters(true);
                    }
                });
        accountDropdown.refresh();

        tablePanel.leftControls().add(searchField);
        UIUtilities.addHorizontalGap(tablePanel.leftControls(), 3);
        tablePanel.leftControls().add(accountDropdown);

        JButton refreshButton = new JButton("Refresh");
        refreshButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        refreshButton.setFocusable(false);
        refreshButton.setToolTipText("Refresh transactions");
        refreshButton.addActionListener(e -> {
            loadTransactionsTriggered.set(false);
            loadTransactionsIfNeeded();
        });

        // Create right panel with download button
        JButton downloadButton = new JButton("Download");
        downloadButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        downloadButton.setFocusable(false);
        downloadButton.setToolTipText("Download transactions as CSV");
        downloadButton.addActionListener(e -> downloadTransactionsCSV());

        tablePanel.rightControls().add(refreshButton);
        UIUtilities.addHorizontalGap(tablePanel.rightControls(), 5);
        tablePanel.rightControls().add(downloadButton);
    }

    private void setupTable(FlippingCopilotConfig config) {
        // Create table
        tablePanel.installPopupHandler(this::showTransactionMenu);

        // Setup renderers
        DefaultTableCellRenderer booleanRenderer = new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable table, Object value,
                                                           boolean isSelected, boolean hasFocus, int row, int column) {
                Component c = super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);
                if (value instanceof Boolean) {
                    setText((Boolean) value ? "Yes" : "No");
                    setHorizontalAlignment(CENTER);
                }
                return c;
            }
        };

        // Apply renderers to columns
        tablePanel.centerColumns(1, 2, 4); // Account, Side, Quantity
        tablePanel.moneyColumns(FlipsPanel.GP_FORMAT, 5, 6, 7); // Paid/Received, Tax, Price ea.
        tablePanel.setRenderer(booleanRenderer, 8); // Part of Flip
    }

    private void setupErrorOverlay() {
        // Create error label
        errorLabel = new JLabel("Error loading transactions from server", SwingConstants.CENTER);
        errorLabel.setFont(errorLabel.getFont().deriveFont(14f));
        errorLabel.setVisible(false);
        tablePanel.addOverlay(errorLabel, JLayeredPane.PALETTE_LAYER);
    }

    private void showLoginPrompt() {
        setSpinnerVisible(false);
        errorLabel.setText("Log into the game to view account transactions");
        errorLabel.setVisible(true);
    }

    private void loadTransactions() {
        String displayName = osrsLoginManager.getPlayerDisplayName();
        if (!osrsLoginManager.isValidLoginState() || Strings.isNullOrEmpty(displayName)) {
            showLoginPrompt();
            return;
        }
        setSpinnerVisible(true);
        errorLabel.setVisible(false);
        apiRequestHandler.asyncLoadTransactionsData(
                displayName,
                transactionsData -> SwingUtilities.invokeLater(() -> {
                    setSpinnerVisible(false);
                    transactionDataWrapper = new TransactionDataWrapper(transactionsData);
                    applyFilters(true);
                }),
                error -> SwingUtilities.invokeLater(() -> {
                    setSpinnerVisible(false);
                    errorLabel.setVisible(true);
                    log.error("Failed to load transactions: {}", error);
                })
        );
    }

    private boolean canLoadForCurrentPlayer() {
        return osrsLoginManager.isValidLoginState() && !Strings.isNullOrEmpty(osrsLoginManager.getPlayerDisplayName());
    }

    private void setSpinnerVisible(boolean visible) {
        tablePanel.setSpinnerVisible(visible);
    }

    private void applyFilters(boolean updateTotalPages) {
        executorService.submit(() -> {
            synchronized (this) {
                try {
                    if (updateTotalPages) {
                        int n = transactionDataWrapper.totalRecords(filteredItems, selectedAccountId);
                        int totalPages = (int) Math.ceil((double) n / (double) pageSize);
                        paginatorPanel.setTotalPagesWithoutEffect(totalPages);
                    }
                    List<AckedTransaction> txs = transactionDataWrapper.getPage(filteredItems, selectedAccountId, currentPage, pageSize);
                    tablePanel.setRows(txs);
                } catch (Exception e) {
                    errorLabel.setText("Error decoding transaction data.");
                    errorLabel.setVisible(true);
                    log.error("loading transaction page", e);
                }
            }
        });
    }

    private Object[] toRow(AckedTransaction tx) {
        Map<Integer, String> accountIdToDisplayName = copilotLoginRS.get().accountIdToDisplayName;
        int absQuantity = Math.abs(tx.getQuantity());
        long paidReceived = Math.abs(tx.getAmountSpent());
        long priceEa = tx.getPrice();
        return new Object[]{
                formatEpoch(tx.getTime()),
                accountIdToDisplayName.getOrDefault(tx.getAccountId(), "Unknown"),
                tx.getQuantity() > 0 ? "BUY" : "SELL",
                itemController.getItemName(tx.getItemId()),
                absQuantity,
                paidReceived,
                calculateTax(tx),
                priceEa,
                isPartOfFlip(tx),
        };
    }

    private boolean isPartOfFlip(AckedTransaction tx) {
        if (ZERO_UUID.equals(tx.getClientFlipId())) {
            return false;
        }
        return !flipManager.isGhostFlip(tx.getAccountId(), tx.getClientFlipId());
    }

    private long calculateTax(AckedTransaction tx) {
        if (tx.getQuantity() < 0) {
            long pricePerItem = tx.getAmountSpent() / tx.getQuantity();
            long pricePostTax = ProfitCalculator.getPostTaxPrice(tx.getItemId(), pricePerItem);
            return (pricePerItem - pricePostTax) * tx.getQuantity();
        }
        return 0;
    }

    private void showTransactionMenu(MouseEvent e, int row) {
        AckedTransaction transaction = tablePanel.row(row);
        JPopupMenu menu = new JPopupMenu();

        if (isPartOfFlip(transaction)) {
            menu.add(transactionMenuItem(
                    transaction,
                    "Remove from flip",
                    "Are you sure you want to remove the transaction from its flip? The flip and any profit will also be updated. This operation cannot be undone.",
                    "Failed to update transaction. Please try again.",
                    "orphaning",
                    apiRequestHandler::asyncOrphanTransaction,
                    transactionDataWrapper::update));
        }

        menu.add(transactionMenuItem(
                transaction,
                "Delete transaction",
                "Are you sure you want to delete this transaction? Any flip it is part of will also be updated.",
                "Failed to delete transaction. Please try again.",
                "deleting",
                apiRequestHandler::asyncDeleteTransaction,
                tx -> transactionDataWrapper.deleteOne(i -> tx.getId().equals(i.getId()))));
        menu.show(e.getComponent(), e.getX(), e.getY());
    }

    private JMenuItem transactionMenuItem(AckedTransaction transaction, String label, String confirmMessage,
                                          String errorMessage, String logAction,
                                          TransactionRequest request, Consumer<AckedTransaction> localUpdate) {
        JMenuItem item = new JMenuItem(label);
        item.addActionListener(evt -> {
            int result = JOptionPane.showConfirmDialog(this,
                    confirmMessage,
                    "Confirm Action",
                    JOptionPane.YES_NO_OPTION);
            if (result == JOptionPane.YES_OPTION) {
                loadingText.setText("");
                setSpinnerVisible(true);
                log.info("{} transaction with ID: {}", logAction, transaction.getId());

                BiConsumer<Integer, List<FlipV2>> onSuccess = (userId, flips) -> {
                    flipManager.mergeFlips(flips, userId);
                    setSpinnerVisible(false);
                    transaction.setClientFlipId(ZERO_UUID);
                    localUpdate.accept(transaction);
                    applyFilters(false);
                };

                Runnable onFailure = () -> {
                    setSpinnerVisible(false);
                    JOptionPane.showMessageDialog(this,
                            errorMessage,
                            "Error",
                            JOptionPane.ERROR_MESSAGE);
                };

                request.send(transaction, onSuccess, onFailure);
            }
        });
        return item;
    }

    @FunctionalInterface
    private interface TransactionRequest {
        void send(AckedTransaction transaction, BiConsumer<Integer, List<FlipV2>> onSuccess, Runnable onFailure);
    }

    private void downloadTransactionsCSV() {
        if (transactionDataWrapper == null) {
            JOptionPane.showMessageDialog(this,
                    "No transaction data available to download.",
                    "Download Error",
                    JOptionPane.WARNING_MESSAGE);
            return;
        }

        JFileChooser fileChooser = new JFileChooser();
        fileChooser.setDialogTitle("Save Transactions CSV");
        fileChooser.setSelectedFile(new File("transactions.csv"));

        if (fileChooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
            File file = fileChooser.getSelectedFile();
            executorService.submit(() -> {
                try (FileWriter writer = new FileWriter(file)) {
                    writer.write(Strings.join(COLUMN_NAMES, ","));

                    // Use the stream method to write all matching transactions
                    Map<Integer, String> accountIdToDisplayName = copilotLoginRS.get().accountIdToDisplayName;
                    transactionDataWrapper.stream(filteredItems, selectedAccountId)
                            .forEach(tx -> {
                                try {
                                    int absQuantity = Math.abs(tx.getQuantity());
                                    long paidReceived = Math.abs(tx.getAmountSpent());
                                    long priceEa = tx.getPrice();
                                    long tax = calculateTax(tx);
                                    String row = String.join(",",
                                            formatTimestampISO(tx.getTime()),
                                            escapeCSV(accountIdToDisplayName.getOrDefault(tx.getAccountId(), "Unknown")),
                                            tx.getQuantity() > 0 ? "BUY" : "SELL",
                                            escapeCSV(itemController.getItemName(tx.getItemId())),
                                            String.valueOf(absQuantity),
                                            String.valueOf(paidReceived),
                                            String.valueOf(tax),
                                            String.valueOf(priceEa),
                                            isPartOfFlip(tx) ? "YES" : "NO"
                                    );
                                    writer.write("\n" + row);
                                } catch (IOException e) {
                                    throw new RuntimeException(e);
                                }
                            });

                    SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(this,
                            "Transactions exported successfully to " + file.getName(),
                            "Export Complete",
                            JOptionPane.INFORMATION_MESSAGE));
                } catch (Exception e) {
                    SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(this,
                            "Error exporting transactions: " + e.getMessage(),
                            "Export Error",
                            JOptionPane.ERROR_MESSAGE));
                    log.error("Error exporting transactions to CSV", e);
                }
            });
        }
    }
}

package com.flippingcopilot.ui.flipsdialog;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.FlipManager;
import com.flippingcopilot.model.FlipV2;
import com.flippingcopilot.rs.CopilotLoginRS;
import com.flippingcopilot.ui.UIUtilities;
import com.flippingcopilot.ui.components.AccountDropdown;
import com.flippingcopilot.ui.components.IntervalDropdown;
import lombok.NoArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;

import javax.inject.Named;
import javax.swing.*;
import java.awt.*;
import java.time.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.function.Consumer;

@Slf4j
public class ProfitPanel extends JPanel {

    // dependencies
    private final FlipManager flipManager;
    private final ExecutorService executorService;

    private final ProfitGraphPanel graphPanel;
    private final AccountDropdown accountDropdown;
    private final IntervalDropdown intervalDropdown;

    // State
    private int cachedIntervalStartTime = 1; // Default to ALL
    private Integer cachedAccountId = null;
    private List<Datapoint> cachedDatapoints = new ArrayList<>();

    public ProfitPanel(FlipManager flipManager,
                       @Named("copilotExecutor") ExecutorService executorService,
                       CopilotLoginRS copilotLoginRS,
                       FlippingCopilotConfig config) {
        this.flipManager = flipManager;
        this.executorService = executorService;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);

        // Create top panel with controls
        JPanel topPanel = new JPanel(new BorderLayout());
        topPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        topPanel.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));

        // Create left panel with dropdowns
        JPanel leftPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        leftPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        intervalDropdown = DialogUi.intervalDropdown((units, value) -> refreshGraph(false));

        accountDropdown = DialogUi.accountDropdown(() -> copilotLoginRS.get().displayNameToAccountId, accountId -> refreshGraph(false));
        accountDropdown.refresh();

        leftPanel.add(intervalDropdown);
        UIUtilities.addHorizontalGap(leftPanel, 3);
        leftPanel.add(accountDropdown);

        topPanel.add(leftPanel, BorderLayout.WEST);
        add(topPanel, BorderLayout.NORTH);

        // Create a panel to hold both graphs
        JPanel graphsPanel = new JPanel();
        graphsPanel.setLayout(new BoxLayout(graphsPanel, BoxLayout.Y_AXIS));
        graphsPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        // Create graph panels
        graphPanel = new ProfitGraphPanel(config.profitAmountColor(), config.lossAmountColor());
        graphsPanel.add(graphPanel);

        // Add the graphs panel to a scroll pane in case they don't fit
        JScrollPane scrollPane = new JScrollPane(graphsPanel);
        scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(null);
        scrollPane.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);

        add(scrollPane, BorderLayout.CENTER);
    }

    public void refreshGraph(boolean forceRecalculate) {
        executorService.submit(() -> {
            try {
                // not fully initialised
                if(accountDropdown == null || intervalDropdown == null) {
                    return;
                }
                accountDropdown.refresh();
                // Check if we need to regenerate the data
                Integer accountId = accountDropdown.getSelectedAccountId();
                int startTime = (int) IntervalDropdown.calculateStartTime(intervalDropdown.getSelectedIntervalTimeUnit(), intervalDropdown.getSelectedIntervalValue(), 0);
                boolean needsRegeneration = forceRecalculate || cachedDatapoints.isEmpty() ||
                        !Objects.equals(cachedAccountId, accountId) ||
                        cachedIntervalStartTime != startTime;

                if (needsRegeneration) {
                    log.debug("Regenerating profit data points");
                    ProfitAggregator aggregator = new ProfitAggregator();
                    cachedIntervalStartTime = startTime;
                    cachedAccountId = accountId;
                    flipManager.aggregateFlips(cachedIntervalStartTime, cachedAccountId, false, aggregator);
                    cachedDatapoints = aggregator.generateProfitDataPoints();
                    log.debug("Generated {} profit data points and {} daily profits", cachedDatapoints.size(), cachedDatapoints.size());
                }

                SwingUtilities.invokeLater(() -> {
                    graphPanel.setData(cachedDatapoints);
                    graphPanel.repaint();
                });
            } catch (Exception e) {
                log.error("Error refreshing profit graph", e);
            }
        });
    }

    @NoArgsConstructor
    private static class ProfitAggregator implements Consumer<FlipV2> {
        private final Map<LocalDate, Long> dailyProfits = new TreeMap<>();
        private final ZoneId zoneId = ZoneId.systemDefault();

        @Override
        public void accept(FlipV2 flip) {
            if (flip.getClosedQuantity() > 0) {
                LocalDate flipDate = LocalDate.ofInstant(Instant.ofEpochSecond(flip.getClosedTime()), zoneId);
                dailyProfits.merge(flipDate, flip.getProfit(), Long::sum);
            }
        }

        public List<Datapoint> generateProfitDataPoints() {
            List<Datapoint> dataPoints = new ArrayList<>();
            if (dailyProfits.isEmpty()) {
                dataPoints.add(new Datapoint(LocalDate.now(zoneId), 0L, 0L));
            }
            long cumulativeProfit = 0;
            for (Map.Entry<LocalDate, Long> entry : dailyProfits.entrySet()) {
                long dailyProfit = entry.getValue();
                cumulativeProfit += dailyProfit;
                dataPoints.add(new Datapoint(entry.getKey(), cumulativeProfit, dailyProfit));
            }
            return dataPoints;
        }
    }
}

package com.flippingcopilot.ui.flipsdialog;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.controller.ApiRequestHandler;
import com.flippingcopilot.controller.ItemController;
import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.*;
import com.flippingcopilot.ui.UIUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableCellRenderer;
import java.awt.*;
import java.awt.event.MouseEvent;
import java.text.NumberFormat;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import java.util.List;

public class PortfolioPanel extends JPanel {
    private static final NumberFormat GP_FORMAT = NumberFormat.getNumberInstance(Locale.US);
    private static final String CONTENT_CARD = "content";
    private static final String LOGIN_PROMPT_CARD = "login";
    private static final String[] COLUMN_NAMES = {
            "Item", "Market value", "Quantity", "Unrealized Profit", "Unrealized ROI", "Avg buy price", "Time held"
    };

    private static final Map<String, Comparator<PortfolioItemCardData>> SORT_COMPARATORS = new HashMap<>();
    static {
        SORT_COMPARATORS.put("Item", Comparator.comparing(
                PortfolioItemCardData::getItemName,
                Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER)));
        // Numeric columns are pre-reversed so the default DESC direction shows largest-first
        SORT_COMPARATORS.put("Market value", Comparator.<PortfolioItemCardData>comparingLong(
                i -> i.getPostTaxSellUnitPrice() * (long) i.getPortfolioQuantity()).reversed());
        SORT_COMPARATORS.put("Quantity", Comparator.comparingInt(PortfolioItemCardData::getPortfolioQuantity).reversed());
        SORT_COMPARATORS.put("Avg buy price", Comparator.comparingLong(PortfolioItemCardData::getUnitBuyPrice).reversed());
        SORT_COMPARATORS.put("Time held", Comparator.comparingInt(PortfolioItemCardData::getHeldMinutes));
        SORT_COMPARATORS.put("Unrealized Profit", Comparator.comparingLong(PortfolioItemCardData::portfolioUnrealizedProfit).reversed());
        SORT_COMPARATORS.put("Unrealized ROI", Comparator.comparing(
                PortfolioPanel::calculateUnrealizedRoi,
                Comparator.nullsLast(Comparator.<Double>naturalOrder().reversed())));
    }

    private final ItemController itemController;
    private final FlippingCopilotConfig config;
    private final ApiRequestHandler apiRequestHandler;
    private final SuggestionManager suggestionManager;
    private final CopilotLoginRS copilotLoginRS;
    private final OsrsLoginRS osrsLoginRS;
    private final PortfolioStateRS portfolioStateRS;
    private final BankStateRS bankStateRS;
    private final ClientThread clientThread;
    private final Consumer<Integer> openPriceGraph;
    private final CardLayout cardLayout;
    private final JPanel cardPanel;
    private final JPanel summaryTablePanel;
    private final PaginatedTablePanel<PortfolioItemCardData> tablePanel;
    private final JLabel autoSyncInfoLabel;
    private final JButton clearPortfolioButton;
    private final Map<Integer, ImageIcon> itemIconCache = new ConcurrentHashMap<>();

    private List<PortfolioItemCardData> currentItems = new ArrayList<>();
    private String sortColumn = "Market value";
    private SortDirection sortDirection = SortDirection.DESC;

    public PortfolioPanel(ItemController itemController,
                          FlippingCopilotConfig config,
                          ApiRequestHandler apiRequestHandler,
                          SuggestionManager suggestionManager,
                          CopilotLoginRS copilotLoginRS,
                          OsrsLoginRS osrsLoginRs,
                          PortfolioStateRS portfolioStateRS,
                          BankStateRS bankStateRS,
                          ClientThread clientThread,
                          Consumer<Integer> openPriceGraph) {
        this.itemController = itemController;
        this.config = config;
        this.apiRequestHandler = apiRequestHandler;
        this.suggestionManager = suggestionManager;
        this.copilotLoginRS = copilotLoginRS;
        this.osrsLoginRS = osrsLoginRs;
        this.portfolioStateRS = portfolioStateRS;
        this.bankStateRS = bankStateRS;
        this.clientThread = clientThread;
        this.openPriceGraph = openPriceGraph;

        setLayout(new BorderLayout(0, 12));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(10, 10, 10, 10));

        cardLayout = new CardLayout();
        cardPanel = new JPanel(cardLayout);
        cardPanel.setOpaque(false);

        JPanel contentPanel = new JPanel(new BorderLayout(0, 12));
        contentPanel.setOpaque(false);
        contentPanel.setBorder(new EmptyBorder(8, 0, 0, 0));

        JPanel summarySection = new JPanel(new BorderLayout(28, 0));
        summarySection.setOpaque(false);
        summarySection.setBorder(new EmptyBorder(0, 0, 10, 0));

        summaryTablePanel = new JPanel(new GridLayout(0, 2, 24, 10));
        summaryTablePanel.setOpaque(false);
        summaryTablePanel.setBorder(new EmptyBorder(4, 0, 4, 0));
        summarySection.add(summaryTablePanel, BorderLayout.WEST);

        clearPortfolioButton = new JButton("Remove everything from portfolio");
        clearPortfolioButton.setFont(FontManager.getRunescapeFont());
        clearPortfolioButton.setFocusable(false);
        clearPortfolioButton.addActionListener(e -> onClearPortfolioClicked());

        JPanel rightControlsPanel = new JPanel();
        rightControlsPanel.setOpaque(false);
        rightControlsPanel.setLayout(new BorderLayout());
        rightControlsPanel.setBorder(new EmptyBorder(0, 12, 0, 0));

        JPanel bottomRightWrap = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        bottomRightWrap.setOpaque(false);
        autoSyncInfoLabel = new JLabel();
        autoSyncInfoLabel.setForeground(ColorScheme.BRAND_ORANGE);
