package com.flippingcopilot.controller;

import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.CopilotLoginRS;
import com.flippingcopilot.ui.OfferEditor;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Instant;
import java.util.Objects;
import java.util.function.Consumer;
import java.util.function.Supplier;

import static net.runelite.api.VarPlayer.CURRENT_GE_ITEM;

@Slf4j
@Getter
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class OfferHandler {

    private static final int GE_OFFER_INIT_STATE_CHILD_ID = 20;
    // Chatbox numeric prompt modes: 32-bit (quantity) and 64-bit (price, since the 2026-09-30 max-cash update).
    static final int MESLAYER_MODE_INT_INPUT = 7;
    static final int MESLAYER_MODE_LONG_INPUT = 30;

    // dependencies
    private final Client client;
    private final ClientThread clientThread;
    private final SuggestionManager suggestionManager;
    private final ApiRequestHandler apiRequestHandler;
    private final OsrsLoginManager osrsLoginManager;
    private final OfferManager offerManager;
    private final HighlightController highlightController;
    private final CopilotLoginRS copilotLoginRS;

    // state
    private String viewedSlotPriceErrorText = null;

    public void fetchSlotItemPrice(boolean isViewingSlot, Supplier<OfferEditor> offerEditorSupplier) {
        if (isViewingSlot) {
            var currentItemId = client.getVarpValue(CURRENT_GE_ITEM);
            offerManager.setViewedSlotItemId(currentItemId);
            if (currentItemId == -1 || currentItemId == 0) return;

            var suggestion = suggestionManager.getSuggestion();
            if (suggestion != null && suggestion.getItemId() == currentItemId &&
                    Objects.equals(suggestion.offerType(), getOfferType())) {
                offerManager.setViewedSlotItemPrice(suggestion.getPrice());
                offerManager.setLastViewedSlotItemId(suggestion.getItemId());
                offerManager.setLastViewedSlotItemPrice(suggestion.getPrice());
                offerManager.setLastViewedSlotPriceTime((int) Instant.now().getEpochSecond());
                return;
            }

            if (!copilotLoginRS.get().isLoggedIn()) {
                viewedSlotPriceErrorText = "Login to copilot to see item price.";
                return;
            }
            viewedSlotPriceErrorText = "Loading copilot item price..";
            Consumer<ItemPrice> itemPriceConsumer = (fetchedPrice) -> {
                clientThread.invoke(() -> {
                    if (fetchedPrice == null) {
                        viewedSlotPriceErrorText = "Unknown error";
                        return;
                    }

                    if (fetchedPrice.getMessage() != null && !fetchedPrice.getMessage().isEmpty()) {
                        viewedSlotPriceErrorText = fetchedPrice.getMessage();
                    } else {
                        viewedSlotPriceErrorText = null;
                    }
                    offerManager.setViewedSlotItemPrice(isSelling() ? fetchedPrice.getSellPrice() : fetchedPrice.getBuyPrice());
                    offerManager.setLastViewedSlotItemId(offerManager.getViewedSlotItemId());
                    offerManager.setLastViewedSlotItemPrice(offerManager.getViewedSlotItemPrice());
                    offerManager.setLastViewedSlotPriceTime((int) Instant.now().getEpochSecond());

                    highlightController.redraw();
                    log.debug("fetched item {} price: {}", offerManager.getViewedSlotItemId(), offerManager.getViewedSlotItemPrice());

                    // todo: Usage of OfferEditor is messy. It mutates a widget so we need to get the original instance
                    //  of it which is created downstream on some other event handler path. This is why we use a supplier
                    //  but probably it should be an injected class of some kind. We should clean this up in the future
                    //  but for now just need it to work as currently broken.

                    OfferEditor flippingWidget = offerEditorSupplier.get();
                    if (flippingWidget != null) {
                        flippingWidget.showPrice(offerManager.getViewedSlotItemPrice());
                    }
                });
            };


            apiRequestHandler.asyncGetItemPriceWithGraphData(currentItemId, osrsLoginManager.getPlayerDisplayName(), itemPriceConsumer, false);

        } else {
            offerManager.setViewedSlotItemPrice(-1);
            offerManager.setViewedSlotItemId(-1);
            viewedSlotPriceErrorText = null;
        }
        highlightController.redraw();
    }

    public static boolean isNumericInputMode(int mesLayerMode) {
        return mesLayerMode == MESLAYER_MODE_INT_INPUT || mesLayerMode == MESLAYER_MODE_LONG_INPUT;
    }

    public boolean isSettingQuantity() {
        var chatboxTitleWidget = getChatboxTitleWidget();
        if (chatboxTitleWidget == null) return false;
        String chatInputText = chatboxTitleWidget.getText();
        return chatInputText.equals("How many do you wish to buy?") || chatInputText.equals("How many do you wish to sell?");
    }

    public boolean isSettingPrice() {
        var chatboxTitleWidget = getChatboxTitleWidget();
        if (chatboxTitleWidget == null) return false;
        String chatInputText = chatboxTitleWidget.getText();

        var offerTextWidget = getOfferTextWidget();
        if (offerTextWidget == null) return false;
        String offerText = offerTextWidget.getText();
        return chatInputText.equals("Set a price for each item:") && (offerText.equals("Buy offer") || offerText.equals("Sell offer"));
    }


    private Widget getChatboxTitleWidget() {
        return client.getWidget(ComponentID.CHATBOX_TITLE);
    }

    private Widget getOfferTextWidget() {
        var offerContainerWidget = client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER);
        if (offerContainerWidget == null) return null;
        return offerContainerWidget.getChild(GE_OFFER_INIT_STATE_CHILD_ID);
    }

    public boolean isSelling() {
        return client.getVarbitValue(Varbits.GE_OFFER_CREATION_TYPE) == 1;
    }

    public boolean isBuying() {
        return client.getVarbitValue(Varbits.GE_OFFER_CREATION_TYPE) == 0;
    }

    public String getOfferType() {
        if (isBuying()) {
            return "buy";
        } else if (isSelling()) {
            return "sell";
        } else {
            return null;
        }
    }

    public void setSuggestedAction(Suggestion suggestion) {
        var currentItemId = client.getVarpValue(CURRENT_GE_ITEM);

        if (isSettingQuantity()) {
            if (suggestion == null || currentItemId != suggestion.getItemId()) {
                return;
            }
            setChatboxValue(suggestion.getQuantity());
        } else if (isSettingPrice()) {
            long price = -1;
            if (suggestion == null || currentItemId != suggestion.getItemId()
                    || !Objects.equals(suggestion.offerType(), getOfferType())) {
                if (offerManager.getViewedSlotItemId() != currentItemId) {
                    return;
                }
                price = offerManager.getViewedSlotItemPrice();
            } else {
                price = suggestion.getPrice();
            }

            if (price == -1) return;

            setChatboxValue(price);
        }
    }

    public void setChatboxValue(long value) {
        var chatboxInputWidget = client.getWidget(ComponentID.CHATBOX_FULL_INPUT);
        if (chatboxInputWidget == null) return;
        chatboxInputWidget.setText(value + "*");
        client.setVarcStrValue(VarClientStr.INPUT_TEXT, String.valueOf(value));
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.*;
import com.flippingcopilot.util.ProfitCalculator;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SlotProfitColorizer {

    private static final int GE_SLOT_COUNT = 8;
    private static final int FIRST_SLOT_CHILD_ID = 7; // Slots are children 7-14 (0-7)
    private static final int PRICE_TEXT_WIDGET_CHILD_INDEX = 25; // Child index within each slot that contains price text
    private static final int DETAIL_VIEW_CHILD_ID = 15; // Detail view when a slot is opened
    private static final int DETAIL_PRICE_TEXT_CHILD_INDEX = 25; // Price text within detail view
    private static final int OFFER_SETUP_CHILD_ID = 26; // Offer setup screen (buy/sell)
    private static final int OFFER_SETUP_PRICE_TEXT_CHILD_INDEX = 41; // Price text within offer setup

    private static final String DEFAULT_COLOR = "ff981f"; // Game's default orange color for slot overview
    private static final String DETAIL_AND_SETUP_DEFAULT_COLOR = "ffb83f"; // Default color for detail view and offer setup

    private final Client client;
    private final FlippingCopilotConfig config;
    private final OfferManager offerManager;
    private final GrandExchange grandExchange;
    private final ProfitCalculator profitCalculator;

    private SavedOffer getOffer(int slotIndex) {
        try {
            long accountHash = client.getAccountHash();
            return offerManager.loadOffer(accountHash, slotIndex);
        } catch (Exception e) {
            log.debug("Error loading offer for slot {}", slotIndex, e);
            return null;
        }
    }

    public void updateAllSlots() {
        if (!config.slotPriceColorEnabled()) {
            return;
        }

        int openSlot = grandExchange.getOpenSlot();
        if (openSlot > -1) {
            if (grandExchange.isSetupOfferOpen()) {
                updateOfferSetup();
            } else {
                updateDetailView(openSlot);
            }
            return;
        }

        for (int slotIndex = 0; slotIndex < GE_SLOT_COUNT; slotIndex++) {
            updateOverviewSlot(slotIndex);
        }
    }

    private void updateOverviewSlot(int slotIndex) {
        try {
            Widget slotWidget = getSlotWidget(slotIndex);
            Widget priceTextWidget = getPriceTextWidget(slotWidget);

            updatePriceTextColor(priceTextWidget, slotIndex, Color.decode("#" + DEFAULT_COLOR));
        } catch (Exception e) {
            log.error("Error updating slot {} price color", slotIndex, e);
        }
    }

    private void updateDetailView(int openSlot) {
        if (openSlot == -1) {
            return;
        }

        try {
            Widget detailViewWidget = client.getWidget(InterfaceID.GE_OFFERS, DETAIL_VIEW_CHILD_ID);
            Widget priceTextWidget = detailViewWidget != null ? detailViewWidget.getChild(DETAIL_PRICE_TEXT_CHILD_INDEX) : null;

            updatePriceTextColor(priceTextWidget, openSlot, Color.decode("#" + DETAIL_AND_SETUP_DEFAULT_COLOR));
        } catch (Exception e) {
            log.debug("Error updating detail view price color", e);
        }
    }

    private void updatePriceTextColor(Widget priceTextWidget, int slotIndex, Color defaultColor) {
        if (!hasValidText(priceTextWidget)) {
            return;
        }

        Color targetColor = defaultColor;

        if (!isBuyOffer(slotIndex)) {
            targetColor = determineProfitColor(calculateSlotProfit(slotIndex), defaultColor);
        } else if (isOfferTracked(slotIndex)) {
            targetColor = config.slotPriceProfitableColor();
        }

        priceTextWidget.setText(applyColorTag(priceTextWidget.getText(), targetColor));
    }

    private void updateOfferSetup() {
        try {
            Widget offerSetupWidget = client.getWidget(InterfaceID.GE_OFFERS, OFFER_SETUP_CHILD_ID);
            if (offerSetupWidget == null || offerSetupWidget.isHidden()) {
                return;
            }

            Widget priceTextWidget = offerSetupWidget.getChild(OFFER_SETUP_PRICE_TEXT_CHILD_INDEX);
            if (priceTextWidget == null) {
                return;
            }

            Color defaultColor = Color.decode("#" + DETAIL_AND_SETUP_DEFAULT_COLOR);
            Color color = determineOfferSetupColor(defaultColor);

            priceTextWidget.setTextColor(color.getRGB() & 0xFFFFFF);
        } catch (Exception e) {
            log.debug("Error updating offer setup price color", e);
        }
    }

    private Color determineOfferSetupColor(Color defaultColor) {
        if (!grandExchange.isOfferTypeSell()) {
            // For buy offers, show profitable if we have a tracked price and the price matches it.
            int viewedItemId = offerManager.getViewedSlotItemId();
            long viewedItemPrice = offerManager.getViewedSlotItemPrice();
            if (viewedItemId > 0 && viewedItemPrice > 0 && grandExchange.getOfferPrice() == viewedItemPrice) {
                return config.slotPriceProfitableColor();
            }

            return defaultColor;
        }

        int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
        if (itemId <= 0) {
            return defaultColor;
        }

        // For sell offers, calculate profit based on the current price
        Long profit = profitCalculator.calculateProfitPerItem(itemId, grandExchange.getOfferPrice());

        return determineProfitColor(profit, defaultColor);
    }

    private Color determineProfitColor(Long profit, Color defaultColor) {
        if (profit == null || profit == 0) {
            return defaultColor;
        }

        if (profit < 0) {
            return config.slotPriceUnprofitableColor();
        } else {
            return config.slotPriceProfitableColor();
        }
    }

    public void resetAllSlots() {
        for (int slotIndex = 0; slotIndex < GE_SLOT_COUNT; slotIndex++) {
            resetSlot(slotIndex);
        }

        resetDetailView();
        resetOfferSetup();
    }

    private void resetSlot(int slotIndex) {
        try {
            Widget slotWidget = getSlotWidget(slotIndex);
            Widget priceTextWidget = getPriceTextWidget(slotWidget);

            if (!hasValidText(priceTextWidget)) {
                return;
            }

            resetWidgetTextColor(priceTextWidget, DEFAULT_COLOR);
        } catch (Exception e) {
            log.error("Error resetting slot {} price color", slotIndex, e);
        }
    }

    private void resetDetailView() {
        try {
            Widget detailViewWidget = client.getWidget(InterfaceID.GE_OFFERS, DETAIL_VIEW_CHILD_ID);
            Widget priceTextWidget = detailViewWidget != null ? detailViewWidget.getChild(DETAIL_PRICE_TEXT_CHILD_INDEX) : null;

            if (!hasValidText(priceTextWidget)) {
                return;
            }

            resetWidgetTextColor(priceTextWidget, DETAIL_AND_SETUP_DEFAULT_COLOR);
        } catch (Exception e) {
            log.debug("Error resetting detail view price color", e);
        }
    }

    public void resetOfferSetup() {
        try {
            Widget offerSetupWidget = client.getWidget(InterfaceID.GE_OFFERS, OFFER_SETUP_CHILD_ID);
            if (offerSetupWidget == null) {
                return;
            }

            Widget priceTextWidget = offerSetupWidget.getChild(OFFER_SETUP_PRICE_TEXT_CHILD_INDEX);
            if (priceTextWidget == null) {
                return;
            }

            priceTextWidget.setTextColor(Integer.parseInt(DETAIL_AND_SETUP_DEFAULT_COLOR, 16));
        } catch (Exception e) {
            log.debug("Error resetting offer setup price color", e);
        }
    }

    private Long calculateSlotProfit(int slotIndex) {
        try {
            return profitCalculator.calculateSlotProfit(slotIndex);
        } catch (Exception e) {
            log.debug("Error calculating profit for slot {}", slotIndex, e);
            return null;
        }
    }

    private boolean isBuyOffer(int slotIndex) {
        try {
            // First try to get it from SavedOffer
            SavedOffer savedOffer = getOffer(slotIndex);
            if (savedOffer != null) {
                return savedOffer.getOfferStatus() == OfferStatus.BUY;
            }

            // Fallback to current GE offer
            GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
            if (offers != null && slotIndex < offers.length) {
                GrandExchangeOffer currentOffer = offers[slotIndex];
                if (currentOffer != null) {
                    GrandExchangeOfferState state = currentOffer.getState();
                    return state == GrandExchangeOfferState.BUYING
                            || state == GrandExchangeOfferState.BOUGHT
                            || state == GrandExchangeOfferState.CANCELLED_BUY;
                }
            }
        } catch (Exception e) {
            log.debug("Error determining offer type for slot {}", slotIndex, e);
        }

        return false; // Default to sell if unknown
    }

    private boolean isOfferTracked(int slotIndex) {
        return getOffer(slotIndex) != null;
    }

    private String applyColorTag(String text, Color determinedColor) {
        return "<col=" + colorToHex(determinedColor) + ">" + stripColorTags(text) + "</col>";
    }

    private String stripColorTags(String text) {
        if (text == null) {
            return "";
        }

        // Remove <col=XXXXXX> and </col> tags
        return text.replaceAll("<col=[0-9a-fA-F]{6}>", "").replaceAll("</col>", "");
    }

    private String colorToHex(Color color) {
        return String.format("%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
    }

    private Widget getSlotWidget(int slotIndex) {
        return client.getWidget(InterfaceID.GE_OFFERS, FIRST_SLOT_CHILD_ID + slotIndex);
    }

    private Widget getPriceTextWidget(Widget slotWidget) {
        if (slotWidget == null) {
            return null;
        }

        return slotWidget.getChild(PRICE_TEXT_WIDGET_CHILD_INDEX);
    }

    private boolean hasValidText(Widget widget) {
        if (widget == null) {
            return false;
        }

        String text = widget.getText();
        return text != null && !text.isEmpty();
    }

    private void resetWidgetTextColor(Widget widget, String defaultColor) {
        String plainText = stripColorTags(widget.getText());
        widget.setText("<col=" + defaultColor + ">" + plainText + "</col>");
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.model.ItemIdName;
import com.flippingcopilot.ui.FuzzySearchScorer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.ToDoubleFunction;
import java.util.stream.Collectors;
import java.util.stream.IntStream;


@Slf4j
@Singleton
public class ItemController {

    public static final int COINS_ITEM_ID = 995;
    public static final int PLATINUM_TOKENS_ITEM_ID = 13204;
    // dependencies
    private final FuzzySearchScorer fuzzySearchScorer;
    private final Client client;
    private final ItemManager itemManager;
    private final ClientThread clientThread;

    // state
    private final Map<Integer, String> cachedItemNames = new ConcurrentHashMap<>();
    private volatile List<ItemIdName> cachedItems = new ArrayList<>(); // volatile used to guarantee immediate visibility across threads on re-assignment
    private final AtomicBoolean initScheduled = new AtomicBoolean(false);

    @Inject
    public ItemController(Client client,
                          ClientThread clientThread,
                          ItemManager itemManager,
                          FuzzySearchScorer fuzzySearchScorer,
                          ScheduledExecutorService executorService) {
        this.fuzzySearchScorer = fuzzySearchScorer;
        this.client = client;
        this.itemManager = itemManager;
        this.clientThread = clientThread;

        Runnable initItems = () -> {
            // only allow one init attempt at a time
            if(initScheduled.compareAndSet(false, true)) {
                clientThread.invokeLater(() -> {
                    List<ItemIdName> items = IntStream.range(0, client.getItemCount())
                            .mapToObj(itemManager::getItemComposition)
                            .filter(item -> item.isGeTradeable() && item.getNote() == -1)
                            .map(i -> new ItemIdName(i.getId(), i.getName()))
                            .collect(Collectors.toList());
                    if (!items.isEmpty()) {
                        cachedItems = items;
                        cachedItems.forEach(i -> cachedItemNames.put(i.itemId, i.name));
                        initScheduled.set(false);
                        log.debug("initialised {} items", items.size());
                        return true;
                    }
                    // if no items are found try again
                    return false;
                });
            }
        };

        // re-init every 5 mins just in case new items are added without restart
        executorService.scheduleAtFixedRate(initItems, 0, 5, TimeUnit.MINUTES);
    }

    public List<ItemIdName> search(String input, Set<Integer> existingSelectedItems) {

        if(input == null || input.isBlank()) {
            return cachedItems.stream()
                    .sorted(Comparator.comparing((ItemIdName i) -> !existingSelectedItems.contains(i.itemId)).thenComparing(i -> i.name))
                    .collect(Collectors.toList());
        }

        ToDoubleFunction<ItemIdName> comparator = fuzzySearchScorer.comparator(input);
        return cachedItems.stream()
                .filter(item -> comparator.applyAsDouble(item) > 0)
                .sorted(Comparator.comparing((ItemIdName i) -> !existingSelectedItems.contains(i.itemId)).thenComparing(Comparator.comparingDouble(comparator).reversed()
                        .thenComparing(i -> i.name)))
                .collect(Collectors.toList());
    }


    public Set<Integer> allItemIds() {
        return cachedItemNames.keySet();
    }

    public String getItemName(Integer itemId) {
        return cachedItemNames.getOrDefault(itemId, "Name unavailable");
    }

    public void loadImage(Integer itemId, Consumer<AsyncBufferedImage> c) {
        clientThread.invokeLater(() -> {
            c.accept(itemManager.getImage(itemId));
        });
    }

    public int toUnnotedItemId(int itemId) {
        ItemComposition composition = itemManager.getItemComposition(itemId);
        if (composition != null && composition.getNote() != -1 && composition.getLinkedNoteId() > 0) {
            return composition.getLinkedNoteId();
        }
        return itemId;
    }

    public long totalCash(Map<Integer, Integer> itemQuantities) {
        if (itemQuantities == null) {
            return 0L;
        }
        return itemQuantities.getOrDefault(COINS_ITEM_ID, 0)
                + (long) itemQuantities.getOrDefault(PLATINUM_TOKENS_ITEM_ID, 0) * 1000L;
    }

    public Map<Integer, Integer> getRunliteInventory() {
        return buildRuneliteItemMap(InventoryID.INVENTORY);
    }

    public Map<Integer, Integer> getRunliteBankInventory() {
        return buildRuneliteItemMap(InventoryID.BANK);
    }

    private Map<Integer, Integer> buildRuneliteItemMap(InventoryID inventoryID) {
        ItemContainer container = client.getItemContainer(inventoryID);
        if (container == null) {
            return null;
        }
        Map<Integer, Integer> totals = new HashMap<>();
        for (Item item : container.getItems()) {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) {
                continue;
            }
            Integer unnotedTradeableItemId = toUnnotedTradeableItemId(item.getId());
            if (unnotedTradeableItemId == null) {
                continue;
            }
            totals.merge(unnotedTradeableItemId, item.getQuantity(), Integer::sum);
        }
        return totals;
    }

    private Integer toUnnotedTradeableItemId(int itemId) {
        int unnotedItemId = toUnnotedItemId(itemId);
        if (unnotedItemId == COINS_ITEM_ID || unnotedItemId == PLATINUM_TOKENS_ITEM_ID) {
            return unnotedItemId;
        }
        ItemComposition unnoted = itemManager.getItemComposition(unnotedItemId);
        if (unnoted == null || !unnoted.isGeTradeable()) {
            return null;
        }
        return unnotedItemId;
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.CopilotLoginRS;
import com.flippingcopilot.ui.graph.model.Data;
import com.flippingcopilot.util.ProtoUtils;
import com.google.inject.Singleton;
import com.google.protobuf.CodedInputStream;
import com.google.protobuf.WireFormat;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import okhttp3.*;

import javax.inject.Inject;
import java.io.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

import static com.flippingcopilot.util.FormatUtil.formatDuration;
import static com.flippingcopilot.util.FormatUtil.formatSize;


/** The plugin's HTTP surface against the copilot backend, all of it the v2 protobuf contract (servergolang/api-contract/api.proto). */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ApiRequestHandler {

    private static final String serverUrl = System.getProperty("flippingcopilot.api.host", "https://api.flippingcopilot.com");
    private static final String serverFeUrl = serverUrl.replace("api.", "");
    private static final MediaType PROTO_MEDIA_TYPE = MediaType.get("application/protobuf");
    private static final byte[] EMPTY_BODY = new byte[0];
    public static final String DEFAULT_COPILOT_PRICE_ERROR_MESSAGE = "Unable to fetch price copilot price (possible server update)";
    public static final String DEFAULT_PREMIUM_INSTANCE_ERROR_MESSAGE = "Error loading premium instance data (possible server update)";
    public static final String UNKNOWN_ERROR = "Unknown error";
    public static final int UNAUTHORIZED_CODE = 401;
    // dependencies
    private final OkHttpClient client;
    private final CopilotLoginRS copilotLoginRS;
    private final SuggestionPreferencesManager preferencesManager;
    private final ClientThread clientThread;

    @FunctionalInterface
    private interface CheckedResponseConsumer {
        void accept(Response response) throws Exception;
    }

    private Request.Builder unauthed(String path) {
        return new Request.Builder().url(serverUrl + path);
    }

    private Request.Builder authed(String jwtToken, String path) {
        return unauthed(path).addHeader("Authorization", "Bearer " + jwtToken);
    }

    private RequestBody protoBody(byte[] body) {
        return RequestBody.create(PROTO_MEDIA_TYPE, body);
    }

    private Call timeoutCall(Request request, int seconds) {
        return client.newBuilder()
                // Overall timeout
                .callTimeout(seconds, TimeUnit.SECONDS)
                .build()
                .newCall(request);
    }

    // a null jwtToken means the request was the login attempt itself, which always clears the login on a 401
    private void clearLoginIfUnauthorized(Response response, String jwtToken) {
        if (response.code() != UNAUTHORIZED_CODE) {
            return;
        }
        if (jwtToken == null || Objects.equals(jwtToken, copilotLoginRS.get().getJwtToken())) {
            copilotLoginRS.clear();
        }
    }

    private void enqueue(Request request,
                         String jwtToken,
                         String label,
                         Consumer<HttpResponseException> onFailure,
                         CheckedResponseConsumer onSuccess) {
        enqueue(client.newCall(request), jwtToken, label, onFailure, onSuccess);
    }

    private void enqueue(Call call,
                         String jwtToken,
                         String label,
                         Consumer<HttpResponseException> onFailure,
                         CheckedResponseConsumer onSuccess) {
        call.enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("{} failed", label, e);
                onFailure.accept(new HttpResponseException(-1, UNKNOWN_ERROR));
            }

            @Override
            public void onResponse(Call call, Response response) {
                try {
                    if (!response.isSuccessful()) {
                        clearLoginIfUnauthorized(response, jwtToken);
                        String errorMessage = extractErrorMessage(response);
                        log.warn("{} failed status={} error={}", label, response.code(), errorMessage);
                        onFailure.accept(new HttpResponseException(response.code(), errorMessage));
                        return;
                    }
                    onSuccess.accept(response);
                } catch (Exception e) {
                    log.warn("error reading/parsing {} response", label, e);
                    onFailure.accept(new HttpResponseException(-1, UNKNOWN_ERROR));
                }
            }
        });
    }

    private Consumer<HttpResponseException> stringFailure(Consumer<String> onFailure) {
        return error -> onFailure.accept(error.getMessage());
    }

    private Consumer<HttpResponseException> runnableFailure(Runnable onFailure) {
        return ignored -> onFailure.run();
    }


    public void authenticate(String username, String password, Consumer<LoginResponse> successCallback, Consumer<String> failureCallback) {
        Request request = unauthed("/v2/login")
                .addHeader("Authorization", Credentials.basic(username, password))
                .post(protoBody(EMPTY_BODY))
                .build();

        enqueue(request, null, "login", stringFailure(failureCallback), response -> {
            if (response.body() == null) {
                throw new IOException("empty login response");
            }
            successCallback.accept(LoginResponse.decodeProto(response.body().bytes()));
        });
    }

    // the discord login handshake is served by the website, so it is outside the v2 contract
    public Call discordLoginAsync(Consumer<String> oathUrlConsumer,
                                  Consumer<LoginResponse> loginResponseConsumer,
                                  Consumer<HttpResponseException>  onFailure) {
        log.debug("sending request to login via discord");
        Request r = new Request.Builder()
                .url(serverFeUrl + "/v2/plugin-discord-login")
                .get().build();

        Call call = client.newBuilder()
                .readTimeout(0, TimeUnit.MILLISECONDS)
                .callTimeout(0, TimeUnit.MILLISECONDS)
                .build()
                .newCall(r);

        call.enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("login via discord call failed", e);
                clientThread.invoke(() -> onFailure.accept(new HttpResponseException(-1, UNKNOWN_ERROR)));
            }
            @Override
            public void onResponse(Call call, Response response) {
                try {
                    if (!response.isSuccessful()) {
                        if(response.code() == UNAUTHORIZED_CODE) {
                            copilotLoginRS.clear();
                        }
                        log.warn("login via discord call failed with http status code {}", response.code());
                        clientThread.invoke(() -> onFailure.accept(new HttpResponseException(response.code(), extractErrorMessage(response))));
                        return;
                    }
                    if (response.body() == null) {
                        throw new IOException("empty discord login response");
                    }
                    try(InputStream is = response.body().byteStream()) {
                        PluginDiscordLoginInitResponse initResponse = PluginDiscordLoginInitResponse.decodeProto(ProtoUtils.readFrame(is));
                        clientThread.invoke(() -> oathUrlConsumer.accept(initResponse.getUrl()));
                        LoginResponse loginResponse = LoginResponse.decodeDiscordLoginResult(ProtoUtils.readFrame(is));
                        if (loginResponse.getError() != null && !loginResponse.getError().isEmpty()) {
                            clientThread.invoke(() -> onFailure.accept(new HttpResponseException(-1, loginResponse.getError())));
                        } else {
                            clientThread.invoke(() -> loginResponseConsumer.accept(loginResponse));
                        }
                    }
                } catch (Exception e) {
                    log.warn("error reading/parsing discord login response body", e);
                    clientThread.invoke(() -> onFailure.accept(new HttpResponseException(-1, UNKNOWN_ERROR)));
                }
            }
        });

        return call;
    }

    public void getSuggestionAsync(byte[] status,
                                   Consumer<Suggestion> suggestionConsumer,
                                   Consumer<Data> graphDataConsumer,
                                   Consumer<HttpResponseException>  onFailure) {
        String jwtToken = copilotLoginRS.get().getJwtToken();
        Request request = authed(jwtToken, "/v3/suggestion")
                .post(protoBody(status))
                .build();

        long startNanos = System.nanoTime();
        enqueue(request, jwtToken, "get suggestion",
                error -> clientThread.invoke(() -> onFailure.accept(error)),
                response -> handleSuggestionResponse(response, startNanos, suggestionConsumer, graphDataConsumer));
    }

    private void handleSuggestionResponse(Response response, long startNanos, Consumer<Suggestion> suggestionConsumer, Consumer<Data> graphDataConsumer) throws IOException {
        if (response.body() == null) {
            throw new IOException("empty suggestion request response");
        }
        Suggestion s;
        int suggestionSize;
        int graphDataSize = 0;
        long suggestionNanos = -1;
        long graphDataNanos = -1;

        Data d = new Data();
        try(InputStream is = response.body().byteStream()) {
            byte[] suggestionBytes = ProtoUtils.readFrame(is);
            suggestionSize = suggestionBytes.length;
            s = Suggestion.decodeProto(suggestionBytes);
            suggestionNanos = System.nanoTime() - startNanos;
            clientThread.invoke(() -> suggestionConsumer.accept(s));

            try {
                byte[] graphDataBytes = ProtoUtils.readFrame(is);
                graphDataSize = graphDataBytes.length;
                if (graphDataBytes.length == 0) {
                    d.loadingErrorMessage = "No graph data loaded for this item.";
                } else {
                    d = Data.decodeProto(graphDataBytes);
                    graphDataNanos = System.nanoTime() - startNanos;
                }
            } catch (Exception e) {
                log.error("error reading graph data part of the suggestion response", e);
                d.loadingErrorMessage = "There was an issue loading the graph data for this item.";
            }
        }
        log.debug("suggestion response: suggestion size={}, graph data size={}, total time={}, suggestion received={}, graph data received={}",
                formatSize(suggestionSize), formatSize(graphDataSize),
                formatDuration(System.nanoTime() - startNanos), formatDuration(suggestionNanos), formatDuration(graphDataNanos));
        if (s != null && s.getType() == SuggestionType.WAIT){
            d.fromWaitSuggestion = true;
        }
        Data finalD = d;
        clientThread.invoke(() -> graphDataConsumer.accept(finalD));
    }

    public void sendTransactionsAsync(List<Transaction> transactions, String displayName, BiConsumer<Integer, List<FlipV2>> onSuccess, Consumer<HttpResponseException> onFailure) {
