package com.flippingcopilot.controller;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.HeldItemSyncStateRS;
import com.flippingcopilot.ui.OfferEditor;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.widgets.*;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.InterfaceID;


@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GameUiChangesHandler {
    private static final int GE_HISTORY_TAB_WIDGET_ID = 149;
    private static final int SCRIPT_GE_COLLECT = 782;
    private static final int SCRIPT_GE_SLOT_REDRAW = 804;
    private static final String BANK_TAG_TAB_VIEW_OPTION = "View tag tab";
    // Bank tag tab widgets exist before bank item bounds settle.
    // Wait one full frame before resolving the highlight target.
    private static final int BANK_REBUILD_HIGHLIGHT_REDRAW_DELAY_FRAMES = 2;

    // dependencies
    private final ClientThread clientThread;
    private final Client client;
    private final GePreviousSearch gePreviousSearch;
    private final HighlightController highlightController;
    private final SuggestionManager suggestionManager;
    private final GrandExchange grandExchange;
    private final OfferManager offerManager;
    private final OfferHandler offerHandler;
    private final SlotProfitColorizer slotProfitColorizer;
    private final HeldItemSyncStateRS heldItemSyncStateRS;
    private final FlippingCopilotConfig config;
    // state
    boolean quantityOrPriceChatboxOpen;
    boolean itemSearchChatboxOpen = false;
    int bankRebuildHighlightRedrawFramesRemaining = 0;
    @Getter
    OfferEditor flippingWidget = null;

    public void onVarClientIntChanged(VarClientIntChanged event) {
        if (event.getIndex() == VarClientID.CHAT_LASTREBUILD) {
            // this is triggered when a bank tag tab is opened/closed
            requestBankRebuildHighlightRedraw();
        }

        if (event.getIndex() == VarClientID.MESLAYERMODE
                && client.getVarcIntValue(VarClientID.MESLAYERMODE) == 14
                && client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS) != null) {
            itemSearchChatboxOpen = true;
            clientThread.invokeLater(gePreviousSearch::showSuggestedItemInSearch);
        }

        if (quantityOrPriceChatboxOpen
                && event.getIndex() == VarClientID.MESLAYERMODE
                && client.getVarcIntValue(VarClientID.MESLAYERMODE) == 0
        ) {
            quantityOrPriceChatboxOpen = false;
            return;
        }

        if (itemSearchChatboxOpen
                && event.getIndex() == VarClientID.MESLAYERMODE
                && client.getVarcIntValue(VarClientID.MESLAYERMODE) == 0
        ) {
            clientThread.invokeLater(highlightController::redraw);
            itemSearchChatboxOpen = false;
            return;
        }

        //Check that it was the chat input that got enabled.
        if (event.getIndex() != VarClientID.MESLAYERMODE
                || client.getWidget(ComponentID.CHATBOX_TITLE) == null
                || !OfferHandler.isNumericInputMode(client.getVarcIntValue(VarClientID.MESLAYERMODE))
                || client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER) == null) {
            return;
        }
        quantityOrPriceChatboxOpen = true;

        clientThread.invokeLater(() ->
        {
            flippingWidget = new OfferEditor(offerManager, client.getWidget(ComponentID.CHATBOX_CONTAINER), offerHandler, client, config);
            Suggestion suggestion = suggestionManager.getSuggestion();
            if (suggestion != null) {
                flippingWidget.showSuggestion(suggestion);
            }
        });
    }

    public void onVarClientStrChanged(VarClientStrChanged event) {
        if (event.getIndex() == VarClientID.MESLAYERINPUT && itemSearchChatboxOpen) {
            clientThread.invokeLater(highlightController::redraw);
        }
    }

    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == InterfaceID.GE_OFFERS) {
            suggestionManager.setSuggestionNeeded(true);
            clientThread.invokeLater(slotProfitColorizer::updateAllSlots);
        }
        if (event.getGroupId() == 383
                || event.getGroupId() == InterfaceID.GE_OFFERS
                || event.getGroupId() == 213
                || event.getGroupId() == GE_HISTORY_TAB_WIDGET_ID) {
            clientThread.invokeLater(highlightController::redraw);
        }
        if (event.getGroupId() == InterfaceID.BANKMAIN) {
            requestBankRebuildHighlightRedraw();
        }
    }

    public void onWidgetClosed(WidgetClosed event) {
        if (event.getGroupId() == InterfaceID.GE_OFFERS) {
            clientThread.invokeLater(highlightController::removeAll);
            suggestionManager.setSuggestionNeeded(true);
        }
        if (event.getGroupId() == InterfaceID.BANKMAIN) {
            clientThread.invokeLater(highlightController::redraw);
        }
    }

    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarpId() == 375
                || event.getVarpId() == VarPlayerID.TRADINGPOST_SEARCH
                || event.getVarbitId() == VarbitID.GE_NEWOFFER_QUANTITY
                || event.getVarpId() == GrandExchange.GE_SETUP_PRICE_VARP
                || event.getVarbitId() == VarbitID.GE_SELECTEDSLOT) {
            clientThread.invokeLater(highlightController::redraw);
        }

        if (event.getVarpId() == VarPlayerID.TRADINGPOST_SEARCH) {
            clientThread.invokeLater(() -> offerHandler.fetchSlotItemPrice(event.getValue() > -1, this::getFlippingWidget));
        }
    }

    public void handleMenuOptionClicked(MenuOptionClicked event) {
        if (event.getMenuOption().equals("Confirm") && grandExchange.isSlotOpen()) {
            log.debug("offer confirmed tick {}", client.getTickCount());
            heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            offerManager.setOfferJustPlaced(true);
            suggestionManager.setLastOfferSubmittedTick(client.getTickCount());
            suggestionManager.setSuggestionNeeded(true);
            Suggestion suggestion = suggestionManager.getSuggestion();
            if(suggestion != null) {
                suggestion.actionedTick = client.getTickCount();
                suggestionManager.setSuggestionItemIdOnOfferSubmitted(suggestion.getItemId());
                suggestionManager.setSuggestionOfferStatusOnOfferSubmitted(suggestionOfferStatus(suggestion));
            } else {
                suggestionManager.setSuggestionItemIdOnOfferSubmitted(-1);
                suggestionManager.setSuggestionOfferStatusOnOfferSubmitted(null);
            }
        }
        if (BANK_TAG_TAB_VIEW_OPTION.equals(event.getMenuOption())) {
            requestBankRebuildHighlightRedraw();
        }
    }

    private OfferStatus suggestionOfferStatus(Suggestion suggestion) {
        if (suggestion.isSellSuggestion()) {
            return OfferStatus.SELL;
        } else if (suggestion.isBuySuggestion()) {
            return OfferStatus.BUY;
        } else {
            return null;
        }
    }

    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() == SCRIPT_GE_COLLECT || event.getScriptId() == SCRIPT_GE_SLOT_REDRAW) {
            clientThread.invokeLater(slotProfitColorizer::updateAllSlots);
        }
        if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING) {
            requestBankRebuildHighlightRedraw();
        }
    }

    public void onBeforeRender(BeforeRender event) {
        if (bankRebuildHighlightRedrawFramesRemaining > 0) {
            bankRebuildHighlightRedrawFramesRemaining--;
            if (bankRebuildHighlightRedrawFramesRemaining == 0) {
                highlightController.redraw();
            }
        }
        if (grandExchange.isOpen()) {
            slotProfitColorizer.updateAllSlots();
        }
    }

    private void requestBankRebuildHighlightRedraw() {
        bankRebuildHighlightRedrawFramesRemaining = BANK_REBUILD_HIGHLIGHT_REDRAW_DELAY_FRAMES;
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.HeldItemSyncStateRS;
import com.flippingcopilot.ui.SuggestionPanel;
import com.google.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GrandExchangeCollectHandler {

    // dependencies
    private final OsrsLoginManager osrsLoginManager;
    private final GrandExchangeUncollectedManager geUncollected;
    private final SuggestionManager suggestionManager;
    private final Client client;
    private final HeldItemSyncStateRS heldItemSyncStateRS;

    @Setter
    private SuggestionPanel suggestionPanel;

    public void handleCollect(MenuOptionClicked event, int slot) {
        String menuOption = event.getMenuOption();
        Widget widget = event.getWidget();
        if (widget != null) {
            handleCollectAll(menuOption, widget);
            handleCollectWithSlotOpen(menuOption, widget, slot);
            handleCollectionBoxCollectAll(menuOption, widget);
            handleCollectionBoxCollectItem(menuOption, widget);
            handleModifyOffer(menuOption, widget);
        }
    }

    private void handleModifyOffer(String menuOption, Widget widget) {
        if (menuOption.equals("Modify offer")) {
            int slot = widget.getId() - 30474247;
            log.debug("modify offer clicked (tick {}) on slot {}", client.getTickCount(), slot);
            suggestionManager.suggestionsDelayedUntil = client.getTickCount() + 3;
            geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
        }
    }

    private void handleCollectAll(String menuOption, Widget widget) {
        if (widget.getId() == 30474246) {
            if (menuOption.equals("Collect to inventory")) {
                geUncollected.clearAllUncollected(osrsLoginManager.getAccountHash());
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            } else if (menuOption.equals("Collect to bank")) {
                geUncollected.clearAllUncollected(osrsLoginManager.getAccountHash());
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            }
            suggestionPanel.refresh();
        }
    }

    private void handleCollectWithSlotOpen(String menuOption, Widget widget, int slot) {
        if (widget.getId() == 30474264 ) {
            if (menuOption.contains("Collect")) {
                geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            } else if (menuOption.contains("Bank")) {
                geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            }
            suggestionPanel.refresh();
        }
    }

    private void handleCollectionBoxCollectAll(String menuOption, Widget widget) {
        if (widget.getId() == 26345476 && menuOption.equals("Collect to bank")) {
            geUncollected.clearAllUncollected(osrsLoginManager.getAccountHash());
            heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            suggestionPanel.refresh();

        } else if (widget.getId() == 26345475 && menuOption.equals("Collect to inventory")) {
            geUncollected.clearAllUncollected(osrsLoginManager.getAccountHash());
            heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            suggestionPanel.refresh();
        }
    }

    private void handleCollectionBoxCollectItem(String menuOption, Widget widget) {
        int slot = widget.getId() - 26345477;
        if (slot >= 0 && slot <= 7) {
            if (menuOption.contains("Collect")) {
                geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            } else if (menuOption.contains("Bank")) {
                geUncollected.clearSlotUncollected(osrsLoginManager.getAccountHash(), slot);
                heldItemSyncStateRS.delayForTicks(client.getTickCount(), 3);
            }
            suggestionPanel.refresh();
        }
    }
}

package com.flippingcopilot.controller;

import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.CopilotLoginRS;
import com.flippingcopilot.ui.LoginPanel;
import com.flippingcopilot.ui.MainPanel;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;

import static com.flippingcopilot.util.FormatUtil.formatDurationSince;

@Slf4j
@Singleton
public class CopilotLoginController {

    // dependencies
    @Setter
    private LoginPanel loginPanel;
    @Setter
    private MainPanel mainPanel;
    private final ApiRequestHandler apiRequestHandler;
    private final FlipManager flipManager;
    private final OsrsLoginManager osrsLoginManager;
    private final SessionManager sessionManager;
    private final TransactionManager transactionManager;
    private final ScheduledExecutorService executorService;
    private final CopilotLoginRS copilotLoginRS;


    @Inject
    public CopilotLoginController(ApiRequestHandler apiRequestHandler,
                                  FlipManager flipManager,
                                  HighlightController highlightController,
                                  SuggestionManager suggestionManager,
                                  OsrsLoginManager osrsLoginManager,
                                  SessionManager sessionManager,
                                  TransactionManager transactionManager,
                                  ScheduledExecutorService executorService,
                                  CopilotLoginRS copilotLoginRS) {
        this.apiRequestHandler = apiRequestHandler;
        this.flipManager = flipManager;
        this.osrsLoginManager = osrsLoginManager;
        this.sessionManager = sessionManager;
        this.transactionManager = transactionManager;
        this.executorService = executorService;
        this.copilotLoginRS = copilotLoginRS;
        flipManager.setCopilotUserId(copilotLoginRS.get().getUserId());
        loadCopilotAccounts(0);
        copilotLoginRS.registerListener((s) -> {
            if(s.loginResponse == null) {
                flipManager.reset();
                suggestionManager.reset();
                highlightController.removeAll();
                mainPanel.refresh();
            }
        });
    }

    private void loadCopilotAccounts(int previousFailures) {
        int userId = copilotLoginRS.get().getUserId();
        if(userId == -1) {
            return;
        }
        long s = System.nanoTime();
        Consumer<Map<String, Integer>> onSuccess = (displayNameToAccountId) -> {
            displayNameToAccountId.forEach((key, value) -> copilotLoginRS.addAccountIfMissing(value, key, userId));
            log.info("loading {} copilot accounts succeeded - took {}", displayNameToAccountId.size(), formatDurationSince(s));
            syncFlips(copilotLoginRS.get().getUserId(), new HashMap<>(), 0);
        };
        Consumer<String> onFailure = (errorMessage) -> {
            if (copilotLoginRS.get().isLoggedIn()) {
                long backOffSeconds = Math.min(15, (long) Math.exp(previousFailures));
                log.info("failed to load copilot accounts ({}) retrying in {}s", errorMessage, backOffSeconds);
                executorService.schedule(() -> loadCopilotAccounts(previousFailures + 1), backOffSeconds, TimeUnit.SECONDS);
            }
        };
        apiRequestHandler.asyncLoadAccounts(onSuccess, onFailure);
    }

    private void syncFlips(int userId, Map<Integer, Integer> accountIdTime, int previousFailures) {
        // Continuously sync's the delta of new or updated flips from the server with back off on failure
        if(copilotLoginRS.get().getUserId() != userId) {
            log.info("user={}, no longer logged in, stopping syncFlips.", userId);
            return;
        }
        Set<Integer> accountIds = copilotLoginRS.get().accountIds();
        if(accountIds.isEmpty()) {
            long backOffSeconds = Math.min(45, (long) 1+previousFailures);
            log.info("user={}, no accounts loaded - re-scheduling runSyncFlips in {}s", userId, backOffSeconds);
            executorService.schedule(() -> syncFlips(userId, accountIdTime, previousFailures+1), backOffSeconds, TimeUnit.SECONDS);
            return;
        }
        accountIds.forEach(a -> accountIdTime.computeIfAbsent(a, i -> 0));
        long s = System.nanoTime();
        BiConsumer<Integer, FlipsDeltaResult> onSuccess = (Integer copilotUserId, FlipsDeltaResult r) -> {
            if(!flipManager.mergeFlips(r.flips, userId)) {
                log.info("user={}, no longer logged in, stopping syncFlips.", userId);
                return;
            }
            log.debug("user={}, loading {} updated flips - took {}", userId, r.flips.size(), formatDurationSince(s));
            accountIds.forEach((a) -> accountIdTime.put(a, r.time));
            executorService.schedule(() -> syncFlips(userId, accountIdTime, 0), 5, TimeUnit.SECONDS);
        };
        Consumer<String> onFailure = (errorMessage) -> {
            long backOffSeconds = Math.min(45, (long) Math.exp(previousFailures));
            log.info("user={}, failed to load updated flips ({}) retrying in {}s", userId, errorMessage, backOffSeconds);
            executorService.schedule(() -> syncFlips(userId, accountIdTime, previousFailures + 1), backOffSeconds, TimeUnit.SECONDS);
        };
        apiRequestHandler.asyncLoadFlips(accountIdTime, onSuccess, onFailure);
    }

    public void onLoginPressed(String email, String password) {
        Consumer<LoginResponse> onSuccess = (LoginResponse loginResponse) -> {
            onLoginResponse(loginResponse);
            loginPanel.endLoading();
        };
        Consumer<String> onFailure = (String errorMessage) -> {
            onLoginFailure(errorMessage);
            loginPanel.endLoading();
        };
        if (email == null || password == null) {
            return;
        }
        loginPanel.startLoading();
        apiRequestHandler.authenticate(email, password, onSuccess, onFailure);
    }

    public void onLoginResponse(LoginResponse loginResponse) {
        copilotLoginRS.update((s) -> {
            s.loginResponse = loginResponse;
            return s;
        });
        mainPanel.refresh();
        String displayName = osrsLoginManager.getPlayerDisplayName();
        if(displayName != null) {
            flipManager.setIntervalAccount(null);
            flipManager.setIntervalStartTime(sessionManager.getCachedSessionData().startTime);
            transactionManager.scheduleSyncIn(0, displayName);
        }
        flipManager.setCopilotUserId(loginResponse.getUserId());
        loadCopilotAccounts(0);
    }

    public void onLoginFailure(String errorMessage) {
        copilotLoginRS.set(new CopilotLoginState());
        loginPanel.showLoginErrorMessage(errorMessage);
    }

    public Integer getActiveAccountId() {
        String displayName = osrsLoginManager.getPlayerDisplayName();
        if (displayName == null) {
            return null;
        }
        Integer accountId = copilotLoginRS.get().getAccountId(displayName);
        if (accountId == null || accountId == -1) {
            return null;
        }
        return accountId;
    }
}

package com.flippingcopilot.controller;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.LinkedHashSet;
import java.util.Set;

@Slf4j
@Singleton
public class PortfolioController {
    // dependencies
    private final Client client;
    private final ItemController itemController;

    @Inject
    public PortfolioController(Client client,
                               ItemController itemController) {
        this.client = client;
        this.itemController = itemController;
    }

    public Set<Integer> getActiveGrandExchangeItemIdsForSync() {
        Set<Integer> itemIds = new LinkedHashSet<>();
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        if (offers == null) {
            return itemIds;
        }
        for (GrandExchangeOffer offer : offers) {
            if (offer == null) {
                continue;
            }
            GrandExchangeOfferState state = offer.getState();
            if (state != GrandExchangeOfferState.EMPTY) {
                int itemId = offer.getItemId();
                if (itemId > 0) {
                    itemIds.add(itemController.toUnnotedItemId(itemId));
                }
            }
        }
        return itemIds;
    }

}

package com.flippingcopilot.controller;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.BankStateRS;
import com.flippingcopilot.rs.PortfolioStateRS;
import com.flippingcopilot.util.BankTagsUtil;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.*;
import net.runelite.client.util.Text;

import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

@Singleton
@Slf4j
public class PortfolioBankTagController {
    private static final String COPILOT_CONFIG_GROUP = "flippingcopilot";
    private static final String CREATED_TAB_CONFIG_KEY = "portfolioBankTagTabCreated";
    private static final String BANK_TAGS_CONFIG_GROUP = "banktags";
    private static final String BANK_TAGS_TAB_CONFIG = "tagtabs";
    private static final String BANK_TAGS_ICON_PREFIX = "icon_";
    private static final String TAG_NAME = "portfolio";
    private static final int TAB_ICON_ITEM_ID = ItemID.FRISD_TAXBAG_BULGING;
    private static final String LEGACY_TAB_ICON_ITEM_ID = String.valueOf(ItemController.PLATINUM_TOKENS_ITEM_ID);

    private final FlippingCopilotConfig config;
    private final ClientThread clientThread;
    private final ConfigManager configManager;
    private final PluginManager pluginManager;
    private final BankTagsService bankTagsService;
    private final TagManager bankTagManager;
    private final ItemManager itemManager;
    private final PortfolioStateRS portfolioStateRS;
    private final BankStateRS bankStateRS;

    private final AtomicBoolean registered = new AtomicBoolean(false);
    private final AtomicBoolean active = new AtomicBoolean(false);
    private final AtomicBoolean syncQueued = new AtomicBoolean(false);
    private volatile Set<Integer> bankedPortfolioItemIds = Collections.emptySet();
    private Runnable removePortfolioListener;
    private Runnable removeBankListener;

    @Inject
    public PortfolioBankTagController(FlippingCopilotConfig config,
                                      ClientThread clientThread,
                                      ConfigManager configManager,
                                      PluginManager pluginManager,
                                      BankTagsService bankTagsService,
                                      TagManager bankTagManager,
                                      ItemManager itemManager,
                                      PortfolioStateRS portfolioStateRS,
                                      BankStateRS bankStateRS) {
        this.config = config;
        this.clientThread = clientThread;
        this.configManager = configManager;
        this.pluginManager = pluginManager;
        this.bankTagsService = bankTagsService;
        this.bankTagManager = bankTagManager;
        this.itemManager = itemManager;
        this.portfolioStateRS = portfolioStateRS;
        this.bankStateRS = bankStateRS;
    }

    public void startUp() {
        active.set(true);
        removePortfolioListener = portfolioStateRS.registerListener(state -> requestSync());
        removeBankListener = bankStateRS.registerListener(state -> requestSync());
        requestSync();
    }

    public void shutDown() {
        active.set(false);
        if (removePortfolioListener != null) {
            removePortfolioListener.run();
            removePortfolioListener = null;
        }
        if (removeBankListener != null) {
            removeBankListener.run();
            removeBankListener = null;
        }
        unregisterTag();
    }

    public void onConfigChanged() {
        requestSync();
    }

    private void requestSync() {
        if (!active.get() || !syncQueued.compareAndSet(false, true)) {
            return;
        }

        // Plugin start-up runs on the AWT event thread when toggled from the plugin
        // panel. ItemManager.canonicalize(), used by sync(), requires the client thread.
        clientThread.invokeLater(() -> {
            syncQueued.set(false);
            if (active.get()) {
                sync();
            }
        });
    }

    private void sync() {
        if (!config.portfolioBankTag() || !BankTagsUtil.isActive(pluginManager)) {
            bankedPortfolioItemIds = Collections.emptySet();
            if (!config.portfolioBankTag()) {
                removeAutoCreatedTab();
            }
            unregisterTag();
            return;
        }

        registerTag();
        ensureBankTagTab();
        updateBankedPortfolioItems();
    }

    private void registerTag() {
        if (registered.compareAndSet(false, true)) {
            bankTagManager.registerTag(TAG_NAME, itemId -> bankedPortfolioItemIds.contains(canonicalize(itemId)));
            log.debug("registered dynamic Bank Tags tag '{}'", TAG_NAME);
        }
    }

    private void unregisterTag() {
        bankedPortfolioItemIds = Collections.emptySet();
        if (registered.compareAndSet(true, false)) {
            bankTagManager.unregisterTag(TAG_NAME);
            log.debug("unregistered dynamic Bank Tags tag '{}'", TAG_NAME);
        }
    }

    private void ensureBankTagTab() {
        List<String> tabs = new ArrayList<>(Text.fromCSV(configValue(BANK_TAGS_TAB_CONFIG)));
        if (!tabs.contains(TAG_NAME)) {
            tabs.add(TAG_NAME);
            configManager.setConfiguration(BANK_TAGS_CONFIG_GROUP, BANK_TAGS_TAB_CONFIG, Text.toCSV(tabs));
            configManager.setConfiguration(COPILOT_CONFIG_GROUP, CREATED_TAB_CONFIG_KEY, true);
        }

        String iconKey = BANK_TAGS_ICON_PREFIX + TAG_NAME;
        String iconItemId = configManager.getConfiguration(BANK_TAGS_CONFIG_GROUP, iconKey);
        if (iconItemId == null || LEGACY_TAB_ICON_ITEM_ID.equals(iconItemId)) {
            configManager.setConfiguration(BANK_TAGS_CONFIG_GROUP, iconKey, TAB_ICON_ITEM_ID);
        }
    }

    private void removeAutoCreatedTab() {
        if (!Boolean.TRUE.equals(configManager.getConfiguration(COPILOT_CONFIG_GROUP, CREATED_TAB_CONFIG_KEY, Boolean.class))) {
            return;
        }

        List<String> tabs = new ArrayList<>(Text.fromCSV(configValue(BANK_TAGS_TAB_CONFIG)));
        if (tabs.remove(TAG_NAME)) {
            configManager.setConfiguration(BANK_TAGS_CONFIG_GROUP, BANK_TAGS_TAB_CONFIG, Text.toCSV(tabs));
        }
        configManager.unsetConfiguration(BANK_TAGS_CONFIG_GROUP, BANK_TAGS_ICON_PREFIX + TAG_NAME);
        configManager.unsetConfiguration(COPILOT_CONFIG_GROUP, CREATED_TAB_CONFIG_KEY);
    }

    private String configValue(String key) {
        String value = configManager.getConfiguration(BANK_TAGS_CONFIG_GROUP, key);
        return value == null ? "" : value;
    }

    private void updateBankedPortfolioItems() {
        PortfolioState portfolioState = portfolioStateRS.get();
        BankState bankState = bankStateRS.get();
        if (portfolioState == null || !portfolioState.isLoaded() || bankState == null || !bankState.isLoaded()) {
            setBankedPortfolioItemIds(Collections.emptySet());
            return;
        }

        Set<Integer> bankItems = new HashSet<>();
        bankState.getItems().forEach((itemId, quantity) -> {
            if (itemId != null && quantity != null && quantity > 0) {
                bankItems.add(canonicalize(itemId));
            }
        });

        Set<Integer> itemIds = new HashSet<>();
        for (PortfolioItemCardData item : portfolioState.getItemCardDataByItemId().values()) {
            if (item != null && item.hasPortfolioQuantityInBank()) {
                int itemId = canonicalize(item.getItemId());
                if (bankItems.contains(itemId)) {
                    itemIds.add(itemId);
                }
            }
        }
        setBankedPortfolioItemIds(Collections.unmodifiableSet(itemIds));
    }

    private void setBankedPortfolioItemIds(Set<Integer> itemIds) {
        Set<Integer> previous = bankedPortfolioItemIds;
        if (previous.equals(itemIds)) {
            return;
        }

        bankedPortfolioItemIds = itemIds;
        refreshActivePortfolioTag();
    }

    private void refreshActivePortfolioTag() {
        if (TAG_NAME.equals(bankTagsService.getActiveTag())) {
            bankTagsService.openBankTag(TAG_NAME, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
        }
    }

    private int canonicalize(int itemId) {
        return itemManager.canonicalize(Math.abs(itemId));
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.*;
import com.flippingcopilot.ui.UIUtilities;
import joptsimple.internal.Strings;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.time.Instant;

import static com.flippingcopilot.util.DateUtil.formatEpoch;
import static net.runelite.http.api.RuneLiteAPI.GSON;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class WebHookController {

    private final FlippingCopilotConfig config;
    private final OkHttpClient okHttpClient;

    private void sendWebHook(DiscordWebhookBody discordWebhookBody) {
        String configURL = config.webhook();
        if (Strings.isNullOrEmpty(configURL)) {return; }

        HttpUrl url = HttpUrl.parse(configURL);
        if (url == null) {
            log.warn("bad discord webhook url {}", configURL);
            return;
        }
        MultipartBody.Builder requestBodyBuilder = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("payload_json", GSON.toJson(discordWebhookBody));
        buildRequestAndSend(url, requestBodyBuilder);
    }

    private void buildRequestAndSend(HttpUrl url, MultipartBody.Builder requestBodyBuilder) {
        RequestBody requestBody = requestBodyBuilder.build();
        Request request = new Request.Builder()
                .url(url)
                .post(requestBody)
                .build();
        sendRequest(request);
    }

    private void sendRequest(Request request) {
        okHttpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.debug("Error on webhook", e);
            }

            @Override
            public void onResponse(Call call, Response response) {
                response.close();
            }
        });
    }

    public void sendMessage(Stats stats, SessionData sd, String displayName, boolean sessionIsFinished) {
        if (stats.profit != 0 && displayName != null) {

            long seconds = sd.durationMillis / 1000;
            String beganAtText = formatEpoch(sd.startTime);
            String endedAtText = sessionIsFinished ? formatEpoch(Instant.now().getEpochSecond()) : "n/a";
            String durationText = String.format("%02d:%02d:%02d", seconds / 3600, (seconds % 3600) / 60, seconds % 60);
            String profitText = UIUtilities.formatProfit(stats.profit);
            String taxText = UIUtilities.formatProfit(stats.taxPaid);
            String roiText = String.format("%.3f%%", stats.calculateRoi() * 100);
            String cashStackText = UIUtilities.quantityToRSDecimalStack(Math.abs(sd.averageCash), false) + " gp";

            String template = "%s, your session stats are:\n" +
                    "```" +
                    "Session began at:      %s\n" +
                    "Session ended at:      %s\n" +
                    "Active session time:   %s\n" +
                    "Flips made:            %d\n" +
                    "Profit:                %s\n" +
                    "Tax paid:              %s\n" +
                    "Roi:                   %s\n" +
                    "Avg wealth:            %s\n" +
                    "```";

            String discordMessage = String.format(template, displayName, beganAtText, endedAtText, durationText, stats.flipsMade, profitText, taxText, roiText, cashStackText);
            DiscordWebhookBody discordWebhookBody = new DiscordWebhookBody();
            discordWebhookBody.setContent(discordMessage);
            sendWebHook(discordWebhookBody);
        }
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.ui.UIUtilities;
import com.flippingcopilot.util.ProfitCalculator;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class TooltipController {
    private static final int SCRIPT_TOOLTIP_GE = 526;
    private static final int TOOLTIP_HEIGHT_WITH_PROFIT = 45;

    private static final int WIDTH_PADDING = 4;

    private final Client client;
    private final ProfitCalculator profitCalculator;

    public void tooltip(ScriptPostFired e) {
        if(e.getScriptId() != SCRIPT_TOOLTIP_GE) {
            return;
        }

        Widget tooltip = client.getWidget(InterfaceID.GeOffers.TOOLTIP);

        if(tooltip == null || tooltip.isHidden()) {
            return;
        }

        Widget background = tooltip.getChild(0);
        Widget border = tooltip.getChild(1);
        Widget text = tooltip.getChild(2);

        if (text != null && background != null && border != null) {

            if (text.getText().contains("Profit:")) {
                // If the tooltip already contains profit information, we don't need to process it again
                return;
            }

            if(!isItemSelling(text.getText())) {
                return;
            }

            String name = getItemNameFromTooltipText(text.getText());

            if(name != null) {
                long profit = profitCalculator.getProfitByItemName(name);
                text.setText(text.getText()  + "<br>Profit: " + UIUtilities.quantityToRSDecimalStack(profit, false) + " gp");
                tooltip.setOriginalHeight(TOOLTIP_HEIGHT_WITH_PROFIT);

                int width = calculateTooltipWidth(text.getFont(), text.getText());
                tooltip.setOriginalWidth(width);

                tooltip.revalidate();
                border.revalidate();
                background.revalidate();
                text.revalidate();
            }
        }
    }

    public boolean isItemSelling(String text) {
        text = text.replaceAll("<br>", " ").trim();
        Pattern pattern = Pattern.compile("^(Buying|Selling): (.+) (\\d{1,3}(?:,\\d{3})*|\\d+) / (\\d{1,3}(?:,\\d{3})*|\\d+)( Profit: -?[\\d,]+ gp?)?$");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            String action = matcher.group(1);
            return action.equals("Selling");
        } else {
            return false; // or handle as you wish
        }
    }

    public String getItemNameFromTooltipText(String text) {
        text = text.replaceAll("<br>", " ").trim();
        Pattern pattern = Pattern.compile("^(Buying|Selling): (.+) (\\d{1,3}(?:,\\d{3})*|\\d+) / (\\d{1,3}(?:,\\d{3})*|\\d+)( Profit: -?[\\d,]+ gp?)?$");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return matcher.group(2);
        } else {
            return null; // or handle as you wish
        }
    }

    private int calculateTooltipWidth(FontTypeFace f, String text)
    {
        final String[] lines = text.split("<br>");
        int maxWidth = 0;
        for (String line : lines) {
            String left = "";
            left = line;

            int width = f.getTextWidth(left);
            if (width > maxWidth) {
                maxWidth = width;
            }
        }
        return maxWidth + WIDTH_PADDING;
    }
}

package com.flippingcopilot.controller;

import javax.inject.Singleton;
import java.awt.*;

@Singleton
public class HighlightColorController {

    // Color ranges for red highlight (R,G,B values)
    private static final int[] RED_START = {205, 0, 50};
    private static final int[] RED_END = {255, 50, 0};

    // Color ranges for blue highlight (R,G,B values)
    private static final int[] BLUE_START = {5, 153, 255};
    private static final int[] BLUE_END = {55, 205, 205};

    // Color ranges for amber highlight (R,G,B values)
    private static final int[] AMBER_START = {210, 108, 0};
    private static final int[] AMBER_END = {236, 134, 10};

    // Constants for controlling the drift
    private static final long CYCLE_DURATION = 600000; // 10 minutes for one complete cycle
    private static final int BASE_ALPHA = 79;
    private static final int MIN_ALPHA = 31;
    private static final int DUMP_ALPHA_MAX = 127;
    private static final double DUMP_ALPHA_FREQUENCY_HZ = 2.0;

    public Color getRedColor() {
        return getRedColor(false);
    }

    public Color getRedColor(boolean isDumpAlert) {
        double phase = calculatePhase();
        int alpha = calculateAlpha(isDumpAlert);
        return interpolateColor(RED_START, RED_END, phase, alpha);
    }

    public Color getBlueColor() {
        return getBlueColor(false);
    }

    public Color getBlueColor(boolean isDumpAlert) {
        double phase = calculatePhase();
        int alpha = calculateAlpha(isDumpAlert);
        return interpolateColor(BLUE_START, BLUE_END, phase, alpha);
    }

    public Color getAmberColor() {
        return getAmberColor(false);
    }

    public Color getAmberColor(boolean isDumpAlert) {
        double phase = calculatePhase();
        int alpha = calculateAlpha(isDumpAlert);
        return interpolateColor(AMBER_START, AMBER_END, phase, alpha);
    }

    private double calculatePhase() {
        // Current time modulo cycle duration gives us position in the cycle
        long currentTime = System.currentTimeMillis();
        double cyclePosition = (currentTime % CYCLE_DURATION) / (double) CYCLE_DURATION;

        // Use absolute sine wave to create smooth back-and-forth oscillation
        return Math.abs(Math.sin(cyclePosition * Math.PI));
    }

    private Color interpolateColor(int[] start, int[] end, double phase, int alpha) {
        int red = interpolateComponent(start[0], end[0], phase);
        int green = interpolateComponent(start[1], end[1], phase);
        int blue = interpolateComponent(start[2], end[2], phase);

        return new Color(red, green, blue, alpha);
    }

    private int interpolateComponent(int start, int end, double phase) {
        return (int) Math.round(start + (end - start) * phase);
    }

    private int calculateAlpha(boolean isDumpAlert) {
        if (!isDumpAlert) {
            return BASE_ALPHA;
        }
        double timeSeconds = System.currentTimeMillis() / 1000.0;
        double phase = (timeSeconds * DUMP_ALPHA_FREQUENCY_HZ) % 1.0;
        double oscillation = 1.0 - Math.abs(2.0 * phase - 1.0);
        return (int) Math.round(MIN_ALPHA + (DUMP_ALPHA_MAX - MIN_ALPHA) * oscillation);
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.*;
import com.flippingcopilot.ui.NpcHighlightOverlay;
import com.flippingcopilot.ui.WidgetHighlightOverlay;
import com.flippingcopilot.util.BankTagsUtil;
import lombok.RequiredArgsConstructor;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;



@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class HighlightController {
    private static final int BANK_WIDGET_GROUP = 12;
    private static final int[] BANK_ITEM_CONTAINER_CHILDREN = {12, 13, 89};
    private static final String PORTFOLIO_BANK_TAG = "portfolio";
    private static final int BANK_TAG_TAB_CHILD_OFFSET = 4;
    private static final int BANK_CLOSE_BUTTON_INDEX = 11;
    private static final int GE_CLOSE_BUTTON_INDEX = 11;
    private static final Rectangle CLOSE_BUTTON_HIGHLIGHT_BOUNDS = new Rectangle(2, 2, 19, 19);
    private static final String GE_CLERK_NAME = "Grand Exchange Clerk";
    private static final String BANKER_NAME = "Banker";

    // dependencies
    private final FlippingCopilotConfig config;
    private final SuggestionManager suggestionManager;
    private final SuggestionPreferencesManager suggestionPreferencesManager;
    private final GrandExchange grandExchange;
    private final AccountStatusManager accountStatusManager;
    private final Client client;
    private final OfferManager offerManager;
    private final OverlayManager overlayManager;
    private final HighlightColorController highlightColorController;
    private final PluginManager pluginManager;
    private final BankTagsService bankTagsService;
    private final ModelOutlineRenderer modelOutlineRenderer;

    // state
    private final ArrayList<Overlay> highlightOverlays = new ArrayList<>();
    private volatile boolean active = true;
    private final AtomicInteger generation = new AtomicInteger(0);

    public void activate() {
        active = true;
        generation.incrementAndGet();
    }

    public void deactivateAndRemoveAll() {
        active = false;
        final int clearGeneration = generation.incrementAndGet();
        Runnable clearTask = () -> clearOverlaysIfCurrentGeneration(clearGeneration);
        if (SwingUtilities.isEventDispatchThread()) {
            clearTask.run();
            return;
        }
        try {
            SwingUtilities.invokeAndWait(clearTask);
        } catch (Exception e) {
            SwingUtilities.invokeLater(clearTask);
        }
    }

    public void redraw() {
        if (!active) {
            return;
        }
        removeAll();
        if (!active) {
            return;
        }
        if(!config.suggestionHighlights()) {
            return;
        }
        if (offerManager.isOfferJustPlaced()) {
            return;
        }
        if(suggestionManager.getSuggestionError() != null) {
            return;
        }
        Suggestion suggestion = suggestionManager.getSuggestion();
        if (suggestion == null) {
            return;
        }
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        boolean sellFromBank = accountStatus != null && accountStatus.shouldSellFromBank(suggestion);
        // When the user must collect first (e.g. no free slot for the sell-from-bank offer),
        // sending them to the bank is wrong — they have to go to the GE clerk first.
        boolean isCollectNeeded = accountStatus != null && accountStatus.isCollectNeeded(suggestion, grandExchange.isSetupOfferOpen());
        boolean goToBank = sellFromBank && !isCollectNeeded;
        if (goToBank && grandExchange.isOpen() && highlightGrandExchangeCloseButton(suggestion)) {
            return;
        }
        if (!goToBank && isBankOpen() && !suggestion.isWaitSuggestion() && highlightBankCloseButton(suggestion)) {
            return;
        }
        if (goToBank && drawSellFromBankHighlight(suggestion, accountStatus)) {
            return;
        }
        if(!grandExchange.isOpen()) {
            if (!isBankOpen()) {
                highlightNpcAtGrandExchange(suggestion, accountStatus, goToBank);
            }
            return;
        }
        if (grandExchange.isHomeScreenOpen()) {
            drawHomeScreenHighLights(suggestion);
        } else if (grandExchange.isSlotOpen()) {
            drawOfferScreenHighlights(suggestion);
        }
    }

    private void highlightNpcAtGrandExchange(Suggestion suggestion, AccountStatus accountStatus, boolean goToBank) {
        if (accountStatus == null) {
            return;
        }
        // Player is considered at the GE only if a clerk is loaded nearby
        NPC clerk = findClosestNpcByName(GE_CLERK_NAME);
        if (clerk == null) {
            return;
        }
        NPC target;
        if (goToBank) {
            target = findClosestNpcByName(BANKER_NAME);
        } else if (drawHomeScreenHighLights(suggestion)) {
            // Reuses the existing home-screen decision tree as the actionability check;
            // widget lookups inside no-op while the GE is closed
            target = clerk;
        } else {
            return;
        }
        if (target == null) {
            return;
        }
        boolean flashHighlight = suggestion.isBuyDumpSuggestion();
        addNpcHighlight(target, () -> {
            Color base = highlightColorController.getBlueColor(flashHighlight);
            if (base == null) {
                return null;
            }
            // Feathered outlines need a higher alpha than filled widget overlays to read as a glow
            return new Color(base.getRed(), base.getGreen(), base.getBlue(), Math.min(255, base.getAlpha() * 3));
        });
    }

    private NPC findClosestNpcByName(String name) {
        Player player = client.getLocalPlayer();
        if (player == null) {
            return null;
        }
        WorldPoint playerLocation = player.getWorldLocation();
        if (playerLocation == null) {
            return null;
        }
        NPC closest = null;
        int closestDistance = Integer.MAX_VALUE;
        for (NPC npc : client.getNpcs()) {
            if (npc == null || !name.equals(npc.getName())) {
                continue;
            }
            WorldPoint npcLocation = npc.getWorldLocation();
            if (npcLocation == null) {
                continue;
            }
            int distance = npcLocation.distanceTo(playerLocation);
            if (distance < closestDistance) {
                closestDistance = distance;
                closest = npc;
            }
        }
        return closest;
    }

    private void addNpcHighlight(NPC npc, Supplier<Color> colorSupplier) {
        if (!active || npc == null) {
            return;
        }
        final int addGeneration = generation.get();
        SwingUtilities.invokeLater(() -> {
            if (!active || generation.get() != addGeneration) {
                return;
            }
            NpcHighlightOverlay overlay = new NpcHighlightOverlay(npc, colorSupplier, modelOutlineRenderer);
            highlightOverlays.add(overlay);
            overlayManager.add(overlay);
        });
    }

    private boolean drawHomeScreenHighLights(Suggestion suggestion) {
        boolean flashHighlight = suggestion.isBuyDumpSuggestion();
        Supplier<Color> blueHighlight = () -> highlightColorController.getBlueColor(flashHighlight);
        Supplier<Color> redHighlight = () -> highlightColorController.getRedColor(flashHighlight);
        Supplier<Color> amberHighlight = () -> highlightColorController.getAmberColor(flashHighlight);
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        if (accountStatus.isCollectNeeded(suggestion, grandExchange.isSetupOfferOpen())) {
            Widget collectButton = grandExchange.getCollectButton();
            if (collectButton != null) {
                add(collectButton, blueHighlight, new Rectangle(2, 1, 81, 18));
            }
            return true;
        }
        else if (suggestion.isAbortSuggestion()) {
            Widget slotWidget = grandExchange.getSlotWidget(suggestion.getBoxId());
            add(slotWidget, redHighlight);
            return true;
        }
        else if (suggestion.isModifySuggestion()) {
            Widget slotWidget = grandExchange.getSlotWidget(suggestion.getBoxId());
            if (slotWidget != null && !slotWidget.isHidden()) {
                add(slotWidget, amberHighlight);
            }
            return true;
        }
        else if (isScanningForDumpsSuggested(suggestion, accountStatus)) {
            highlightCreateBuyOfferButton(accountStatus, blueHighlight);
            return true;
        }
        else if (suggestion.isBuySuggestion()) {
            highlightCreateBuyOfferButton(accountStatus, blueHighlight);
            return true;
        }
        else if (suggestion.isSellSuggestion() && accountStatus.hasSufficientInventoryForSellSuggestion(suggestion)) {
            Widget itemWidget = getInventoryItemWidget(suggestion.getItemId());
            if (itemWidget != null && !itemWidget.isHidden()) {
                add(itemWidget, blueHighlight, new Rectangle(0, 0, 34, 32));
            }
            return true;
        }
        return false;
    }

    private boolean drawSellFromBankHighlight(Suggestion suggestion, AccountStatus accountStatus) {
        boolean flashHighlight = suggestion.isBuyDumpSuggestion();
        Supplier<Color> blueHighlight = () -> highlightColorController.getBlueColor(flashHighlight);

        Widget bankItemWidget = getBankItemWidget(suggestion.getItemId());
        if (bankItemWidget != null && !bankItemWidget.isHidden()) {
            add(bankItemWidget, blueHighlight, new Rectangle(0, 0, 34, 32));
            return true;
        }

        Widget portfolioTagButton = getPortfolioBankTagButton();
        if (portfolioTagButton != null) {
            add(portfolioTagButton, blueHighlight);
            return true;
        }

        return false;
    }

    private boolean highlightGrandExchangeCloseButton(Suggestion suggestion) {
        return highlightCloseButton(getGrandExchangeCloseButton(), suggestion);
    }

    private boolean highlightBankCloseButton(Suggestion suggestion) {
        return highlightCloseButton(getBankCloseButton(), suggestion);
    }

    private boolean highlightCloseButton(Widget closeButton, Suggestion suggestion) {
        if (closeButton == null || closeButton.isHidden()) {
            return false;
        }

        boolean flashHighlight = suggestion.isBuyDumpSuggestion();
        Supplier<Color> blueHighlight = () -> highlightColorController.getBlueColor(flashHighlight);
        add(closeButton, blueHighlight, new Rectangle(CLOSE_BUTTON_HIGHLIGHT_BOUNDS));
        return true;
    }

    private boolean isScanningForDumpsSuggested(Suggestion suggestion, AccountStatus accountStatus) {
        return suggestion.isWaitSuggestion()
                && accountStatus.emptySlotExists()
                && !accountStatus.moreGpNeeded()
                && suggestionPreferencesManager.isReceiveDumpSuggestions();
    }

    private void highlightCreateBuyOfferButton(AccountStatus accountStatus, Supplier<Color> colorSupplier) {
        int slotId = accountStatus.findEmptySlot();
        if (slotId == -1) {
            return;
        }
        Widget buyButton = grandExchange.getBuyButton(slotId);
        if (buyButton != null && !buyButton.isHidden()) {
            add(buyButton, colorSupplier, new Rectangle(0, 0, 45, 44));
        }
    }

    private void drawOfferScreenHighlights(Suggestion suggestion) {
        boolean flashHighlight = suggestion.isBuyDumpSuggestion();
        Supplier<Color> blueHighlight = () -> highlightColorController.getBlueColor(flashHighlight);
        GEOfferScreenSetupOfferState s = grandExchange.getOfferScreenSetupOfferState();
        if (s == null) {
            return;
        }

        if (s.offerDetailsCorrect(suggestion)) {
            highlightConfirm(blueHighlight);
            return;
        }

        boolean offerTypeMatches = Objects.equals(s.offerType, suggestion.offerType());
        boolean itemMatches = s.currentItemId == suggestion.getItemId();

        // Prioritise certain buy dump alert cases
        if (suggestion.isBuyDumpSuggestion()) {
            if (!offerTypeMatches || accountStatusManager.getAccountStatus().isCollectNeeded(suggestion, grandExchange.isSetupOfferOpen())) {
                highlightBackButton(blueHighlight);
            } else if (!s.searchOpen && s.currentItemId != -1 && !itemMatches) {
                highlightItemSearchButton(blueHighlight);
            } else if (itemMatches) {
                if (s.offerPrice != suggestion.getPrice()) {
                    highlightPrice(blueHighlight);
                }
                highlightQuantity(suggestion, s.offerQuantity, blueHighlight);
            } else if (s.searchOpen) {
                highlightItemInSearch(suggestion, blueHighlight);
            }
            return;
        }

        // Custom item choice case
        if (isCustomChoiceItem(s, offerTypeMatches, itemMatches)) {
            if (s.offerPrice == offerManager.getViewedSlotItemPrice()) {
                highlightConfirm(blueHighlight);
            } else {
                highlightPrice(blueHighlight);
            }
            return;
        }

        // Standard suggestion case
        if (offerTypeMatches && itemMatches) {
            if (s.offerPrice != suggestion.getPrice()) {
                highlightPrice(blueHighlight);
            }
            highlightQuantity(suggestion, s.offerQuantity, blueHighlight);
            return;
        }
        if (suggestion.isAbortSuggestion()
                || ((suggestion.isSellSuggestion() || suggestion.isModifySuggestion()) && s.isEmptyBuyState())) {
            highlightBackButton(blueHighlight);
            return;
        }
        if(offerTypeMatches && s.currentItemId == -1 && s.searchOpen) {
            highlightItemInSearch(suggestion,blueHighlight);
            return;
        }

    }

    private boolean isCustomChoiceItem(GEOfferScreenSetupOfferState s, boolean offerTypeMatches, boolean itemMatches) {
        return s.currentItemId != -1 && ((!offerTypeMatches && s.offerType.equals("sell"))|| (!s.searchOpen && !itemMatches))
                && s.currentItemId == offerManager.getViewedSlotItemId()
                && offerManager.getViewedSlotItemPrice() > -1;
    }

    private void highlightItemInSearch(Suggestion suggestion, Supplier<Color> colorSupplier) {
        if (!client.getVarcStrValue(VarClientStr.INPUT_TEXT).isEmpty()) {
            return;
        }
        Widget searchResults = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        if (searchResults == null) {
            return;
        }
        for (Widget widget : searchResults.getDynamicChildren()) {
            if (widget.getName().equals("<col=ff9040>" + suggestion.getName() + "</col>")) {
                add(widget, colorSupplier);
                return;
            }
        }
        Widget itemWidget = searchResults.getChild(3);
        if (itemWidget != null && itemWidget.getItemId() == suggestion.getItemId()) {
            add(itemWidget, colorSupplier);
        }
    }


    private void highlightPrice(Supplier<Color> colorSupplier) {
        Widget setPriceButton = grandExchange.getSetPriceButton();
        if (setPriceButton != null) {
            add(setPriceButton, colorSupplier, new Rectangle(1, 6, 33, 23));
        }
    }

    private void highlightQuantity(Suggestion suggestion, int offerQuantity, Supplier<Color> colorSupplier) {
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        if (offerQuantity != suggestion.getQuantity()) {
            Widget setQuantityButton;
            if (accountStatus.getInventory().getTotalAmount(suggestion.getItemId()) == suggestion.getQuantity()
                && suggestion.isSellSuggestion()) {
                setQuantityButton = grandExchange.getSetQuantityAllButton();
            } else {
                setQuantityButton = grandExchange.getSetQuantityButton();
            }
            if (setQuantityButton != null) {
                add(setQuantityButton, colorSupplier, new Rectangle(1, 6, 33, 23));
            }
        }
    }

    private void highlightConfirm(Supplier<Color> colorSupplier) {
        Widget confirmButton = grandExchange.getConfirmButton();
        if (confirmButton != null) {
            add(confirmButton, colorSupplier, new Rectangle(1, 1, 150, 38));
        }
    }

    private Widget getItemSearchButtonWidget() {
        Widget setupContainer = client.getWidget(465, 26);
        if (setupContainer == null) {
            return null;
        }
        Widget[] children = setupContainer.getChildren();
        if (children != null && children.length > 0) {
            return children[0];
        }
        return null;
    }

    private void highlightItemSearchButton(Supplier<Color> colorSupplier) {
        Widget searchWidget = getItemSearchButtonWidget();
        if (searchWidget != null) {
            add(searchWidget, colorSupplier);
        }
    }

    private void highlightBackButton(Supplier<Color> colorSupplier) {
        Widget backButton = grandExchange.getBackButton();
        if (backButton != null) {
            add(backButton, colorSupplier);
        }
    }

    private void add(Widget widget, Supplier<Color> colorSupplier, Rectangle adjustedBounds) {
        if (!active || widget == null) {
            return;
        }
        final int addGeneration = generation.get();
        SwingUtilities.invokeLater(() -> {
            if (!active || generation.get() != addGeneration) {
                return;
            }
            WidgetHighlightOverlay overlay = new WidgetHighlightOverlay(widget, colorSupplier, adjustedBounds);
            highlightOverlays.add(overlay);
            overlayManager.add(overlay);
        });
    }

    private void add(Widget widget, Supplier<Color> colorSupplier) {
        if (widget == null) {
            return;
        }
        add(widget, colorSupplier, new Rectangle(0, 0, widget.getWidth(), widget.getHeight()));
    }

    public void removeAll() {
        final int clearGeneration = generation.incrementAndGet();
        SwingUtilities.invokeLater(() -> {
            clearOverlaysIfCurrentGeneration(clearGeneration);
        });
    }

    private void clearOverlaysIfCurrentGeneration(int expectedGeneration) {
        if (generation.get() != expectedGeneration) {
            return;
        }
        highlightOverlays.forEach(overlayManager::remove);
        highlightOverlays.clear();
    }

    private Widget getInventoryItemWidget(int unnotedItemId) {
        // Only the GE-specific inventory widget is relevant here — the regular inventory
        // (149,0) is shown when the GE is closed, and we don't highlight items in that case.
        Widget inventory = client.getWidget(467, 0);
        if (inventory == null) {
            return null;
        }

        Widget[] children = inventory.getDynamicChildren();
        if (children == null) {
            return null;
        }

        Widget notedWidget = null;
        Widget unnotedWidget = null;

        for (Widget widget : children) {
            if (widget == null) {
                continue;
            }

            int itemId = widget.getItemId();
            ItemComposition itemComposition = client.getItemDefinition(itemId);

            if (itemComposition.getNote() != -1) {
                if (itemComposition.getLinkedNoteId() == unnotedItemId) {
                    notedWidget = widget;
                }
            } else if (itemId == unnotedItemId) {
                unnotedWidget = widget;
            }
        }
        return notedWidget != null ? notedWidget : unnotedWidget;
    }

    private Widget getBankItemWidget(int unnotedItemId) {
        for (int childId : BANK_ITEM_CONTAINER_CHILDREN) {
            Widget bankItems = client.getWidget(BANK_WIDGET_GROUP, childId);
            if (bankItems == null || bankItems.isHidden()) {
                continue;
            }

            Widget itemWidget = getVisibleItemWidget(bankItems, unnotedItemId);
            if (itemWidget != null) {
                return itemWidget;
            }
        }
        return null;
    }

    private boolean isBankOpen() {
        Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        return bank != null && !bank.isHidden();
    }

    private Widget getBankCloseButton() {
        Widget frame = client.getWidget(InterfaceID.Bankmain.FRAME);
        if (frame == null || frame.getDynamicChildren() == null) {
            return null;
        }
        Widget[] children = frame.getDynamicChildren();
        if (children.length <= BANK_CLOSE_BUTTON_INDEX) {
            return null;
        }
        return children[BANK_CLOSE_BUTTON_INDEX];
    }

    private Widget getGrandExchangeCloseButton() {
        Widget frame = client.getWidget(InterfaceID.GeOffers.FRAME);
        if (frame == null || frame.getDynamicChildren() == null) {
            return null;
        }
        Widget[] children = frame.getDynamicChildren();
        if (children.length <= GE_CLOSE_BUTTON_INDEX) {
            return null;
        }
        return children[GE_CLOSE_BUTTON_INDEX];
    }

    private Widget getPortfolioBankTagButton() {
        if (!config.portfolioBankTag()
                || !BankTagsUtil.isActive(pluginManager)
                || PORTFOLIO_BANK_TAG.equals(bankTagsService.getActiveTag())) {
            return null;
        }

        Widget parent = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
        if (parent == null || parent.isHidden() || parent.getChildren() == null) {
            return null;
        }

        Widget[] children = parent.getChildren();
        for (int i = BANK_TAG_TAB_CHILD_OFFSET; i < children.length; i += 2) {
            Widget button = children[i];
            if (button == null || button.isHidden()) {
                continue;
            }

            String widgetName = button.getName();
            if (widgetName == null) {
                continue;
            }

            if (PORTFOLIO_BANK_TAG.equals(Text.removeTags(widgetName))) {
                return button;
            }
        }
        return null;
    }

    private Widget getVisibleItemWidget(Widget itemContainer, int unnotedItemId) {
        Widget[] children = itemContainer.getDynamicChildren();
        if (children == null) {
            return null;
        }

        Rectangle containerBounds = itemContainer.getBounds();
        boolean clipToContainerBounds = hasUsableBounds(containerBounds);
        for (Widget widget : children) {
            if (widget == null || widget.isHidden() || widget.getItemQuantity() <= 0) {
                continue;
            }

            if (!matchesItemId(widget.getItemId(), unnotedItemId)) {
                continue;
            }

            Rectangle bounds = widget.getBounds();
            if (clipToContainerBounds && (bounds == null || !containerBounds.intersects(bounds))) {
                continue;
            }

            return widget;
        }
        return null;
    }

    private boolean hasUsableBounds(Rectangle bounds) {
        return bounds != null && bounds.width > 0 && bounds.height > 0;
    }

    private boolean matchesItemId(int itemId, int unnotedItemId) {
        if (itemId == unnotedItemId) {
            return true;
        }
        if (itemId <= 0) {
            return false;
        }

        ItemComposition itemComposition = client.getItemDefinition(itemId);
        return itemComposition.getNote() != -1 && itemComposition.getLinkedNoteId() == unnotedItemId;
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.PortfolioStateRS;
import com.flippingcopilot.ui.UIUtilities;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.List;

@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class InventorySlotTooltipDataProvider {

    private final ItemManager itemManager;
    private final SuggestionManager suggestionManager;
    private final ItemController itemController;
    private final PortfolioStateRS portfolioStateRS;

    public InventorySlotTooltipData getTooltipData(int itemId, int quantity, TooltipHoverSource source) {
        if (!portfolioStateRS.get().isLoaded()) {
            return null;
        }
        int unnotedItemId = itemController.toUnnotedItemId(itemId);
        PortfolioItemCardData itemData = portfolioStateRS.get().getItemCardDataByItemId().get(unnotedItemId);
        if (itemData == null) {
            return null;
        }

        String itemName = itemManager.getItemComposition(itemData.getItemId()).getName();
        Suggestion suggestion = suggestionManager.getSuggestion();
        Suggestion.PortfolioItem portfolioItem = findPortfolioItem(suggestion, itemData.getItemId());
        List<String> lines = buildTooltipLines(itemData, portfolioItem, source);
        return new InventorySlotTooltipData(itemData.getItemId(), quantity, itemName, lines);
    }

    private List<String> buildTooltipLines(PortfolioItemCardData itemData, Suggestion.PortfolioItem portfolioItem, TooltipHoverSource source) {
        boolean inPortfolio = itemData.isInPortfolio();

        List<String> lines = new ArrayList<>(5);

        lines.add(formatQuantityLine(itemData.getRuneliteInventoryQuantity(), itemData.getSuggestionBankQuantity(), source));
        if (itemData.isPartiallyInPortfolio()) {
            lines.add("Quantity in Portfolio: " + NumberFormat.getIntegerInstance().format(itemData.getPortfolioQuantity()));
        }
        if (!inPortfolio) {
            Long totalValue = calculateValue(itemData);
            lines.add("Total value: " + (totalValue == null ? "Unknown" : UIUtilities.formatProfit(totalValue)));
        } else {
            lines.add("Time held: " + UIUtilities.formatDurationMinutes(itemData.getHeldMinutes()));
            lines.add("Avg buy price: " + (portfolioItem == null || portfolioItem.getAmount() <= 0
                    ? "Unknown"
                    : UIUtilities.formatProfit(portfolioItem.getUnitBuyPrice())));
            Long totalValue = calculateValue(itemData);
            lines.add("Total value: " + (totalValue == null ? "Unknown" : UIUtilities.formatProfit(totalValue)));
            Long unrealizedProfit = itemData.getUnrealizedUnitProfit() == null ? null : itemData.inventoryTooltipUnrealizedProfit();
            lines.add("Unrealized Profit: " + (unrealizedProfit == null ? "Unknown" : UIUtilities.formatProfit(unrealizedProfit)));
            String unrealizedRoi = calculateUnrealizedRoi(itemData, portfolioItem);
            lines.add("Unrealized ROI: " + (unrealizedRoi == null ? "Unknown" : unrealizedRoi));
        }
        return lines;
    }

    private String calculateUnrealizedRoi(PortfolioItemCardData itemData, Suggestion.PortfolioItem portfolioItem) {
        if (portfolioItem == null || portfolioItem.getAmount() <= 0 || portfolioItem.getUnitBuyPrice() <= 0 || itemData.getUnrealizedUnitProfit() == null) {
            return null;
        }
        double roi = (double) itemData.getUnrealizedUnitProfit() / (double) portfolioItem.getUnitBuyPrice();
        return String.format("%.2f%%", roi * 100.0d);
    }

    private Suggestion.PortfolioItem findPortfolioItem(Suggestion suggestion, int itemId) {
        if (suggestion == null || suggestion.getPortfolioItems() == null || suggestion.getPortfolioItems().isEmpty()) {
            return null;
        }
        for (Suggestion.PortfolioItem portfolioItem : suggestion.getPortfolioItems()) {
            if (portfolioItem != null && portfolioItem.getItemId() == itemId) {
                return portfolioItem;
            }
        }
        return null;
    }

    private Long calculateValue(PortfolioItemCardData itemData) {
        long unitPrice = itemData.getPostTaxSellUnitPrice();
        if (unitPrice <= 0) {
            return null;
        }
        long totalQuantity = Math.max(0L, (long) itemData.getRuneliteInventoryQuantity() + itemData.getSuggestionBankQuantity());
        return unitPrice * totalQuantity;
    }

    private String formatQuantityLine(int inventoryQuantity, long bankQuantity, TooltipHoverSource source) {
        NumberFormat fmt = NumberFormat.getIntegerInstance();
        String invPart = "Inventory: " + fmt.format(Math.max(0, inventoryQuantity));
        String bankPart = "Bank: " + fmt.format(Math.max(0L, bankQuantity));

        if (source == TooltipHoverSource.BANK) {
            if (inventoryQuantity <= 0) {
                return bankPart;
            }
            return bankPart + ", " + invPart;
        }
        if (bankQuantity <= 0) {
            return invPart;
        }
        return invPart + ", " + bankPart;
    }

}

package com.flippingcopilot.controller;

import com.flippingcopilot.model.Transaction;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

@Slf4j
public class Persistance {
    public static Gson gson;
    public static final File COPILOT_DIR = new File(RuneLite.RUNELITE_DIR, "flipping-copilot");
    public static final String UN_ACKED_TRANSACTIONS_FILE_TEMPLATE = "%s_un_acked.jsonl";
    public static final String LOGIN_RESPONSE_JSON_FILE = "login-response.json";
    public static File directory;

    public static void setUp(String directoryPath) throws IOException {
        directory = new File(directoryPath);
        createDirectory(directory);
        createRequiredFiles();
    }

    public static void setUp(Gson gson) throws IOException {
        Persistance.gson = gson;
        directory = COPILOT_DIR;
        createDirectory(COPILOT_DIR);
        createRequiredFiles();
    }

    public static boolean hasExistingInstallation() {
        if (!COPILOT_DIR.exists() || !COPILOT_DIR.isDirectory()) {
            return false;
        }

        String[] files = COPILOT_DIR.list();
        return files != null && files.length > 0;
    }

    private static void createRequiredFiles() throws IOException {
        generateFileIfDoesNotExist(LOGIN_RESPONSE_JSON_FILE);
    }

    private static void generateFileIfDoesNotExist(String filename) throws IOException {
        File file = new File(directory, filename);
        if (!file.exists()) {
            if (!file.createNewFile()) {
                log.info("Failed to generate file {}", file.getPath());
            }
        }
    }

    private static void createDirectory(File directory) throws IOException {
        if (!directory.exists()) {
            if (!directory.mkdir()) {
                throw new IOException("unable to create parent directory!");
            }
        }
    }


    public static List<Transaction> loadUnAckedTransactions(String displayName) {
        List<Transaction> transactions = new ArrayList<>();
        File file = new File(COPILOT_DIR, String.format(UN_ACKED_TRANSACTIONS_FILE_TEMPLATE, hashDisplayName(displayName)));
        if (!file.exists()) {
            log.info("no existing un acked transactions file for {}", displayName);
            return new ArrayList<>();
        }
        Set<UUID> added = new HashSet<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.isEmpty()) {
                    continue;
                }
                try {
                    Transaction transaction = gson.fromJson(line, Transaction.class);
                    // there was previously a bug where the same transaction was being added many times to the list
                    // just clean things here to be safe
                    if (!added.contains(transaction.getId())) {
                        transactions.add(transaction);
                        added.add(transaction.getId());
                    }
                } catch (JsonSyntaxException e) {
                    log.warn("error deserializing transaction line '{}' file {}", line, file, e);
                }
            }
        } catch (FileNotFoundException e) {
            log.info("no existing un acked transactions file for {}", displayName);
            return new ArrayList<>();
        } catch (IOException e) {
            log.warn("error loading un acked transaction file {}", file, e);
            return new ArrayList<>();
        } catch (JsonSyntaxException e) {
            log.warn("corrupted un acked transaction file {}", file, e);
            return new ArrayList<>();
        }
        log.info("loaded {} stored transactions for {}", transactions.size(), displayName);
        return transactions;
    }

    public static void storeUnAckedTransactions(List<Transaction> transactions, String displayName) {
        File unackedTransactionsFile = new File(COPILOT_DIR, String.format(UN_ACKED_TRANSACTIONS_FILE_TEMPLATE, hashDisplayName(displayName)));
        try (BufferedWriter w = new BufferedWriter(new FileWriter(unackedTransactionsFile, false))) {
            for (Transaction transaction : transactions) {
                String json = gson.toJson(transaction);
                w.write(json);
                w.newLine();
            }
        } catch (IOException e) {
            log.warn("error storing un acked transactions to file {}", unackedTransactionsFile, e);
        }
    }

    public static String hashDisplayName(String displayName) {
        if(displayName == null) {
            return "null";
        }
        // we hash the display name just to ensure that it's a valid file name
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-1");
            byte[] hashBytes = digest.digest(displayName.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not available", e);
        }
    }
}

