	}

	@Subscribe
	public void onVarClientStrChanged(VarClientStrChanged event) {
		gameUiChangesHandler.onVarClientStrChanged(event);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
				sessionManager.reset();
				suggestionManager.reset();
				osrsLoginManager.reset();
				accountStatusManager.reset();
				grandExchangeUncollectedManager.reset();
				statsPanel.refresh(true, copilotLoginRS.get().isLoggedIn() && osrsLoginManager.isValidLoginState());
				osrsLoginRS.set(osrsLoginRS.get().nextState(client));
				mainPanel.refresh();
				break;
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				osrsLoginManager.setLastLoginTick(client.getTickCount());
				osrsLoginRS.set(osrsLoginRS.get().nextState(client));
				break;
			case LOGGED_IN:
				// we want to update the flips panel on login but unfortunately the display name
				// is not available immediately so schedule what we need to do here for in the future
				// todo: move to just using the accountHash which is available immediately to simply things
				clientThread.invokeLater(() -> {
					if (client.getGameState() != GameState.LOGGED_IN) {
						return true;
					}
					final String name = osrsLoginManager.getPlayerDisplayName();
					if(name == null) {
						return false;
					}
					statsPanel.resetIntervalDropdownToSession();
					Integer accountId = copilotLoginRS.get().getAccountId(name);
					if (accountId != null && accountId != -1) {
						flipManager.setIntervalAccount(accountId);
					} else {
						flipManager.setIntervalAccount(null);
					}
					flipManager.setIntervalStartTime(sessionManager.getCachedSessionData().startTime);
					statsPanel.refresh(true, copilotLoginRS.get().isLoggedIn()  && osrsLoginManager.isValidLoginState());
					mainPanel.refresh();
					if(copilotLoginRS.get().isLoggedIn()) {
						transactionManager.scheduleSyncIn(0, name);
					}
					return true;
				});
		}
	}

	@Subscribe
	public void onVarClientIntChanged(VarClientIntChanged event) {
		gameUiChangesHandler.onVarClientIntChanged(event);
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown clientShutdownEvent) {
		log.debug("client shutdown event received");
		offerManager.saveAll();
		if(copilotLoginRS.get().isLoggedIn()) {
			String displayName = osrsLoginManager.getLastDisplayName();
			Integer accountId = copilotLoginRS.get().getAccountId(displayName);
			if (accountId != null && accountId != -1) {
				webHookController.sendMessage(flipManager.calculateStats(sessionManager.getCachedSessionData().startTime, accountId), sessionManager.getCachedSessionData(), displayName, false);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (event.getGroup().equals("flippingcopilot")) {
			log.debug("copilot config changed event received");
			configRS.forceSet(config);
			if (event.getKey().equals("profitAmountColor") || event.getKey().equals("lossAmountColor")) {
				mainPanel.copilotPanel.statsPanel.refresh(true, copilotLoginRS.get().isLoggedIn() && osrsLoginManager.isValidLoginState());
			}
			if (event.getKey().equals("suggestionHighlights")) {
				clientThread.invokeLater(() -> highlightController.redraw());
			}
			if (event.getKey().equals("slotPriceColorEnabled")) {
				handleSlotPriceColorConfigChange();
			}
			if (event.getKey().equals("slotPriceProfitableColor") || event.getKey().equals("slotPriceUnprofitableColor")) {
				clientThread.invokeLater(() -> {
					slotProfitColorizer.updateAllSlots();
					highlightController.redraw();
				});
			}
			if (event.getKey().equals("portfolioBankTag")) {
				portfolioBankTagController.onConfigChanged();
			}
		}
	}

	private void handleSlotPriceColorConfigChange() {
		if (config.slotPriceColorEnabled()) {
			clientThread.invokeLater(() -> slotProfitColorizer.updateAllSlots());
		} else {
			clientThread.invokeLater(() -> slotProfitColorizer.resetAllSlots());
		}
	}
}

package com.flippingcopilot.controller;

import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PlayerLocationController {
    private static final WorldPoint GRAND_EXCHANGE_CENTER = new WorldPoint(3165, 3484, 0);
    private static final int NEAR_GE_DISTANCE_TILES = 20;

    private final Client client;

    public boolean isNearGE() {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return false;
        }

        WorldPoint playerLocation = localPlayer.getWorldLocation();
        if (playerLocation == null || playerLocation.getPlane() != GRAND_EXCHANGE_CENTER.getPlane()) {
            return false;
        }

        return playerLocation.distanceTo2D(GRAND_EXCHANGE_CENTER) <= NEAR_GE_DISTANCE_TILES;
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.model.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.*;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Slf4j
public class GePreviousSearch {

    private final SuggestionManager suggestionManager;
    private final SuggestionPreferencesManager suggestionPreferencesManager;
    private final AccountStatusManager accountStatusManager;
    private final GrandExchange grandExchange;
    private final HighlightController highlightController;
    private final Client client;


    public void showSuggestedItemInSearch() {
        Suggestion suggestion = suggestionManager.getSuggestion();
        if (suggestion == null) {
            return;
        }

        if (isScanningForDumpsSuggested(suggestion)) {
            if ((grandExchange.isPreviousSearchSet() || copilotPreviousSearchItemExists()) && grandExchange.showLastSearchEnabled()) {
                setScanningForDumpsMessage();
            } else {
                createPreviousSearchWidget(-1, "");
                createPreviousSearchItemNameWidget("");
                createPreviousSearchItemWidget(-1);
                createPreviousSearchTextWidget();
                setScanningForDumpsMessage();
            }
            highlightController.redraw();
            return;
        }

        if (suggestion.getType() == SuggestionType.BUY) {
            if ((grandExchange.isPreviousSearchSet() || copilotPreviousSearchItemExists()) && grandExchange.showLastSearchEnabled()) {
                setPreviousSearch(suggestion.getItemId(), suggestion.getName());
            } else {
                createPreviousSearchWidget(suggestion.getItemId(), suggestion.getName());
                createPreviousSearchItemNameWidget(suggestion.getName());
                createPreviousSearchItemWidget(suggestion.getItemId());
                createPreviousSearchTextWidget();
            }
            highlightController.redraw();
        }
    }

    private boolean isScanningForDumpsSuggested(Suggestion suggestion) {
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        return accountStatus != null
                && suggestion.isWaitSuggestion()
                && grandExchange.isOpen()
                && accountStatus.emptySlotExists()
                && !accountStatus.moreGpNeeded()
                && suggestionPreferencesManager.isReceiveDumpSuggestions();
    }

    private boolean copilotPreviousSearchItemExists() {
        Widget searchResults = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        if(searchResults == null || searchResults.getChildren() == null || searchResults.getChildren().length < 2) {
            return false;
        }
        for (int i = 0; i < searchResults.getChildren().length; i++) {
            Widget child = searchResults.getChild(i);
            if (child == null) {
                continue;
            }
            String text = child.getText();
            if (text == null) {
                continue;
            }
            if(text.startsWith("Copilot item:") || text.startsWith("Waiting for dumps...")) {
                return true;
            }
        }
        return false;
    }

    private void setPreviousSearch(int itemId, String itemName) {
        Widget searchResults = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        Widget previousSearch = searchResults.getChild(0);
        previousSearch.setHasListener(true);
        previousSearch.setOnOpListener(754, itemId, 84);
        previousSearch.setOnKeyListener(754, itemId, -2147483640);
        previousSearch.setName("<col=ff9040>" + itemName + "</col>");
        previousSearch.setAction(0, "Select");
        previousSearch.revalidate();

        Widget previousSearchText = searchResults.getChild(1);
        previousSearchText.setText("Copilot item:");
        previousSearchText.setOriginalWidth(95);
        previousSearchText.setXTextAlignment(WidgetTextAlignment.LEFT);
        previousSearchText.revalidate();

        Widget itemNameWidget = searchResults.getChild(2);
        itemNameWidget.setText(itemName);
        itemNameWidget.revalidate();

        Widget item = searchResults.getChild(3);
        item.setItemId(itemId);
        item.revalidate();
    }

    private void setScanningForDumpsMessage() {
        Widget searchResults = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        if (searchResults == null) {
            return;
        }

        Widget previousSearch = searchResults.getChild(0);
        if (previousSearch != null) {
            previousSearch.setHasListener(false);
            previousSearch.setName("");
            previousSearch.setAction(0, "");
            previousSearch.revalidate();
        }

        Widget previousSearchText = searchResults.getChild(1);
        if (previousSearchText != null) {
            previousSearchText.setText("Waiting for dumps...");
            previousSearchText.setOriginalWidth(256);
            previousSearchText.setXTextAlignment(WidgetTextAlignment.CENTER);
            previousSearchText.revalidate();
        }

        Widget itemNameWidget = searchResults.getChild(2);
        if (itemNameWidget != null) {
            itemNameWidget.setText("");
            itemNameWidget.revalidate();
        }

        Widget item = searchResults.getChild(3);
        if (item != null) {
            item.setItemId(-1);
            item.revalidate();
        }
    }

    private void createPreviousSearchWidget(int itemId, String itemName) {
        Widget parentWidget = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        Widget widget = parentWidget.createChild(0, WidgetType.RECTANGLE);
        widget.setTextColor(0xFFFFFF);
        widget.setOpacity(255);
        widget.setName("<col=ff9040>" + itemName + "</col>");
        widget.setHasListener(true);
        widget.setFilled(true);
        widget.setOriginalX(114);
        widget.setOriginalY(0);
        widget.setOriginalWidth(256);
        widget.setOriginalHeight(32);
        widget.setOnOpListener(754, itemId, 84);
        widget.setOnKeyListener(754, itemId, -2147483640);
        widget.setHasListener(true);
        widget.setAction(0, "Select");
        // set opacity to 200 when mouse is hovering
        widget.setOnMouseOverListener((JavaScriptCallback) ev -> {
            widget.setOpacity(200);
        });
        // set opacity back to 255 when mouse is not hovering
        widget.setOnMouseLeaveListener((JavaScriptCallback) ev -> {
            widget.setOpacity(255);
        });

        widget.revalidate();
    }

    private void createPreviousSearchTextWidget() {
        Widget parentWidget = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        Widget widget = parentWidget.createChild(1, WidgetType.TEXT);
        widget.setText("Copilot item:");
        widget.setFontId(495);
        widget.setOriginalX(114);
        widget.setOriginalY(0);
        widget.setOriginalWidth(95);
        widget.setOriginalHeight(32);
        widget.setYTextAlignment(1);
        widget.revalidate();
    }

    private void createPreviousSearchItemNameWidget(String itemName) {
        Widget parentWidget = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        Widget widget = parentWidget.createChild(2, WidgetType.TEXT);
        widget.setText(itemName);
        widget.setFontId(495);
        widget.setOriginalX(254);
        widget.setOriginalY(0);
        widget.setOriginalWidth(116);
        widget.setOriginalHeight(32);
        widget.setYTextAlignment(1);
        widget.revalidate();
    }

    private void createPreviousSearchItemWidget(int itemId) {
        Widget parentWidget = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
        Widget widget = parentWidget.createChild(3, WidgetType.GRAPHIC);
        widget.setItemId(itemId);
        widget.setItemQuantity(1);
        widget.setItemQuantityMode(0);
        widget.setRotationX(550);
        widget.setModelZoom(1031);
        widget.setBorderType(1);
        widget.setOriginalX(214);
        widget.setOriginalY(0);
        widget.setOriginalWidth(36);
        widget.setOriginalHeight(32);
        widget.revalidate();
    }


}

package com.flippingcopilot.controller;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.BankStateRS;
import com.flippingcopilot.rs.PortfolioStateRS;
import com.flippingcopilot.ui.flipsdialog.FlipsDialogController;
import com.flippingcopilot.ui.graph.model.PriceLine;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.api.*;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Map;
import java.util.function.Consumer;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class MenuHandler {

    private static final int BANK_WIDGET_GROUP = 12;
    private static final int[] BANK_ITEM_CONTAINER_CHILDREN = {12, 13, 89};
    private static final int BANK_INVENTORY_WIDGET_GROUP = 15;
    private static final int BANK_INVENTORY_WIDGET_CHILD = 3;

    private final FlippingCopilotConfig config;
    private final Client client;
    private final OfferManager offerManager;
    private final GrandExchange grandExchange;
    private final SuggestionManager suggestionManager;
    private final FlipsDialogController flipsDialogController;
    private final ItemController itemController;
    private final PortfolioController portfolioController;
    private final CopilotLoginController copilotLoginController;
    private final ApiRequestHandler apiRequestHandler;
    private final PortfolioStateRS portfolioStateRS;
    private final BankStateRS bankStateRS;
    private final ClientThread clientThread;
    private final PlayerLocationController playerLocationController;
    private final ChatboxPanelManager chatboxPanelManager;

    private static final String MENU_ADD = "Add-All to portfolio";
    private static final String MENU_ADD_X = "Add-X to portfolio";
    private static final String MENU_REMOVE = "Remove-All from portfolio";
    private static final String MENU_REMOVE_X = "Remove-X from portfolio";

    private enum MenuLocation { INVENTORY, BANK }


    public void injectCopilotPriceGraphMenuEntry(MenuEntryAdded event) {
        if (!playerLocationController.isNearGE()) {
            return;
        }

        if(!config.priceGraphMenuOptionEnabled()) {
            return;
        }
        if (event.getOption().equals("View offer")) {
            long slotWidgetId = event.getActionParam1();
            String menuTarget = event.getTarget();
            client.getMenu()
                    .createMenuEntry(-1)
                    .setOption("Copilot graph")
                    .setTarget(menuTarget)
                    .onClick((MenuEntry e) -> {
                        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
                        for (int i = 0; i < offers.length; i++) {
                            Widget slotWidget = client.getWidget(465, 7 + i);
                            if (slotWidget != null && slotWidget.getId() == slotWidgetId) {
                                int itemId = offers[i].getItemId();
                                PriceLine priceLine = buildPriceLine(offers[i]);
                                flipsDialogController.showPriceGraphTab(itemId, false, priceLine);
                                log.debug("matched widget to slot {}, item {}", i, offers[i].getItemId());
                            }
                        }
                    });
        } else if (shouldAddInventoryPriceGraphEntry(event)) {
            int inventorySlot = event.getActionParam0();
            int inventoryWidgetId = event.getActionParam1();
            Widget inventoryWidget = client.getWidget(inventoryWidgetId);
            if (inventoryWidget == null || inventorySlot < 0) {
                return;
            }
            Widget[] items = inventoryWidget.getDynamicChildren();
            if (items == null || inventorySlot >= items.length) {
                return;
            }
            Widget itemWidget = items[inventorySlot];
            if (itemWidget == null || itemWidget.getItemId() <= 0) {
                return;
            }
            int itemId = itemWidget.getItemId();
            if (!isGeTradableItem(itemId)) {
                return;
            }
            String menuTarget = resolveMenuTarget(event.getTarget(), itemId);
            int graphItemId = toUnnotedItemId(itemId);
            client.getMenu()
                    .createMenuEntry(-1)
                    .setOption("Copilot graph")
                    .setTarget(menuTarget)
                    .onClick((MenuEntry e) -> flipsDialogController.showPriceGraphTab(graphItemId, false, null));
        }
    }

    public void injectInventoryPortfolioMenuEntry(MenuEntryAdded event) {
        if (!playerLocationController.isNearGE()) {
            return;
        }

        InventoryMenuItem menuItem = getInventoryMenuItem(event);
        if (menuItem == null) {
            return;
        }
        if (!portfolioStateRS.get().isLoaded()) {
            return;
        }

        Integer accountId = copilotLoginController.getActiveAccountId();
        PortfolioItemCardData cardData = portfolioStateRS.get().getItemCardDataByItemId().get(menuItem.unnotedItemId);

        int notInPortfolio = cardData == null ? 0 : cardData.getNotInPortfolioQuantity();
        int portfolioQty = cardData == null ? 0 : cardData.getPortfolioQuantity();
        int locationQty = getLocationQuantity(menuItem.unnotedItemId, menuItem.location);
        boolean showAdd = locationQty > 0 && (cardData == null || !cardData.isInPortfolio() || notInPortfolio > 0);
        boolean showRemove = locationQty > 0 && portfolioQty > 0;

        // Menu entries are added in reverse display order (last added = top of menu)

        // Remove X — cross-location custom amount, when portfolioQuantity > 1
        if (portfolioQty > 1) {
            addPortfolioMenuEntry(MENU_REMOVE_X, menuItem,
                    e -> promptQuantityAndToggle(menuItem, accountId, ToggleItemPortfolioRequest.REMOVE, "Enter quantity to remove:"));
        }

        // Remove (location-scoped) — removes only the qty present at the clicked location
        if (showRemove) {
            addPortfolioMenuEntry(MENU_REMOVE, menuItem,
                    e -> onTogglePortfolioClicked(menuItem, accountId, ToggleItemPortfolioRequest.REMOVE, locationQty));
        }

        // Add X — cross-location custom amount, when notInPortfolio > 1
        if (notInPortfolio > 1) {
            addPortfolioMenuEntry(MENU_ADD_X, menuItem,
                    e -> promptQuantityAndToggle(menuItem, accountId, PortfolioId.COFLIP_PORTFOLIO, "Enter quantity to add:"));
        }

        // Add (location-scoped) — adds only the qty present at the clicked location
        if (showAdd) {
            addPortfolioMenuEntry(MENU_ADD, menuItem,
                    e -> onTogglePortfolioClicked(menuItem, accountId, PortfolioId.COFLIP_PORTFOLIO, locationQty));
        }
    }

    private void addPortfolioMenuEntry(String option, InventoryMenuItem menuItem, Consumer<MenuEntry> onClick) {
        client.getMenu()
                .createMenuEntry(-1)
                .setOption(option)
                .setTarget(menuItem.menuTarget)
                .onClick(onClick);
    }

    private int getLocationQuantity(int itemId, MenuLocation location) {
        if (location == MenuLocation.INVENTORY) {
            Map<Integer, Integer> inv = itemController.getRunliteInventory();
            return inv == null ? 0 : Math.max(0, inv.getOrDefault(itemId, 0));
        }
        if (location == MenuLocation.BANK) {
            if (!bankStateRS.get().isLoaded()) {
                return 0;
            }
            Map<Integer, Integer> bank = bankStateRS.get().getItems();
            return bank == null ? 0 : Math.max(0, bank.getOrDefault(itemId, 0));
        }
        return 0;
    }

    private void promptQuantityAndToggle(InventoryMenuItem menuItem, Integer accountId, int portfolioId, String prompt) {
        chatboxPanelManager.openTextInput(prompt)
                .charValidator(c -> c >= '0' && c <= '9')
                .onDone((String input) -> {
                    if (input == null || input.isEmpty()) {
                        return;
                    }
                    try {
                        int qty = Integer.parseInt(input);
                        if (qty > 0) {
                            onTogglePortfolioClicked(menuItem, accountId, portfolioId, qty);
                        }
                    } catch (NumberFormatException ignored) {
                    }
                })
                .build();
    }

    private void onTogglePortfolioClicked(InventoryMenuItem menuItem, Integer accountId, int portfolioId, int quantity) {
        if (accountId == null) {
            return;
        }
        clientThread.invokeLater(() -> {
            Map<Integer, Integer> runeliteInventory = itemController.getRunliteInventory();
            int bagQuantity = runeliteInventory == null ? 0 : Math.max(0, runeliteInventory.getOrDefault(menuItem.unnotedItemId, 0));

            int bankQuantity;
            if (bankStateRS.get().isLoaded()) {
                bankQuantity = Math.max(0, bankStateRS.get().getItems().getOrDefault(menuItem.unnotedItemId, 0));
            } else {
                bankQuantity = -1;
            }

            ToggleItemPortfolioRequest request = new ToggleItemPortfolioRequest(accountId, menuItem.unnotedItemId, portfolioId, bagQuantity, bankQuantity, quantity);
            apiRequestHandler.toggleItemPortfolioAsync(
                    request,
                    (userId, result) -> {
                        portfolioStateRS.updatePortfolioState(suggestionManager.getSuggestion(), result);
                        suggestionManager.setSuggestionNeeded(true);
                        int itemsUpdated = result == null || result.getPortfolioItems() == null ? 0 : result.getPortfolioItems().size();
                        log.info("toggle portfolio succeeded for item_id={}, account_id={}, portfolio_id={}, quantity={}, portfolio_items_updated={}", menuItem.unnotedItemId, accountId, portfolioId, quantity, itemsUpdated);
                    },
                    error -> log.warn("toggle portfolio failed for item_id={}, account_id={}, portfolio_id={}, quantity={}, status={}, message={}", menuItem.unnotedItemId, accountId, portfolioId, quantity, error.getResponseCode(), error.getResponseMessage())
            );
            return true;
        });
    }

    private boolean shouldAddInventoryPriceGraphEntry(MenuEntryAdded event) {
        if (!grandExchange.isOpen() || !event.getOption().equals("Examine")) {
            return false;
        }
        int widgetId = event.getActionParam1();
        Widget geInventoryWidget = client.getWidget(467, 0);
        if (geInventoryWidget != null && geInventoryWidget.getId() == widgetId) {
            return true;
        }
        Widget inventoryWidget = client.getWidget(149, 0);
        return inventoryWidget != null && inventoryWidget.getId() == widgetId;
    }

    private MenuLocation getMenuLocation(int widgetId) {
        Widget geInventoryWidget = client.getWidget(467, 0);
        if (geInventoryWidget != null && geInventoryWidget.getId() == widgetId) {
            return MenuLocation.INVENTORY;
        }
        Widget inventoryWidget = client.getWidget(149, 0);
        if (inventoryWidget != null && inventoryWidget.getId() == widgetId) {
            return MenuLocation.INVENTORY;
        }
        Widget bankInventoryWidget = client.getWidget(BANK_INVENTORY_WIDGET_GROUP, BANK_INVENTORY_WIDGET_CHILD);
        if (bankInventoryWidget != null && bankInventoryWidget.getId() == widgetId) {
            return MenuLocation.INVENTORY;
        }
        for (int childId : BANK_ITEM_CONTAINER_CHILDREN) {
            Widget bankItemWidget = client.getWidget(BANK_WIDGET_GROUP, childId);
            if (bankItemWidget != null && bankItemWidget.getId() == widgetId) {
                return MenuLocation.BANK;
            }
        }
        return null;
    }

    private InventoryMenuItem getInventoryMenuItem(MenuEntryAdded event) {
        if (!"Examine".equals(event.getOption())) {
            return null;
        }

        int inventorySlot = event.getActionParam0();
        int inventoryWidgetId = event.getActionParam1();
        MenuLocation location = getMenuLocation(inventoryWidgetId);
        if (location == null) {
            return null;
        }

        Widget inventoryWidget = client.getWidget(inventoryWidgetId);
        if (inventoryWidget == null || inventorySlot < 0) {
            return null;
        }
        Widget[] items = inventoryWidget.getDynamicChildren();
        if (items == null || inventorySlot >= items.length) {
            return null;
        }
        Widget itemWidget = items[inventorySlot];
        if (itemWidget == null || itemWidget.getItemId() <= 0) {
            return null;
        }

        int unnotedItemId = itemController.toUnnotedItemId(itemWidget.getItemId());
        ItemComposition itemComposition = client.getItemDefinition(unnotedItemId);
        String itemName = itemComposition.getName();
        String menuTarget = resolveMenuTarget(event.getTarget(), unnotedItemId);
        return new InventoryMenuItem(unnotedItemId, itemName, menuTarget, location);
    }

    private static class InventoryMenuItem {
        private final int unnotedItemId;
        private final String itemName;
        private final String menuTarget;
        private final MenuLocation location;

        private InventoryMenuItem(int unnotedItemId, String itemName, String menuTarget, MenuLocation location) {
            this.unnotedItemId = unnotedItemId;
            this.itemName = itemName;
            this.menuTarget = menuTarget;
            this.location = location;
        }
    }

    private boolean isGeTradableItem(int itemId) {
        ItemComposition item = client.getItemDefinition(itemId);
        if (item.isGeTradeable()) {
            return true;
        }
        if (item.getNote() != -1) {
            int unnotedItemId = item.getLinkedNoteId();
            if (unnotedItemId > 0) {
                ItemComposition unnoted = client.getItemDefinition(unnotedItemId);
                return unnoted.isGeTradeable();
            }
        }
        return false;
    }

    private String resolveMenuTarget(String eventTarget, int itemId) {
        if (eventTarget != null && !eventTarget.isBlank()) {
            return eventTarget;
        }
        ItemComposition item = client.getItemDefinition(itemId);
        return "<col=ff9040>" + item.getName() + "</col>";
    }

    private int toUnnotedItemId(int itemId) {
        ItemComposition item = client.getItemDefinition(itemId);
        if (item.getNote() != -1 && item.getLinkedNoteId() > 0) {
            return item.getLinkedNoteId();
        }
        return itemId;
    }

    private PriceLine buildPriceLine(GrandExchangeOffer offer) {
        switch (offer.getState()) {
            case BOUGHT:
            case BUYING:
                return new PriceLine(
                        offer.getPrice(),
                        "offer buy price",
                        false
                );
            case SOLD :
            case SELLING:
                return new PriceLine(
                        offer.getPrice(),
                        "offer sell price",
                        true
                );
        }
        return null;
    }

    public void injectConfirmMenuEntry(MenuEntryAdded event) {
        if(!config.disableLeftClickConfirm()) {
            return;
        }

        if (!grandExchange.isOpen()) {
            return;
        }

        if(offerDetailsCorrect()) {
            return;
        }

        if(event.getOption().equals("Confirm") && grandExchange.isSlotOpen()) {
            log.debug("Adding deprioritized menu entry for offer");
            client.getMenu()
                    .createMenuEntry(-1)
                    .setOption("Nothing");

            event.getMenuEntry().setDeprioritized(true);
        }
    }

    public void injectSlotActionSwapMenuEntry(MenuEntryAdded event) {
        if (!config.slotActionSwap()) {
            return;
        }

        if (!grandExchange.isOpen() || grandExchange.isSlotOpen()) {
            return;
        }

        Suggestion suggestion = suggestionManager.getSuggestion();
        if (suggestion == null) {
            return;
        }

        if (!suggestion.isAbortSuggestion() && !suggestion.isModifySuggestion()) {
            return;
        }

        Widget slotWidget = grandExchange.getSlotWidget(suggestion.getBoxId());
        if (slotWidget == null || slotWidget.getId() != event.getActionParam1()) {
            return;
        }

        String target = suggestion.isAbortSuggestion() ? "Abort offer" : "Modify offer";
        if (! event.getOption().equals(target)) {
            event.getMenuEntry().setDeprioritized(true);
        }
    }

    private boolean offerDetailsCorrect() {
        Suggestion suggestion = suggestionManager.getSuggestion();
        if (suggestion == null) {
            return false;
        }
        String offerType = grandExchange.isOfferTypeSell() ? "sell" : "buy";
        if (client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH) == suggestion.getItemId() && offerType.equals(suggestion.offerType())) {
            return grandExchange.getOfferPrice() == suggestion.getPrice()
                    && grandExchange.getOfferQuantity() == suggestion.getQuantity();
        } else if (client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH) == offerManager.getViewedSlotItemId()
                && offerManager.getViewedSlotItemPrice() > 0) {
            return grandExchange.getOfferPrice() == offerManager.getViewedSlotItemPrice();
        }
        return false;
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.config.FlippingCopilotConfig;
import com.flippingcopilot.model.*;
import com.flippingcopilot.rs.CopilotLoginRS;
import com.flippingcopilot.rs.PortfolioStateRS;
import com.flippingcopilot.ui.*;
import com.flippingcopilot.ui.flipsdialog.FlipsDialogController;
import com.flippingcopilot.ui.graph.model.Data;
import com.flippingcopilot.ui.graph.model.PriceLine;
import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.Notifier;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageBuilder;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import java.util.function.Consumer;


@Slf4j
@Getter
@Setter
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SuggestionController {

    private static final String DUMP_ALERT_SOUND = "/alert-sound.wav";

    // dependencies
    private final PausedManager pausedManager;
    private final Client client;
    private final AudioPlayer audioPlayer;
    private final OsrsLoginManager osrsLoginManager;
    private final HighlightController highlightController;
    private final GrandExchange grandExchange;
    private final ApiRequestHandler apiRequestHandler;
    private final Notifier notifier;
    private final OfferManager offerManager;
    private final CopilotLoginRS copilotLoginRS;
    private final ClientThread clientThread;
    private final FlippingCopilotConfig config;
    private final SuggestionManager suggestionManager;
    private final AccountStatusManager accountStatusManager;
    private final GrandExchangeUncollectedManager uncollectedManager;
    private final PortfolioStateRS portfolioStateRS;
    private final FlipsDialogController flipDialogController;
    private final GePreviousSearch gePreviousSearch;


    private MainPanel mainPanel;
    private LoginPanel loginPanel;
    private CopilotPanel copilotPanel;
    private SuggestionPanel suggestionPanel;

    public void skipSuggestion() {
        if (accountStatusManager.skipCurrentSuggestion()) {
            if (suggestionPanel != null) {
                suggestionPanel.refresh();
            }
        }
    }

    public void togglePause() {
        if (pausedManager.isPaused()) {
            pausedManager.setPaused(false);
            suggestionManager.setSuggestionNeeded(true);
            suggestionPanel.refresh();
        } else {
            pausedManager.setPaused(true);
            highlightController.removeAll();
            suggestionPanel.refresh();
        }
    }

    void onGameTick() {
        if(suggestionManager.isSuggestionRequestInProgress() || suggestionManager.isGraphDataReadingInProgress()) {
            return;
        }
        // There is a race condition when the collect button is hit at the same time as offers fill.
        // In such a case we can end up with the uncollectedManager falsely thinking there is items to collect.
        // We identify if this has happened here by checking if the collect button is actually visible.
        if(isUncollectedOutOfSync()) {
            log.warn("uncollected is out of sync, it thinks there are items to collect but the GE is open and the Collect button not visible");
            uncollectedManager.clearAllUncollected(osrsLoginManager.getAccountHash());
            suggestionManager.setSuggestionNeeded(true);
        }
        // on initial login the state of the GE offers isn't correct we need to wait a couple ticks before requesting a suggestion
        if (osrsLoginManager.hasJustLoggedIn()) {
            return;
        }
        if (shouldFetchNewSuggestion()) {
            getSuggestionAsync();
        }
    }

    private boolean shouldFetchNewSuggestion() {
        if (client.getTickCount() < suggestionManager.suggestionsDelayedUntil) {
            return false;
        }
        Suggestion p = suggestionManager.getSuggestion();
        if(grandExchange.isSlotOpen() && !suggestionActionedOrVeryOutOfDate(p)) {
            return false;
        }

        return suggestionManager.isSuggestionNeeded() || suggestionManager.suggestionOutOfDate();
    }

    private boolean suggestionActionedOrVeryOutOfDate(Suggestion p) {
        if (p == null || p.isWaitSuggestion()) {
            return true;
        }
        if (p.actionedTick != -1 && p.actionedTick < client.getTickCount()) {
            return true;
        }
        return suggestionManager.suggestionVeryOutOfDate();
    }

    private boolean isUncollectedOutOfSync() {
        if (client.getTickCount() <= uncollectedManager.getLastUncollectedAddedTick() + 2) {
            return false;
        }
        if(!grandExchange.isHomeScreenOpen() || grandExchange.isCollectButtonVisible()) {
            return false;
        }
        if(uncollectedManager.HasUncollected(osrsLoginManager.getAccountHash())) {
            return true;
        }
        if(suggestionPanel.isCollectItemsSuggested()) {
            return true;
        }
        return false;
    }

    public void getSuggestionAsync() {
        suggestionManager.setSuggestionNeeded(false);
        if (!copilotLoginRS.get().isLoggedIn() || !osrsLoginManager.isValidLoginState()) {
            suggestionManager.setSuggestionRefreshPending(false);
            return;
        }
        if (suggestionManager.isSuggestionRequestInProgress()) {
            return;
        }
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        if (accountStatus == null) {
            suggestionManager.setSuggestionRefreshPending(false);
            return;
        }
        Suggestion oldSuggestion = suggestionManager.getSuggestion();
        if (oldSuggestion != null && oldSuggestion.isRecentUnActionedDumpAlert()) {
            suggestionManager.setSuggestionRefreshPending(false);
            return;
        }
        suggestionManager.setSuggestionRequestInProgress(true);
        suggestionManager.setSuggestionRefreshPending(false);
        boolean skipGraphData = config.lowDataMode();
        suggestionManager.setGraphDataReadingInProgress(!skipGraphData);
        Consumer<Suggestion> suggestionConsumer = (newSuggestion) -> handleSuggestionReceived(oldSuggestion, newSuggestion, accountStatus);
        Consumer<Data> graphDataConsumer = (d) -> {
            SwingUtilities.invokeLater(() -> {
                if (flipDialogController.priceGraphPanel != null) {
                    flipDialogController.priceGraphPanel.setSuggestionPriceData(d);
                }
            });
            suggestionManager.setGraphDataReadingInProgress(false);
        };
        Consumer<HttpResponseException> onFailure = (e) -> {
            suggestionManager.setSuggestion(null);
            suggestionManager.setSuggestionError(e);
            suggestionManager.setSuggestionRequestInProgress(false);
            suggestionManager.setGraphDataReadingInProgress(false);
            if (e.getResponseCode() == 401) {
                copilotLoginRS.clear();
                mainPanel.refresh();
                loginPanel.showLoginErrorMessage("Login timed out. Please log in again");
            } else {
                suggestionPanel.refresh();
            }
        };
        suggestionPanel.refresh();
        log.debug("tick {} getting suggestion", client.getTickCount());
        boolean sendGraphData = config.priceGraphWebsite() == FlippingCopilotConfig.PriceGraphWebsite.FLIPPING_COPILOT && !config.lowDataMode();
        boolean geOpen = grandExchange.isOpen();
        apiRequestHandler.getSuggestionAsync(accountStatus.encodeProto(geOpen, sendGraphData), suggestionConsumer, graphDataConsumer, onFailure);
    }

    void handleDumpSuggestion(Suggestion suggestion) {
        AccountStatus accountStatus = accountStatusManager.getAccountStatus();
        if (accountStatus == null) {
            log.info("discarding dump suggestion as account status null");
            return;
        }
        Suggestion s = suggestionManager.getSuggestion();
        if(s != null && s.isDumpAlert && s.actionedTick == -1) {
            log.info("discarding dump suggestion as already processing dump suggestion");
            return;
        }
        if (accountStatus.emptySlotExists()) {
            handleSuggestionReceived(suggestionManager.getSuggestion(), suggestion, accountStatus);
        } else {
            log.info("discarding dump suggestion as no free slot");
        }
    }

    private synchronized void handleSuggestionReceived(Suggestion oldSuggestion, Suggestion newSuggestion, AccountStatus accountStatus) {
        if (!newSuggestion.isDumpAlert && !suggestionManager.isSuggestionRequestInProgress()) {
            // this is the edge case when a dump suggestion is received whilst a standard request is in progress
            log.info("discarding suggestion as not dump alert and no request in progress {}", newSuggestion);
            return;
        }
        if (newSuggestion.isBuyDumpSuggestion() && config.dumpAlertSound()) {
            playDumpAlertSound();
        }
        suggestionManager.setSuggestion(newSuggestion);
        portfolioStateRS.updatePortfolioState(
                newSuggestion.getBankItems(),
                newSuggestion.getPortfolioItems(),
                accountStatus.getOffers(),
                accountStatus.getUncollected(),
                newSuggestion.getTimeIssued()
        );
        suggestionManager.setSuggestionError(null);
        suggestionManager.setSuggestionRequestInProgress(false);
        log.debug("Received suggestion: {}", newSuggestion.toString());
        accountStatusManager.resetSkipSuggestion();
        offerManager.setOfferJustPlaced(false);
        suggestionPanel.refresh();
        showNotifications(oldSuggestion, newSuggestion, accountStatus);
        if (!newSuggestion.isWaitSuggestion()) {
            SwingUtilities.invokeLater(() -> {
                if (flipDialogController.priceGraphPanel != null) {
                    flipDialogController.priceGraphPanel.newSuggestedItemId(
                            newSuggestion.getItemId(),
                            buildPriceLine(newSuggestion)
                    );
                }
            });
        } else {
            SwingUtilities.invokeLater(() -> {
                if (flipDialogController.priceGraphPanel != null) {
                    flipDialogController.priceGraphPanel.suggestedPriceLine = null;
                }
            });
        }
        if (client.getVarcIntValue(VarClientInt.INPUT_TYPE) == 14) {
            clientThread.invokeLater(gePreviousSearch::showSuggestedItemInSearch);
        }
    }

    private void playDumpAlertSound() {
        try {
            audioPlayer.play(SuggestionController.class, DUMP_ALERT_SOUND, 0);
        } catch (Exception e) {
            log.warn("failed to play dump alert sound", e);
        }
    }

    private PriceLine buildPriceLine(Suggestion suggestion) {
        if (suggestion.isBuySuggestion()) {
            return new PriceLine(
                    suggestion.getPrice(),
                    "Suggested buy price",
                    false
            );
        }
        if (suggestion.isSellSuggestion()) {
            return new PriceLine(
                    suggestion.getPrice(),
                    "Suggested sell price",
                    true
            );
        }
        return null;
    }

    void showNotifications(Suggestion oldSuggestion, Suggestion newSuggestion, AccountStatus accountStatus) {
        if (shouldNotify(newSuggestion, oldSuggestion)) {
            String msg = newSuggestion.toMessage();
            if (config.enableTrayNotifications()) {
                notifier.notify(msg);
            }
            if (!copilotPanel.isShowing() && config.enableChatNotifications()) {
                showChatNotifications(newSuggestion, accountStatus);
            }
        }
    }

    static boolean shouldNotify(Suggestion newSuggestion, Suggestion oldSuggestion) {
        if (newSuggestion.isWaitSuggestion()) {
            return false;
        }
        if (oldSuggestion != null && newSuggestion.equals(oldSuggestion)) {
            return false;
        }
        return true;
    }

    private void showChatNotifications(Suggestion newSuggestion, AccountStatus accountStatus) {
        if (accountStatus.isCollectNeeded(newSuggestion, grandExchange.isSetupOfferOpen())) {
            clientThread.invokeLater(() -> showChatNotification("Flipping Copilot: Collect items"));
        }
        clientThread.invokeLater(() -> showChatNotification(newSuggestion.toMessage()));
    }

    private void showChatNotification(String message) {
        String chatMessage = new ChatMessageBuilder()
                .append(config.chatTextColor(), message)
                .build();
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", chatMessage, "");
    }
}

package com.flippingcopilot.controller;


import com.flippingcopilot.model.DumpAlert;
import com.flippingcopilot.model.Suggestion;
import com.flippingcopilot.rs.*;
import com.google.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import okhttp3.Call;
import okhttp3.Response;
import okio.BufferedSource;

import javax.inject.Inject;
import java.io.IOException;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicReference;

@Slf4j
@Singleton
public class DumpsStreamController {

    // a dump alert is a few hundred bytes; anything near this is a framing bug
    private static final long MAX_FRAME_BYTES = 1 << 20;

    private final ClientThread clientThread;
    private final ApiRequestHandler apiRequestHandler;
    private final SuggestionController suggestionController;
    private final AtomicReference<Call> activeCall = new AtomicReference<>();
    private final ReactiveState<String> subscribedDisplayName;

    @Inject
    public DumpsStreamController(ClientThread clientThread,
                                 ApiRequestHandler apiRequestHandler,
                                 SuggestionController suggestionController,
                                 AccountSuggestionPreferencesRS accountSuggestionPreferencesRS,
                                 OsrsLoginRS osrsLoginRS,
                                 CopilotLoginRS copilotLoginRS,
                                 GrandExchangeOpenRS grandExchangeOpenRS) {
        this.clientThread = clientThread;
        this.apiRequestHandler = apiRequestHandler;
        this.suggestionController = suggestionController;
        this.subscribedDisplayName = ReactiveStateUtil.derive(
                copilotLoginRS,
                osrsLoginRS,
                accountSuggestionPreferencesRS,
                grandExchangeOpenRS,
                (copilotLoginState, loginState, preferences, isGrandExchangeOpen) -> {
                    if (!loginState.loggedIn
                            || loginState.displayName == null
                            || loginState.displayName.isBlank()
                            || !copilotLoginState.isLoggedIn()
                            || !preferences.isReceiveDumpSuggestions()
                            || !Boolean.TRUE.equals(isGrandExchangeOpen)) {
                        return null;
                    }
                    return loginState.displayName;
                });
        subscribedDisplayName.registerListener(name -> {
            if (name != null) {
                consumeDumps();
            } else {
                ensureUnsubscribed();
            }
        });
    }

    public void ensureUnsubscribed() {
        Call call = activeCall.getAndSet(null);
        if (call != null) {
            call.cancel();
        }
    }

    private void consumeDumps() {
        String displayName = subscribedDisplayName.get();
        if(displayName != null) {
            Call previous = activeCall.get();
            Call call = apiRequestHandler.asyncConsumeDumpAlerts(displayName,
                    this::consumeDumpStream,
                    error -> {
                        log.warn("dump alerts connection failed, re-connecting: {}", error.getMessage());
                        consumeDumps();
                    }
            );
            log.info("{} subscribing to dumps", displayName);
            if (activeCall.getAndSet(call) != previous || subscribedDisplayName.get() == null) { // catches race edge case
                ensureUnsubscribed();
            }
        }
    }

    // each frame is a uvarint byte length followed by that many bytes of an encoded DumpAlert; a zero-length frame is the keepalive
    private void consumeDumpStream(Response response) {
        try (Response resp = response) {
            BufferedSource source = resp.body().source();
            while (activeCall.get() != null) {
                long length = readUvarint(source);
                if (length == 0) {
                    continue;
                }
                // a negative length means the uvarint overflowed, and readByteArray would then throw an unchecked exception
                if (length < 0 || length > MAX_FRAME_BYTES) {
                    throw new IOException("invalid dump frame length: " + length);
                }
                handleDumpMessage(source.readByteArray(length));
            }
        } catch (IOException e) {
            String displayName = subscribedDisplayName.get();
            if (displayName != null) {
                log.warn("dump alerts stream error", e);
                consumeDumps();
            } else {
                log.info("consumeDumpStream ended gracefully");
            }
        }
    }

    private static long readUvarint(BufferedSource source) throws IOException {
        long value = 0;
        for (int shift = 0; shift < 64; shift += 7) {
            int b = source.readByte() & 0xFF;
            value |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return value;
            }
        }
        throw new IOException("dump frame length is not a valid uvarint");
    }

    private void handleDumpMessage(byte[] data) throws IOException {
        Suggestion suggestion = DumpAlert.decodeProto(data).suggestion;
        if (suggestion == null) {
            log.warn("dump suggestion decode failed");
            return;
        }
        suggestion.setMessage("<html><b><font color=#FA4A4B>Dump alert!!</font></b></html>");
        suggestion.setDumpAlert(true);
        suggestion.setDumpAlertReceived(Instant.now());
        clientThread.invoke(() -> suggestionController.handleDumpSuggestion(suggestion));
        log.info("received dump suggestion {} {}", suggestion.getName(), suggestion.getType());
    }

}

package com.flippingcopilot.controller;

import com.flippingcopilot.ui.PatchNotesPopup;
import com.flippingcopilot.ui.UIUtilities;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Singleton;
import javax.swing.*;
import java.awt.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

@Singleton
@Slf4j
public class PatchNotesController {

    static final String PATCH_NOTES_VERSION_FILE = "patch-notes-version.txt";

    public void maybeShowOnStartup(Component parent, boolean hadExistingInstallation) {
        if (!UIUtilities.ensureEdt(() -> maybeShowOnStartup(parent, hadExistingInstallation))) return;

        int latestVersion = PatchNotesPopup.LATEST_VERSION;
        Integer lastSeenVersion = loadLastSeenVersion();
        boolean shouldShow = shouldShowPatchNotes(latestVersion, lastSeenVersion, hadExistingInstallation);
        persistSeenVersion(lastSeenVersion == null ? latestVersion : Math.max(lastSeenVersion, latestVersion));

        if (!shouldShow || GraphicsEnvironment.isHeadless()) {
            return;
        }

        Window owner = parent == null ? null : SwingUtilities.getWindowAncestor(parent);
        PatchNotesPopup.show(owner != null ? owner : parent);
    }

    static boolean shouldShowPatchNotes(int currentVersion, Integer lastSeenVersion, boolean hadExistingInstallation) {
        if (lastSeenVersion != null) {
            return currentVersion > lastSeenVersion;
        }
        return hadExistingInstallation;
    }

    private Integer loadLastSeenVersion() {
        Path patchNotesVersionPath = patchNotesVersionPath();
        if (!Files.exists(patchNotesVersionPath)) {
            return null;
        }

        try {
            String rawVersion = Files.readString(patchNotesVersionPath, StandardCharsets.UTF_8).trim();
            return rawVersion.isEmpty() ? null : Integer.parseInt(rawVersion);
        } catch (IOException | NumberFormatException e) {
            log.warn("error loading patch notes version from {}", patchNotesVersionPath, e);
            return null;
        }
    }

    private void persistSeenVersion(int version) {
        Path patchNotesVersionPath = patchNotesVersionPath();

        try {
            Files.writeString(patchNotesVersionPath, Integer.toString(version), StandardCharsets.UTF_8);
        } catch (IOException e) {
            log.warn("error saving patch notes version to {}", patchNotesVersionPath, e);
        }
    }

    private Path patchNotesVersionPath() {
        return Persistance.COPILOT_DIR.toPath().resolve(PATCH_NOTES_VERSION_FILE);
    }
}

package com.flippingcopilot.controller;

import com.flippingcopilot.config.FlippingCopilotConfig;
